            ["eyrie"] = new EngineDef("eyrie", "Eyrie Dynasties", "faction", "base", new[] { "warriors per clearing", "roosts per clearing", "ruler of each clearing, counting Lords of the Forest ties", "Decree cards and current leader", "Turmoil" }),
            ["alliance"] = new EngineDef("alliance", "Woodland Alliance", "faction", "base", new[] { "sympathy tokens per clearing", "bases on the map, by suit", "warriors per clearing", "officers", "supporters" }),
            ["vagabond-tinker"] = new EngineDef("vagabond-tinker", "Vagabond (Tinker)", "vagabond", "base", new[] { "pawn location (clearing or forest)", "items with damaged and exhausted state", "relationship with each non-Vagabond faction", "coalition partner", "completed quests by suit" }),
            ["vagabond-ranger"] = new EngineDef("vagabond-ranger", "Vagabond (Ranger)", "vagabond", "base", new[] { "pawn location (clearing or forest)", "items with damaged and exhausted state", "relationship with each non-Vagabond faction", "coalition partner", "completed quests by suit" }),
            ["vagabond-thief"] = new EngineDef("vagabond-thief", "Vagabond (Thief)", "vagabond", "base", new[] { "pawn location (clearing or forest)", "items with damaged and exhausted state", "relationship with each non-Vagabond faction", "coalition partner", "completed quests by suit" }),
            ["riverfolk"] = new EngineDef("riverfolk", "Riverfolk Company", "faction", "riverfolk", new[] { "warriors per clearing", "trade posts per clearing", "funds and payments", "services bought" }),
            ["lizards"] = new EngineDef("lizards", "Lizard Cult", "faction", "riverfolk", new[] { "warriors per clearing", "gardens per clearing, by suit", "Outcast suit", "acolytes", "Lost Souls pile" }),
            ["duchy"] = new EngineDef("duchy", "Underground Duchy", "faction", "underworld", new[] { "warriors per clearing", "warriors in the Burrow", "tunnels per clearing", "citadels and markets per clearing", "swayed ministers" }),
            ["corvids"] = new EngineDef("corvids", "Corvid Conspiracy", "faction", "underworld", new[] { "warriors per clearing", "plot tokens per clearing, face up or face down", "type of each face-up plot", "ruler of each clearing" }),
            ["hundreds"] = new EngineDef("hundreds", "Lord of the Hundreds", "faction", "marauder", new[] { "Warlord location", "warriors per clearing", "strongholds per clearing", "mob tokens per clearing", "Hoard items", "current mood" }),
            ["keepers"] = new EngineDef("keepers", "Keepers in Iron", "faction", "marauder", new[] { "relic tokens per forest and clearing, by type", "relic values once face up", "recovered relics by type", "waystations and their faces", "warriors per clearing", "Retinue cards" }),
        };

        public static readonly IReadOnlyDictionary<string, CharacterDef> Characters = new Dictionary<string, CharacterDef>
        {
            ["gustave"] = new CharacterDef("gustave", "Gustave", "Gustave", "marquise", true, 4, "win.gustave", "bot.gustave", "role.lumiere", new[] { "paintress", "white-haired-man" }, "asset.portrait.gustave", "#3A6EA5", true, "An engineer from Lumière in his last year, leading Expedition 33 across the Continent. He rides the Marquise de Cat from an Expedition Camp in Lumière. Plant Expedition Flags as you build, charge Gustave's Arm in fights you choose, and hold a road of ruled, flagged clearings from Lumière to the Monolith's doorstep that covers all three suits.", "He leads Act I. He is an engineer from Lumière, 32 years old, in his last year before his Gommage. With his sister Emma, Lumière's Chief Councillor, he is Maelle's guardian. After the landing massacre he regroups the survivors and leads them toward the Paintress. [Act I ending spoiler] He is killed at the end of Act I protecting Maelle. The expedition's motto about those who come after is his creed.", "Gustave's goal is to reach and stop the Paintress before his own Gommage, protect Maelle and leave something behind for those who come after. His verified combat signature is Overcharge: his mechanical arm builds charge as he fights and releases a lightning strike. E33 counts up to 10 charges, which 3 pips abstract. Expedition Flags are E33's real checkpoints, so a flagged road is his legacy in Root form. He dies at the end of Act I before reaching the Monolith, so his road ends at its doorstep. Feasibility changes from the merged draft: flags alone no longer win (he must currently rule the Chain, like a supply line); the arm charges only from fights he picks; the Beachhead needs a building; the Chain must span three suits; and the Beach vignette no longer adds charge. Name fixes: the gauge is 'Gustave's Arm', after the official replica, instead of the unverified 'Lumina Converter', and Emma is 'his sister' because 'twin' is unverified."),
            ["esquie"] = new CharacterDef("esquie", "Esquie", "Esquie", "vagabond-tinker", true, 5, "win.esquie", "bot.esquie", "role.esquies-nest", new[] { "clea" }, "asset.portrait.esquie", "#8FC7E8", true, "A huge, cheerful friend who can carry the expedition anywhere, once he finds his four lost magic rocks. He rides the Tinker Vagabond and never gets angry: he only fights the guards sitting on his rocks. Bring Florrie, Dorrie, Soarrie and Urrie home and he wins, no VP needed.", "Esquie is how the expedition crosses the Continent: a huge, cheerful creature whose lost magic rocks unlock swimming, coral-breaking, flying and diving. Without them the party cannot cross the sea, fly up to the Paintress at the end of Act II, or reach the deepest areas. [finished] Young Verso Dessendre painted him from his favourite stuffed toy, so Esquie is a piece of the imagination the Canvas came from.", "The user's 'nuts' are Esquie's four magic rocks: Florrie (swim), Dorrie (break coral), Soarrie (fly) and Urrie (dive). Nothing in E33 is called nuts. The user's spirit holds up in the lore, with corrected placements. Esquie blames François for Florrie and the party fights him at the Nest, but Florrie itself is recovered at Stone Wave Cliffs, Act I's last area, where the Lampmaster is fought. So Florrie spawns guarded at the Cliffs and François becomes a decoy joke. Dorrie turns up in Old Lumière in Act II, after the fight with painted Renoir there, so it is a ruin find blocked while Renoir's warriors hold the clearing. The draft's 'Sciel finds it' was dropped as unconfirmed. Verso already has Soarrie at the top of the Monolith and gives it to Esquie for the Paintress fight, so it comes from Verso or from whoever holds the Monolith. After Act II François refuses to trade Urrie and is beaten in a rematch, so Urrie spawns guarded at the Nest late. Clea hosts the guards when seated because as children Clea rode François while Verso rode Esquie. Never Mad and Friends Not Foes reflect his never-angry nature, and the rock powers are his real traversal unlocks."),
            ["paintress"] = new CharacterDef("paintress", "The Paintress", "Aline Dessendre", "eyrie", true, 1, "win.paintress", "bot.paintress", "role.monolith", new[] { "gustave", "curator" }, "asset.portrait.paintress", "#9E1B32", true, "Every year she paints a lower number on the Monolith, and every expedition, Expedition 33 included, sets out to stop her. She rides the Eyrie Dynasties from an easel in the Monolith, bound by her own Canvas Plan. Hold the Monolith and keep three Living Portraits, one in each suit, ruled and guarded.", "She paints the falling number on the Monolith that every expedition, Expedition 33 included, sets out to stop, and she is the final boss of Act II. [finished] She is Aline Dessendre, the grieving mother of Verso, Clea and Alicia. She entered her dead son's Canvas, refused to leave, and painted copies of her family to live with.", "The user suggested she spawn '3 of herself in different areas', but the lore does not have Aline copying herself. Inside the Canvas she painted copies of three family members, Verso, Clea and Renoir, and stayed at the top of the Monolith. The real Alicia entered later and was repainted as a newborn, Maelle, so there is no painted Alicia to place; the draft's Alicia portrait and Maelle exclusion are removed. The spirit is kept: three of her creations spread across three regions while she holds the Monolith, and each easel shows her painting, so she still appears across the map. Eyrie's rigid Decree and Turmoil fit a grieving painter bound by her own plan. Feasibility fix: portraits are worked out at each check instead of being used up when a roost is placed, so she can never lock herself out. Lore fixes: the unverified 'head of the Painters' Council' title is not used (the Despot leader is The Matriarch), and no text says she does the erasing, since late-game lore credits that to the real Renoir and treats her number as a countdown."),
            ["sciel"] = new CharacterDef("sciel", "Sciel", "Sciel", "alliance", true, 2, "win.sciel", "bot.sciel", null, Array.Empty<string>(), "asset.portrait.sciel", "#D9A441", true, "A warm farmer-turned-teacher who joined Expedition 33 to give Lumière's children a future. She rides the Woodland Alliance: light Lanterns in quiet clearings, keep an Aquafarm standing, and hold five Sanctuaries across all three suits.", "A warm farmer-turned-teacher in her last year, and the best friend of Sophie, who is gommaged in the Prologue. She worked the Aquafarm with Gustave and Sophie, lost her husband Pierre and their unborn child, and volunteered for Expedition 33 to spare Lumière's children the same future. She is playable from Act I to Act III. [Act II ending spoiler] She is gommaged at the end of Act II and brought back by Maelle.", "Sciel wants to spare Lumière's youth, and she is a farmer and teacher who worked the Aquafarm. Her verified combat signature: applying Foretell gives a Sun charge, consuming it gives a Moon charge, and holding both triggers Twilight. Sun (safe places) and Moon (Aquafarms) make her a protector rather than a generic Alliance. Feasibility fix: the Birdsong confirmation counts Lanterns still standing without enemy buildings or tokens, so walking a warrior in no longer erases the win; you have to remove a Lantern or raze an Aquafarm, which is the Alliance's real counterplay. Tone fix: the draft's joke about Pierre was replaced with a warm line, since his death and her grief are serious parts of her story."),
            ["verso"] = new CharacterDef("verso", "Verso", "Verso", "vagabond-ranger", true, 6, "win.verso", "bot.verso", null, new[] { "maelle" }, "asset.portrait.verso", "#4B3F72", true, "A calm stranger with a sword and a pistol who seems to know the Continent far too well. He rides the Ranger Vagabond: take only clean fights to climb his public Perfection rank from D to S, then stand alone in the Monolith.", "The immortal stranger who saves the survivors. He leads Act II and is central to Act III and to one of the two endings. [Act I ending spoiler] He arrives after Gustave dies. [Act II/III spoiler] He is a painted copy of the real Verso Dessendre, and he knows it. The Canvas is the real Verso's childhood painting and holds the last fragment of his soul. He fought in Expedition Zero, where painted Renoir was his commander.", "Verso's verified combat signature is Perfection: a D-to-S grade that climbs with clean hits, dodges and parries and drops when he is hurt. He is immortal, knows he is painted, and wants to end the Canvas so that his mother leaves and the real Verso's soul fragment can rest. He reveals Soarrie at the top of the Monolith. A rank-S Verso standing alone in the Monolith is that ending in Root form, and the Ranger's self-repair is his immortality. Feasibility fix: the Birdsong confirmation now asks only that he still stands there at rank S, so the answer is landing a hit, which is exactly what breaks Perfection in E33. The old 'Monolith still empty' test was nearly unwinnable against a seated Paintress and spoiler bots. Lore fix: he leads Act II, not Act III, which is Maelle's."),
            ["maelle"] = new CharacterDef("maelle", "Maelle", "Alicia Dessendre", "vagabond-thief", true, 3, "win.maelle", "bot.maelle", null, new[] { "verso" }, "asset.portrait.maelle", "#E0703A", true, "Gustave's sixteen-year-old foster sister and Expedition 33's youngest member, looking for somewhere to belong. She rides the Thief Vagabond as a fencer: win two factions over as allies, make no enemies, and hold her ground in Lumière with her gear intact.", "Gustave's 16-year-old foster sister and the youngest member of Expedition 33, an orphan who never felt she belonged in Lumière. Act III is named after her. [Act III spoiler] She learns she is Alicia Dessendre, the Paintress's youngest daughter, returns as a Painter, brings back Lune and Sciel, and fights to keep the painted world and her friends alive.", "Maelle's arc is about belonging. The orphan who never fit in Lumière joins the expedition to find a place, and in Act III she learns she is Alicia and chooses to keep the painted world and the people she loves. Root's Vagabond is the outsider whose relationships with every faction are its core loop. Her verified stance system becomes the stance chip and the Defensive requirement of 3 undamaged items. Lore fix: nothing in E33 makes her a thief, so Steal is reskinned as a fencer's Disarm, and the Ronin's Swift Strike is her riposte. Feasibility fixes: Alicia Awakens is now cosmetic, with no scripted relationship bump, and a 2-player game needs 15 VP because one Allied faction is easy."),
            ["lune"] = new CharacterDef("lune", "Lune", "Lune", "keepers", false, 7, "win.lune", "bot.lune", null, Array.Empty<string>(), "asset.portrait.lune", "#2F7F7A", true, "The expedition's scholar and pathfinder, carrying her parents' unfinished research. She rides the Keepers in Iron (The Marauder Expansion): from Act II, recover a Journal, a Route Chart and a Chroma Sample, one of them the Parents' Journal that glows gold beside Sirène.", "She is the expedition's scholar, mage and pathfinder, trusted to chart the route. Her parents, renowned researchers, left on Expedition 46 and never came back, and she carries their unfinished work. She wants to understand the Gommage rather than just survive it. She is playable from Act I to Act III. [Act II ending spoiler] She is gommaged at the end of Act II and brought back by Maelle.", "Lune is the scholar and pathfinder carrying her parents' unfinished research, and journals of past expeditions are real E33 collectibles. Her parents were on Expedition 46, and her relationship quest leads to the Sirène area where that expedition's trail ends, so the Journal lies beside the Sirène Axon. This is a lore fix: the draft used a generic spot next to the Monolith. Keepers in Iron is Root's 'recover lost things from the woods' faction, and Stains are her verified combat signature. Feasibility fixes: the Act II gate is now in the win text, the Journal is tagged only at the start of Act II, and the highest-value tablet is tagged instead of an exact value-3 one that may not exist."),
            ["monoco"] = new CharacterDef("monoco", "Monoco", "Monoco", "hundreds", false, 8, "win.monoco", "bot.monoco", null, Array.Empty<string>(), "asset.portrait.monoco", "#7A9A3A", true, "A battle-loving Gestral who learns by taking the feet of the Nevrons he beats. He rides the Lord of the Hundreds (The Marauder Expansion): fill the five-slot Bestial Wheel with feet from at least three factions, and keep his Warlord standing.", "A battle-loving Gestral and an old friend of Verso and Esquie. He is recruited in Act II at his mountain station after you beat him in a duel and then defeat the Stalact. He learns by defeating specific marked Nevrons and taking their feet, and fights in their forms on the Bestial Wheel of masks. His questline ends at the Sacred River, where his friend Noco is brought back.", "Monoco's verified signature: he defeats specific marked Nevrons, takes their feet, and fights in their forms through the Bestial Wheel of masks Agile, Caster, Balanced, Heavy and Almighty, treating battle as thrill and meditation. The Sacred River, where dead Gestrals are reborn with most memories gone, frames losing feet when the Warlord falls, and his friend Noco is brought back there in his questline. Feasibility fixes: a 10 VP gate, feet from at least 3 factions, a harder Almighty and a Birdsong confirmation, so he is no longer the fastest unanswerable winner. Lore fixes: Noco is 'his friend' because 'protégé' is unverified, the unconfirmed rescue claim is dropped, and his barks are in the first person in a polite-brawler voice."),
            ["curator"] = new CharacterDef("curator", "The Curator", "Renoir Dessendre", "duchy", false, 9, "win.curator", "bot.curator", null, new[] { "paintress" }, "asset.portrait.curator", "#8A8A99", true, "A faceless figure at camp who quietly upgrades the expedition's weapons. He rides the Underground Duchy (The Underworld Expansion) and works patiently from below. His goal, which unlocks only in Act III: end the painting from Lumière.", "The faceless figure at camp who quietly upgrades the expedition's weapons. [Act III spoiler] He is really Renoir Dessendre, father of the family, trapped beneath the Monolith since the Fracture. He helped Expedition 33 get Aline expelled, then his power gommages Lumière, and he is the final boss of Act III.", "The real Renoir has been trapped beneath the Monolith since the Fracture caused by his clash with Aline, and acts through the faceless Curator form. He quietly upgrades the expedition's weapons so they can get Aline expelled. Then his power gommages Lumière, and he is fought there as the final boss. Sources say his power does the erasing. The Duchy's off-map Burrow is that prison, and the win is the exact sequence: Aline out, him out, Lumière taken. Quiet Helper is the weapon upgrades. Feasibility fix: the Cell Crack stays inert until Act III, so he has no turn-1 Burrow access to the Paintress's home and no early tunnel cost; and when Lumière holds no keep, a token rule there is not enough. Lore fix: 'trapped since the Fracture' replaces 'imprisoned by Aline'."),
            ["clea"] = new CharacterDef("clea", "???", "Clea", "lizards", false, 10, "win.clea", "bot.clea", "role.flying-manor", new[] { "esquie" }, "asset.portrait.clea", "#6A1B4D", false, "Locked in spoiler-safe mode: a seat for players who have finished Clair Obscur: Expedition 33. Rides the Lizard Cult (The Riverfolk Expansion) from the Flying Manor, and wins by spreading her pieces across eight clearings, the Monolith among them.", "[finished] The eldest Dessendre daughter. The real Clea, fighting the Writers outside the Canvas, wants the Canvas destroyed and sent Alicia in. She captured Aline's gentle painted Clea in the Flying Manor and repainted her into a tool that keeps producing the Nevrons that kill expeditions and drain Aline's chroma. Painted Clea is a secret superboss, and 'Clea Unleashed' joined the Endless Tower in the Thank You update.", "Sources say Clea painted the Nevrons to drain Aline's chroma so the Canvas could be erased. The real Clea captured Aline's gentle painted Clea in the Flying Manor and repainted her into the tool that keeps producing them. Nevrons across the Continent plus presence at the Monolith where Aline sits is that plan as board presence, and the Lizard Cult's Convert and Sanctify literally repaint enemy pieces. One seat covers both Cleas: the real one working through her captured copy. As children Clea rode François while Verso rode Esquie, so she is the natural owner of the guards on Esquie's rocks. Lore fix: the unverified 'Regent' title is removed. Feasibility fixes: her bot spreads through Recruit and Convert because the Lizards have no normal Move, and guard warriors never count toward her coverage."),
            ["white-haired-man"] = new CharacterDef("white-haired-man", "The White-Haired Man", "Painted Renoir", "corvids", false, 11, "win.white-haired-man", "bot.white-haired-man", null, new[] { "gustave" }, "asset.portrait.white-haired-man", "#D8D2C4", true, "The white-haired swordsman who meets every expedition on the shore. He rides the Corvid Conspiracy (The Underworld Expansion): ring the Monolith with warriors and Barrier plots so that nobody reaches the Paintress.", "The visible villain of Acts I and II. He massacres Expedition 33 when they land and guards the way to the Paintress. [Act II/III spoiler] He is Aline's painted copy of her husband and led Expedition Zero, where Verso calls him his former commander. He kills Gustave at the end of Act I and is erased at the Monolith.", "Painted Renoir's goal is to protect the Paintress and stop expeditions reaching her, which is why earlier expeditions vanished. His signature moments are the landing massacre, being effectively unbeatable in Act I, and guarding the Monolith. Corvid plots (bombs as massacres, snares as a barrier) and thin, everywhere-at-once warriors fit an ambusher who rings the Monolith. Feasibility fix: the Ring is judged by rule, not emptiness, so one walk-in no longer breaks it. Lore fixes: sources show him doing the massacre himself, so 'Renoir's Nevrons' is stated design liberty and the unconfirmed 'Noirs' name is gone (the Raid plot is now 'Ambush on the Shore'); the barrier imagery is also design liberty; and the bark no longer treats 'Expedition 33' as a headcount. He stays separate from the Curator, whose goal is the opposite."),
        };

