        public static readonly IReadOnlyDictionary<string, WinConditionDef> WinConditions = new Dictionary<string, WinConditionDef>
        {
            ["win.gustave"] = new WinConditionDef("win.gustave", "gustave", "The Road to the Monolith", "countdown", 2, 10, "From Act II with 10+ VP. At the end of each of his turns, every clearing he rules that holds one of his buildings gets a permanent Expedition Flag (Lumière starts flagged), but a flag only counts while he still rules that clearing. Gustave's Arm (0-3) gains a charge only when he starts a battle that removes an enemy piece; using Overcharge empties it. His Chain is the flagged clearings he rules that connect to Lumière by paths. The table is warned at the end of his turn if the Chain reaches a Beachhead (a clearing next to the Monolith) holding one of his buildings, covers fox, rabbit and mouse, his Arm is 3/3 and he has 10+ VP. He wins at the start of his next Birdsong if all of that still holds. 30 VP still wins.", "At hook.evening-end for the seat playing Gustave (Marquise). First the flags: every clearing c with Ruler(c) == seat and Buildings(seat, c) >= tune.gustave-flag-buildings is added to state.gustave.flags. Then the test: act >= 2, Vp(seat) >= tune.countdown-vp, ActiveDominance(seat) == null, and state.gustave.arm == tune.gustave-arm-max. Chain = breadth-first search from Lumière (state.global.roles[role.lumiere]) along PathNeighbours only (rivers are not paths), visiting only clearings that are in state.gustave.flags and have Ruler(c) == seat; if Lumière itself fails that, the Chain is empty. Pass when (1) some Chain clearing b is in PathNeighbours(Monolith) and has Buildings(seat, b) >= tune.gustave-beachhead-buildings, and (2) the union of SuitsOf(c) over the Chain holds tune.gustave-chain-suits distinct suits among fox, rabbit and mouse (a Lost City gives all three). A pass adds the seat to state.global.countdowns and shows the public banner.", "At hook.birdsong-start for his seat, before any Birdsong step, if the seat is in state.global.countdowns: rerun the same test on the current board and state (act, VP, no active dominance, Arm full, a ruled flagged Chain from Lumière reaching a Beachhead with his building, three suits). No new flags are planted. Pass: do.declare-winner. Fail: remove the seat from state.global.countdowns and clear the banner.", "Flip rule of any one Chain clearing (including Lumière), or remove the Beachhead's Marquise buildings, before his next Birdsong. Only his own Overcharge empties the Arm, and it must refill to 3 before he can announce again.", true, false, new Dictionary<string, string> { ["tune.countdown-vp"] = "10", ["tune.gustave-arm-max"] = "3", ["tune.gustave-chain-suits"] = "3", ["tune.gustave-flag-buildings"] = "1", ["tune.gustave-beachhead-buildings"] = "1" }, new[] { "state.gustave.flags", "state.gustave.arm", "state.gustave.overcharge-armed", "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters" }, new[] { "hook.setup-complete", "hook.battle-resolved", "hook.ui-toggle", "hook.evening-end", "hook.birdsong-start", "hook.load" }, new[] { "read.ruler", "read.buildings", "read.path-neighbours", "read.suits-of", "read.vp", "read.active-dominance", "read.clearings" }, new[] { "ui.gustave.flags", "ui.gustave.arm", "ui.gustave.road", "ui.global.countdown-banner", "ui.global.goal-tracker", "ui.gustave.ending" }, new[] { "GustaveWin_AnnouncesWithRuledThreeSuitChainToBeachhead", "GustaveWin_ConfirmFailsAfterChainClearingFlips", "GustaveWin_BlockedInActOneAndBelowTenVp", "GustaveWin_FlaggedButUnruledClearingBreaksChain" }),
            ["win.esquie"] = new WinConditionDef("win.esquie", "esquie", "Esquie's Rocks Come Home", "quest", 2, 0, "Bring all four of Esquie's rocks home and he wins at the end of any of his turns, with no VP needed. Florrie waits at Stone Wave Cliffs under 2 guards from the start; Dorrie hides in the Old Lumière ruin from Act II, and while the White-Haired Man's warriors stand in Old Lumière it cannot be picked up, by Exploring or otherwise; Soarrie appears in Act II on Verso's card, or with whoever rules the Monolith; Urrie waits at Esquie's Nest under 3 guards from Act III, or as soon as he holds the other three. Guards fall to anyone's battles; once a rock has no guards left, Esquie picks it up after any of his actions in that clearing. Claimed rocks are never lost. No win while he is in a coalition.", "At hook.evening-end for the seat playing Esquie: act >= 2 and CoalitionPartner(seat) == null, and the number of entries in state.esquie.rocks with Status == held is >= tune.esquie-rocks. Pass: do.declare-winner at once. Claims that feed it: after every Esquie action (hook.action-resolved), each loose rock whose Clearing == PawnClearing(seat) becomes held, except Dorrie while some seat s with EngineOf(s) == Corvids has Warriors(s, Old Lumière) >= 1; so does Soarrie while heldByRuler if Ruler(Monolith) == null and he stands in the Monolith; Explore of Old Lumière with act >= 2 makes Dorrie held unless Corvid warriors are there; Aiding Ruler(Monolith) while in the Monolith makes a heldByRuler Soarrie held; ending his turn in Verso's clearing makes a withVerso Soarrie held.", "None: a quest win takes effect at the end of the owner's turn, with no Birdsong confirmation.", "Keep host warriors stacked on the last guarded rock (more defenders deal more hits to him) and attack his pawn to damage items so he cannot fight; keep Corvid warriors in Old Lumière; hold the Monolith so he must Aid you for Soarrie. With the no-spawn fallback, keep any warriors in a rock's clearing.", true, true, new Dictionary<string, string> { ["tune.esquie-rocks"] = "4", ["tune.esquie-guards-florrie"] = "2", ["tune.esquie-guards-urrie"] = "3", ["tune.esquie-guard-spawns"] = "1" }, new[] { "state.esquie.rocks", "state.esquie.decoy", "state.global.act", "state.global.roles", "state.global.seat-characters" }, new[] { "hook.setup-complete", "hook.act-change", "hook.battle-resolved", "hook.piece-removed", "hook.action-resolved", "hook.explore-resolved", "hook.aid-resolved", "hook.piece-moved", "hook.evening-end", "hook.load" }, new[] { "read.pawn-clearing", "read.warriors", "read.ruler", "read.has-ruin", "read.seats", "read.seat-engine", "read.coalition-partner", "read.supply-warriors", "read.vp" }, new[] { "ui.esquie.rocks", "ui.esquie.rock-ring", "ui.esquie.lampmaster-badge", "ui.esquie.francois-badge", "ui.esquie.francois-decoy", "ui.global.goal-tracker", "ui.esquie.ending" }, new[] { "EsquieWin_WinsAtTurnEndWithFourRocks", "EsquieWin_GuardsLeftDropsOnHostLossesByAnyAttacker", "EsquieWin_OffInCoalition", "EsquieWin_DorrieBlockedByCorvidWarriors", "EsquieWin_WinsSameTurnSoarrieHandedOver" }),
            ["win.paintress"] = new WinConditionDef("win.paintress", "paintress", "The Family Portrait", "countdown", 2, 10, "From Act II with 10+ VP. A Living Portrait is a roost outside the Monolith, in a clearing she rules (ties count, as Lords of the Forest), with 2+ of her warriors. The table is warned at the end of her turn if she rules the Monolith and has a roost there, and has Living Portraits in a fox, a rabbit and a mouse clearing. She wins at the start of her next Birdsong if the same test still passes.", "At hook.evening-end for the seat playing the Paintress (Eyrie): act >= 2, Vp(seat) >= tune.countdown-vp, ActiveDominance(seat) == null; Ruler(Monolith) == seat and BuildingsOfType(seat, Monolith, 'roost') >= tune.paintress-monolith-roosts; L = {c != Monolith : BuildingsOfType(seat, c, 'roost') >= 1, Ruler(c) == seat, Warriors(seat, c) minus the GuardsLeft of rocks she hosts in c >= tune.paintress-portrait-warriors}; the union of SuitsOf(c) over L includes fox, rabbit and mouse (a Lost City gives all three). Portraits are not stored; they are worked out at each check and labelled Verso, Clea and Renoir, one per suit, for display only. A pass adds the seat to state.global.countdowns and shows the banner.", "At hook.birdsong-start for her seat, before any Birdsong step, if the seat is in state.global.countdowns: the same test on the current board. Pass: do.declare-winner. Fail: remove the countdown and clear the banner.", "Before her next Birdsong: break one easel, flip rule in one Portrait clearing, thin a Portrait below 2 warriors, or take the Monolith. Grief (Turmoil) also resets her Decree.", true, false, new Dictionary<string, string> { ["tune.countdown-vp"] = "10", ["tune.paintress-portrait-warriors"] = "2", ["tune.paintress-monolith-roosts"] = "1" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.esquie.rocks", "state.global.seat-characters" }, new[] { "hook.evening-end", "hook.birdsong-start", "hook.load" }, new[] { "read.ruler", "read.buildings-of-type", "read.warriors", "read.suits-of", "read.clearings", "read.vp", "read.active-dominance" }, new[] { "ui.paintress.portraits", "ui.paintress.portrait-tracker", "ui.global.countdown-banner", "ui.global.goal-tracker", "ui.paintress.ending" }, new[] { "PaintressWin_AnnouncesWithThreeSuitsAndMonolith", "PaintressWin_ConfirmFailsAfterPortraitDropsBelowTwoWarriors", "PaintressWin_BlockedWithActiveDominance", "PaintressWin_LordsOfTheForestTieCountsAsRule" }),
            ["win.sciel"] = new WinConditionDef("win.sciel", "sciel", "Twilight Harvest", "countdown", 2, 10, "From Act II with 10+ VP. A Sanctuary is a clearing with her Lantern and no enemy pieces of any kind. The table is warned at the end of her turn if she has 5+ Sanctuaries spanning fox, rabbit and mouse, at least one Aquafarm is on the map, and she has 10+ VP. She wins at the start of her next Birdsong if at least 5 clearings across all three suits still hold her Lantern with no enemy building or token, and an Aquafarm still stands. Enemy warriors or pawns that only walk in do not stop it.", "At hook.evening-end for the seat playing Sciel (Alliance): act >= 2, Vp(seat) >= tune.countdown-vp, ActiveDominance(seat) == null; S = {c : TokensOfType(seat, c, 'sympathy') >= 1 and, for every other seat o, Warriors(o, c) + Buildings(o, c) + Tokens(o, c) == 0 and PawnClearing(o) != c}; |S| >= tune.sciel-sanctuaries; the union of SuitsOf over S includes fox, rabbit and mouse; the sum over all clearings of BuildingsOfType(seat, c, 'base') >= tune.sciel-aquafarms. A pass adds the countdown and shows the banner.", "At hook.birdsong-start for her seat, if in state.global.countdowns: S' = {c : TokensOfType(seat, c, 'sympathy') >= 1 and, for every other seat o, Buildings(o, c) + Tokens(o, c) == 0} (other seats' warriors and pawns are ignored); |S'| >= tune.sciel-sanctuaries, the suits of S' include fox, rabbit and mouse, and Aquafarms on the map >= tune.sciel-aquafarms. Pass: do.declare-winner. Fail: clear the countdown and banner.", "Before the announce, step any piece into a Sanctuary (paying Outrage). After it, battle one Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm before her Birdsong.", true, false, new Dictionary<string, string> { ["tune.countdown-vp"] = "10", ["tune.sciel-sanctuaries"] = "5", ["tune.sciel-aquafarms"] = "1" }, new[] { "state.global.countdowns", "state.global.act", "state.global.seat-characters" }, new[] { "hook.evening-end", "hook.birdsong-start", "hook.load" }, new[] { "read.tokens-of-type", "read.warriors", "read.buildings", "read.tokens", "read.pawn-clearing", "read.buildings-of-type", "read.suits-of", "read.clearings", "read.seats", "read.vp", "read.active-dominance" }, new[] { "ui.sciel.gauges", "ui.global.countdown-banner", "ui.global.goal-tracker", "ui.sciel.ending" }, new[] { "ScielWin_AnnouncesWithFiveSanctuariesAndAquafarm", "ScielWin_ConfirmIgnoresWalkInWarriors", "ScielWin_ConfirmFailsAfterLanternRemoved", "ScielWin_BlockedInActOne" }),
            ["win.verso"] = new WinConditionDef("win.verso", "verso", "The Last Note", "countdown", 2, 10, "From Act II with 10+ VP. His public Perfection rank runs D, C, B, A, S, starting at D. After each battle he is in: +1 if he removed an enemy piece and none of his items were damaged, -1 if 1-2 were damaged, -2 if 3 or more were. Strikes and other removals do not change it. The table is warned at the end of his turn if he is rank S, his pawn is in the Monolith, and no other faction has warriors, buildings or pawns there. He wins at the start of his next Birdsong if he is still in the Monolith at rank S; pieces that only walk in do not stop it. On Easy, a human Verso at rank A with 2 undamaged swords counts as S. No win while he is in a coalition.", "At hook.evening-end for the seat playing Verso: act >= 2, Vp(seat) >= tune.countdown-vp, CoalitionPartner(seat) == null; rank qualifies: state.verso.rank == tune.verso-rank-s, or (IsBot(seat) == false and state.global.difficulty == Easy and state.verso.rank >= tune.verso-easy-rank and the count of Items(seat) that are swords and not Damaged >= tune.verso-easy-swords); PawnClearing(seat) == Monolith; for every other seat o: Warriors(o, Monolith) + Buildings(o, Monolith) == 0 and PawnClearing(o) != Monolith. A pass adds the countdown and shows the banner.", "At hook.birdsong-start for his seat, if in state.global.countdowns: PawnClearing(seat) == Monolith and the rank still qualifies by the same rule (gates act >= 2 and no coalition re-checked). Other pieces in the Monolith are ignored. Pass: do.declare-winner. Fail: clear the countdown and banner.", "Battle him in the Monolith before his Birdsong and land a hit: any damaged item drops him off S. Ambush cards are the classic answer.", true, true, new Dictionary<string, string> { ["tune.countdown-vp"] = "10", ["tune.verso-rank-s"] = "4", ["tune.verso-easy-rank"] = "3", ["tune.verso-easy-swords"] = "2", ["tune.verso-rank-up"] = "1", ["tune.verso-rank-down-small"] = "1", ["tune.verso-rank-down-large"] = "2", ["tune.verso-heavy-damage"] = "3" }, new[] { "state.verso.rank", "state.global.countdowns", "state.global.act", "state.global.difficulty", "state.global.roles", "state.global.seat-characters" }, new[] { "hook.battle-resolved", "hook.evening-end", "hook.birdsong-start", "hook.load" }, new[] { "read.pawn-clearing", "read.warriors", "read.buildings", "read.items", "read.is-bot", "read.seats", "read.vp", "read.coalition-partner" }, new[] { "ui.verso.rank", "ui.global.countdown-banner", "ui.global.goal-tracker", "ui.verso.ending" }, new[] { "VersoWin_AnnouncesAtRankSAloneInMonolith", "VersoWin_ConfirmFailsAfterHitDropsRank", "VersoWin_EasyAssistOnlyForHuman", "VersoWin_ConfirmIgnoresWalkIns" }),
            ["win.maelle"] = new WinConditionDef("win.maelle", "maelle", "A Home in the Canvas", "countdown", 2, 10, "From Act II with 10+ VP. The table is warned at the end of her turn if she is Allied with at least 2 non-Vagabond factions (if only one is seated: Allied with it and 15+ VP instead), Hostile with none, her pawn is in Lumière, and she has 3+ undamaged items (exhausted items count). She wins at the start of her next Birdsong if it still holds. No win while she is in a coalition.", "At hook.evening-end for the seat playing Maelle: act >= 2, CoalitionPartner(seat) == null; F = seats o with EngineOf(o) not a Vagabond; allied = |{o in F : RelationshipOf(seat, o) == Allied}|; hostile = |{o in F : RelationshipOf(seat, o) == Hostile}|; if |F| >= 2: allied >= tune.maelle-allied and Vp(seat) >= tune.countdown-vp; if |F| == 1: allied == 1 and Vp(seat) >= tune.maelle-2p-vp; hostile == 0; PawnClearing(seat) == Lumière; the count of Items(seat) with Damaged == false >= tune.maelle-items. A pass adds the countdown and shows the banner.", "At hook.birdsong-start for her seat, if in state.global.countdowns: the same test on the current board. Pass: do.declare-winner. Fail: clear the countdown and banner.", "Attack her in Lumière before her Birdsong and damage items until fewer than 3 are undamaged (Ambush cards help). Opponents cannot lower her relationships: a Vagabond's relationships rise only through her own Aid, and drop only to Hostile when she removes that faction's warriors.", true, true, new Dictionary<string, string> { ["tune.countdown-vp"] = "10", ["tune.maelle-allied"] = "2", ["tune.maelle-items"] = "3", ["tune.maelle-2p-vp"] = "15" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters" }, new[] { "hook.evening-end", "hook.birdsong-start", "hook.load" }, new[] { "read.seats", "read.seat-engine", "read.relationship", "read.pawn-clearing", "read.items", "read.vp", "read.coalition-partner" }, new[] { "ui.maelle.family", "ui.maelle.stance", "ui.global.countdown-banner", "ui.global.goal-tracker", "ui.maelle.ending" }, new[] { "MaelleWin_AnnouncesWithTwoAlliedInLumiere", "MaelleWin_ConfirmFailsWhenItemsDamagedBelowThree", "MaelleWin_SingleFactionNeedsFifteenVp", "MaelleWin_BlockedByAnyHostile" }),
            ["win.lune"] = new WinConditionDef("win.lune", "lune", "Her Parents' Work", "quest", 2, 0, "From Act II. At the start of Act II one relic in a forest is tagged as the Parents' Journal and its forest glows gold. She wins at the end of any of her turns once her recovered relics include a Journal (tablet), a Route Chart (figure) and a Chroma Sample (jewelry), with the Parents' Journal among them. If an enemy knocks the Parents' Journal loose, it goes face up into a forest and keeps its tag.", "At hook.evening-end for the seat playing Lune (Keepers): act >= 2, ActiveDominance(seat) == null; R = RecoveredRelics(seat); the set {RelicType(r) : r in R} holds tune.lune-relic-types distinct types (tablet, figure, jewelry); and state.lune.tagged-relic is in R. Pass: do.declare-winner at once.", "None: a quest win takes effect at the end of the owner's turn, with no Birdsong confirmation.", "Intercept her carriers on the way to a waystation (the attacker scores Prized Trophies and the Journal drops face up, still tagged); hold the clearings around the gold forest by Sirène so she cannot delve it safely; she announces the journal run a turn early.", true, false, new Dictionary<string, string> { ["tune.lune-relic-types"] = "3" }, new[] { "state.lune.tagged-relic", "state.global.act", "state.global.roles", "state.global.seat-characters" }, new[] { "hook.act-change", "hook.relic-moved", "hook.relic-recovered", "hook.evening-end", "hook.load" }, new[] { "read.recovered-relics", "read.relic-type", "read.relic-value", "read.relics-in-forest", "read.relic-forest", "read.forests-around", "read.forest-clearings", "read.active-dominance", "read.path-neighbours", "read.relic-face-up" }, new[] { "ui.lune.journal-glow", "ui.lune.thesis", "ui.global.goal-tracker", "ui.lune.ending" }, new[] { "LuneWin_WinsWithThreeTypesIncludingTaggedJournal", "LuneWin_NoWinWithoutTaggedJournal", "LuneWin_BlockedInActOne", "LuneWin_DroppedJournalKeepsTag" }),
            ["win.monoco"] = new WinConditionDef("win.monoco", "monoco", "The Bestial Wheel", "countdown", 2, 10, "From Act II with 10+ VP. Monoco takes a foot only in a battle his Warlord is in, when Hundreds hits remove an enemy piece. Agile: an enemy warrior, in a clearing the Warlord moved into this turn. Heavy: an enemy building. Caster: an enemy token. Balanced: a battle where he removed an enemy piece and lost one of his own. Almighty (Act III only): a building of the current VP leader, or 3+ of the leader's pieces in one battle. The five feet must come from at least 3 different factions, or every opponent if fewer are seated. The table is warned at the end of his turn when he has all five and 10+ VP; he wins at the start of his next Birdsong if he still has all five and the Warlord is on the map. Whenever the Warlord is removed, he loses Almighty and his most recent other foot.", "At hook.evening-end for the seat playing Monoco (Hundreds): act >= 2, Vp(seat) >= tune.countdown-vp, ActiveDominance(seat) == null; all tune.monoco-feet entries of state.monoco.feet have Earned == true; the number of distinct Faction values among them >= min(tune.monoco-feet-factions, number of other seats). A pass adds the countdown and shows the banner.", "At hook.birdsong-start for his seat, if in state.global.countdowns: the same test, and PawnClearing(seat) != null (the Warlord is on the map). Pass: do.declare-winner. Fail: clear the countdown and banner.", "Kill the Warlord during the countdown: Sacred River Rebirth strips Almighty and his latest other foot. Otherwise deny him fights against new factions; the Warlord is one exposed pawn.", true, false, new Dictionary<string, string> { ["tune.countdown-vp"] = "10", ["tune.monoco-feet"] = "5", ["tune.monoco-feet-factions"] = "3", ["tune.monoco-almighty-act"] = "3", ["tune.monoco-almighty-pieces"] = "3" }, new[] { "state.monoco.feet", "state.global.countdowns", "state.global.act", "state.global.seat-characters" }, new[] { "hook.battle-resolved", "hook.warlord-removed", "hook.evening-end", "hook.birdsong-start", "hook.load" }, new[] { "read.pawn-clearing", "read.seats", "read.vp", "read.active-dominance" }, new[] { "ui.monoco.wheel", "ui.global.countdown-banner", "ui.global.goal-tracker", "ui.monoco.ending" }, new[] { "MonocoWin_AnnouncesWithFiveFeetFromThreeFactions", "MonocoWin_ConfirmFailsAfterWarlordRemoved", "MonocoWin_AlmightyOnlyInActThree", "MonocoWin_FewerOpponentsNeedEveryOpponent" }),
            ["win.curator"] = new WinConditionDef("win.curator", "curator", "Curtain Call", "countdown", 3, 10, "End the painting from Lumière. From Act III with 10+ VP. The table is warned at the end of his turn if no Paintress roost stands in the Monolith (always true if she is not seated), one of his tunnels stands in the Monolith (the crack there opens into a tunnel at Act III), and he rules Lumière, with one of his buildings or 3+ of his warriors there if no keep stands in Lumière. He wins at the start of his next Birdsong if it still holds.", "At hook.evening-end for the seat playing the Curator (Duchy): act >= 3, Vp(seat) >= tune.countdown-vp, ActiveDominance(seat) == null; p = the seat playing the Paintress (state.global.seat-characters), and either p is not seated or BuildingsOfType(p, Monolith, 'roost') == 0; TokensOfType(seat, Monolith, 'tunnel') >= tune.curator-monolith-tunnels; Ruler(Lumière) == seat; and if no seat s has TokensOfType(s, Lumière, 'keep') >= 1, then Buildings(seat, Lumière) >= 1 or Warriors(seat, Lumière) >= tune.curator-lumiere-warriors. A pass adds the countdown and shows the banner.", "At hook.birdsong-start for his seat, if in state.global.countdowns: the same test on the current board. Pass: do.declare-winner. Fail: clear the countdown and banner.", "Before his Birdsong: flip rule of Lumière, remove his tunnel from the Monolith, or (with no keep in Lumière) raze his building there and cut his warriors below 3. Keeping the Paintress's roost alive in the Monolith blocks him; every camp or stall destroyed also costs him a minister (Price of Failure).", true, false, new Dictionary<string, string> { ["tune.countdown-vp"] = "10", ["tune.curator-monolith-tunnels"] = "1", ["tune.curator-lumiere-warriors"] = "3" }, new[] { "state.curator.cell-crack", "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters" }, new[] { "hook.setup-complete", "hook.act-change", "hook.evening-end", "hook.birdsong-start", "hook.load" }, new[] { "read.buildings-of-type", "read.tokens-of-type", "read.ruler", "read.buildings", "read.warriors", "read.seats", "read.vp", "read.active-dominance" }, new[] { "ui.curator.cell-crack", "ui.global.countdown-banner", "ui.global.goal-tracker", "ui.curator.ending" }, new[] { "CuratorWin_AnnouncesWithMonolithTunnelAndLumiereRuled", "CuratorWin_ConfirmFailsAfterLumiereRuleFlips", "CuratorWin_BlockedBeforeActThree", "CuratorWin_NoKeepNeedsBuildingOrThreeWarriors" }),
            ["win.clea"] = new WinConditionDef("win.clea", "clea", "Nevron Tide", "countdown", 2, 10, "From Act II with 10+ VP. The table is warned at the end of her turn if her Nevrons (warriors) stand in 8+ different clearings, one of them the Monolith, and she has an atelier (garden) in the Flying Manor. Guard warriors she hosts on Esquie's rocks do not count. She wins at the start of her next Birdsong if it still holds.", "At hook.evening-end for the seat playing Clea (Lizards): act >= 2, Vp(seat) >= tune.countdown-vp, ActiveDominance(seat) == null; covered = {c : Warriors(seat, c) minus the GuardsLeft of rocks in c whose HostSeat == seat >= 1}; |covered| >= tune.clea-coverage; Monolith is in covered; BuildingsOfType(seat, FlyingManor, 'garden') >= tune.clea-manor-gardens. A pass adds the countdown and shows the banner.", "At hook.birdsong-start for her seat, if in state.global.countdowns: the same test on the current board. Pass: do.declare-winner. Fail: clear the countdown and banner.", "Before her Birdsong: remove her warriors from one counted clearing or from the Monolith, or raze the Flying Manor atelier. Lone Nevrons fall to any battle.", true, false, new Dictionary<string, string> { ["tune.countdown-vp"] = "10", ["tune.clea-coverage"] = "8", ["tune.clea-manor-gardens"] = "1" }, new[] { "state.esquie.rocks", "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters" }, new[] { "hook.evening-end", "hook.birdsong-start", "hook.load" }, new[] { "read.warriors", "read.buildings-of-type", "read.clearings", "read.vp", "read.active-dominance" }, new[] { "ui.clea.coverage", "ui.global.countdown-banner", "ui.global.goal-tracker", "ui.clea.ending" }, new[] { "CleaWin_AnnouncesWithEightCoveredIncludingMonolith", "CleaWin_ConfirmFailsAfterManorAtelierRazed", "CleaWin_HostedGuardsDoNotCount", "CleaWin_BlockedBelowTenVp" }),
            ["win.white-haired-man"] = new WinConditionDef("win.white-haired-man", "white-haired-man", "Nobody Reaches Her", "countdown", 2, 10, "From Act II with 10+ VP. The Ring is the Monolith's path neighbours. The table is warned at the end of his turn if every Ring clearing either holds his face-up Snare (Barrier), or holds at least one of his pieces (warrior or plot, face up or down) and is ruled by no faction other than him or the Paintress; and the Monolith is ruled by no faction other than him or the Paintress and holds no Vagabond pawn. He wins at the start of his next Birdsong if the same test still passes.", "At hook.evening-end for the seat playing the White-Haired Man (Corvids): act >= 2, Vp(seat) >= tune.countdown-vp, ActiveDominance(seat) == null; p = the seat playing the Paintress, if seated; Ring = PathNeighbours(Monolith); for every r in Ring: FaceUpPlot(seat, r) == 'snare', or (Warriors(seat, r) minus the GuardsLeft of rocks he hosts in r, plus TokensOfType(seat, r, 'plot'), >= 1, and Ruler(r) is seat, p or null); and for the Monolith: Ruler(Monolith) is seat, p or null, and no seat v whose EngineOf(v) is a Vagabond has PawnClearing(v) == Monolith. A pass adds the countdown and shows the banner.", "At hook.birdsong-start for his seat, if in state.global.countdowns: the same test on the current board. Pass: do.declare-winner. Fail: clear the countdown and banner.", "Before his Birdsong: out-stack him in one Ring clearing, strip a plot with an Exposure guess, or walk a Vagabond into the Monolith (the one deliberate walk-in answer).", true, false, new Dictionary<string, string> { ["tune.countdown-vp"] = "10" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.esquie.rocks" }, new[] { "hook.evening-end", "hook.birdsong-start", "hook.load" }, new[] { "read.path-neighbours", "read.corvid-face-up-plot", "read.warriors", "read.tokens-of-type", "read.ruler", "read.pawn-clearing", "read.seats", "read.seat-engine", "read.vp", "read.active-dominance" }, new[] { "ui.white-haired-man.ring", "ui.global.countdown-banner", "ui.global.goal-tracker", "ui.white-haired-man.ending" }, new[] { "WhiteHairedManWin_AnnouncesWithRingHeld", "WhiteHairedManWin_ConfirmFailsWhenVagabondEntersMonolith", "WhiteHairedManWin_FaceUpSnareHoldsOutstackedClearing", "WhiteHairedManWin_PaintressRuleCountsAsHeld" }),
        };

        public static readonly IReadOnlyDictionary<string, RuleTweakDef> RuleTweaks = new Dictionary<string, RuleTweakDef>
        {
            ["tweak.gustave.overcharge"] = new RuleTweakDef("tweak.gustave.overcharge", "gustave", "Overcharge", "A pre-battle toggle on his faction board, never a mid-battle prompt. When he attacks with Gustave's Arm at tune.gustave-arm-max (3/3), he may arm it for +tune.gustave-overcharge-hits hit in that battle; when the battle resolves the Arm empties to 0 (instead of charging). An unused armed toggle switches off at the end of his turn. His bot arms it only to take the Beachhead or retake Lumière.", "v1", new[] { "hook.ui-toggle", "hook.battle-start", "hook.battle-resolved", "hook.turn-end" }, new[] { "do.add-hits" }, new[] { "Overcharge_AddsHitAndEmptiesArm", "Overcharge_UnavailableBelowFullArm", "Overcharge_DisarmsUnusedAtTurnEnd" }),
            ["tweak.gustave.keep-in-lumiere"] = new RuleTweakDef("tweak.gustave.keep-in-lumiere", "gustave", "Expedition Camp in Lumière", "Setup: the Marquise keep (the Expedition Camp) goes in Lumière. On Autumn, Lumière is fixed (the bottom-left corner by the lake, autumn.01), so the keep may only go there and the Monolith is the diagonally opposite top-right corner. On other maps the corner where Gustave places the keep becomes Lumière for the game, and the corner diagonally opposite becomes the Monolith, before any other faction sets up. Either way normal Marquise setup then leaves the Monolith as the one clearing with no Expeditioners.", "v1", new[] { "hook.setup-home", "hook.piece-placed" }, new[] { "do.restrict-home" }, new[] { "GustaveSetup_KeepCornerBecomesLumiere", "GustaveSetup_MonolithIsDiagonalAndHasNoExpeditioners", "GustaveSetup_AutumnKeepRestrictedToLumiere" }),
            ["tweak.esquie.belly-bounce"] = new RuleTweakDef("tweak.esquie.belly-bounce", "esquie", "Belly Bounce", "Automatic, no prompt: in a clearing with a guarded rock, his Bag counts as tune.esquie-belly-bounce-swords undamaged sword for his max hits.", "v1", new[] { "hook.battle-start" }, new[] { "do.add-max-hits" }, new[] { "BellyBounce_BagAddsMaxHitInGuardedRockClearing", "BellyBounce_NoEffectOutsideRockClearings", "BellyBounce_DamagedBagDoesNotCount" }),
            ["tweak.esquie.never-mad"] = new RuleTweakDef("tweak.esquie.never-mad", "esquie", "Never Mad", "He may start a battle or Strike only against the Nevron host's warriors in a clearing with a guarded rock. Every other battle or Strike is not offered to him (AI and human UI alike).", "v1", new[] { "hook.battle-legal" }, Array.Empty<string>(), new[] { "NeverMad_AllowsBattleAgainstHostGuards", "NeverMad_BlocksBattleOutsideGuardedRockClearing", "NeverMad_BlocksStrikeOnNonHostPieces" }),
            ["tweak.esquie.friends-not-foes"] = new RuleTweakDef("tweak.esquie.friends-not-foes", "esquie", "Friends Not Foes", "Removing guard warriors never moves the host toward Hostile: one prefix patch skips Root's hostility change for battles in a clearing with a guarded rock.", "v1", new[] { "hook.hostility-change" }, Array.Empty<string>(), new[] { "FriendsNotFoes_HostNotMadeHostileInGuardedRockClearing", "FriendsNotFoes_HostilityNormalElsewhere" }),
            ["tweak.esquie.start-near-nest"] = new RuleTweakDef("tweak.esquie.start-near-nest", "esquie", "Starts by the Nest", "Setup: Esquie's pawn starts in a forest touching Esquie's Nest.", "v1", new[] { "hook.setup-home" }, new[] { "do.restrict-start-forest" }, new[] { "EsquieSetup_StartsInForestTouchingNest" }),
            ["tweak.esquie.guard-floor"] = new RuleTweakDef("tweak.esquie.guard-floor", "esquie", "Guards hold their post", "While a rock is guarded in a clearing, the host's move generator (Root's AI and the human UI too) keeps at least GuardsLeft of its warriors there. It is a count floor: the host's other warriors come and go. The floor lifts when the rock becomes loose. Applies to any host, a human Clea included. With tune.esquie-guard-spawns at 0 (the no-spawn fallback) no rock is ever guarded, so this floor never applies.", "v1", new[] { "hook.setup-complete", "hook.act-change", "hook.battle-resolved", "hook.piece-removed", "hook.action-resolved", "hook.aid-resolved", "hook.evening-end", "hook.load" }, new[] { "do.set-guard-floor" }, new[] { "GuardFloor_HostCannotMoveBelowGuardsLeft", "GuardFloor_ExtraHostWarriorsMoveFreely", "GuardFloor_LiftsWhenRockLoose" }),
            ["tweak.esquie.guard-no-placement"] = new RuleTweakDef("tweak.esquie.guard-no-placement", "esquie", "No building at a guarded rock", "While a rock is guarded in a clearing, the host may not build, recruit or place pieces there (AI and human UI alike). The block lifts when the rock becomes loose. With tune.esquie-guard-spawns at 0 (the no-spawn fallback) no rock is ever guarded, so this block never applies.", "v1", new[] { "hook.setup-complete", "hook.act-change", "hook.battle-resolved", "hook.piece-removed", "hook.action-resolved", "hook.aid-resolved", "hook.evening-end", "hook.load" }, new[] { "do.block-placement" }, new[] { "GuardRules_HostCannotBuildRecruitOrPlaceInRockClearing", "GuardRules_PlacementBlockLiftsWhenRockLoose" }),
            ["tweak.esquie.guards-never-count"] = new RuleTweakDef("tweak.esquie.guards-never-count", "esquie", "Guards are not the host's", "Guard warriors never count toward the host's own themed win. Wherever a themed-win test counts the host's own warriors toward the host's win (Clea's coverage, the White-Haired Man's Ring, the Paintress's Portraits), it first subtracts GuardsLeft of the guarded rocks it hosts there. Other seats' tests still see guards as enemy warriors (for example in Sciel's Sanctuaries or Verso's Monolith test).", "v1", new[] { "hook.evening-end", "hook.birdsong-start" }, Array.Empty<string>(), new[] { "GuardRules_HostedGuardsExcludedFromCleaCoverage", "GuardRules_HostedGuardsExcludedFromRingPresence", "GuardRules_HostedGuardsExcludedFromPortraitWarriors", "GuardRules_OtherSeatsStillSeeGuardsAsEnemyWarriors" }),
            ["tweak.esquie.florrie-swim"] = new RuleTweakDef("tweak.esquie.florrie-swim", "esquie", "Rock power: Florrie", "Once Esquie holds Florrie, rivers count as paths for him.", "v1.1", new[] { "hook.action-resolved", "hook.load" }, new[] { "do.grant-ability" }, new[] { "RockPowers_FlorrieLetsRiversCountAsPaths" }),
            ["tweak.esquie.dorrie-coral"] = new RuleTweakDef("tweak.esquie.dorrie-coral", "esquie", "Rock power: Dorrie", "Once Esquie holds Dorrie, he no longer pays the extra boot for entering a Hostile faction's clearing.", "v1.1", new[] { "hook.action-resolved", "hook.explore-resolved", "hook.load" }, new[] { "do.grant-ability" }, new[] { "RockPowers_DorrieWaivesHostileBoot" }),
            ["tweak.esquie.soarrie-glide"] = new RuleTweakDef("tweak.esquie.soarrie-glide", "esquie", "Rock power: Soarrie", "Once Esquie holds Soarrie, he may exhaust a torch once per turn to move to any clearing (the Harrier's Glide logic).", "v1.1", new[] { "hook.action-resolved", "hook.aid-resolved", "hook.evening-end", "hook.load" }, new[] { "do.grant-ability" }, new[] { "RockPowers_SoarrieGlideOncePerTurn" }),
            ["tweak.paintress.roost-in-monolith"] = new RuleTweakDef("tweak.paintress.roost-in-monolith", "paintress", "First easel in the Monolith", "Setup: her starting roost (Easel) must go in the Monolith. Normal setup already puts it there when Gustave's keep is in Lumière.", "v1", new[] { "hook.setup-home" }, new[] { "do.restrict-home" }, new[] { "PaintressSetup_RoostRestrictedToMonolith" }),
            ["tweak.paintress.still-life"] = new RuleTweakDef("tweak.paintress.still-life", "paintress", "Still Life", "Once per turn, when an enemy starts a battle in a Living Portrait clearing, she may move tune.paintress-still-life-warriors warrior there from an adjacent clearing before the roll.", "v1.1", new[] { "hook.battle-start", "hook.turn-end" }, new[] { "do.move-warriors" }, new[] { "StillLife_MovesOneWarriorBeforeRoll", "StillLife_OncePerTurn" }),
            ["tweak.sciel.twilight"] = new RuleTweakDef("tweak.sciel.twilight", "sciel", "Twilight", "Automatic. Placing a Lantern gives her a Sun charge; removing an enemy warrior in a battle she starts gives a Moon charge. If she holds both at the start of her Evening, her first battle that Evening deals +tune.sciel-twilight-hits hit, then both reset.", "v1.1", new[] { "hook.piece-placed", "hook.battle-resolved", "hook.evening-start", "hook.battle-start", "hook.turn-end" }, new[] { "do.add-hits" }, new[] { "Twilight_SunAndMoonAddHitToFirstEveningBattle", "Twilight_ChargesResetAfterBoostedBattle", "Twilight_NoHitWithOnlyOneCharge" }),
            ["tweak.verso.perfection"] = new RuleTweakDef("tweak.verso.perfection", "verso", "Perfection", "Automatic: at rank A or S (tune.verso-perfection-rank or higher) he deals +tune.verso-perfection-hits hit when attacking, once per battle. Any hit he takes knocks the rank down, so it balances itself.", "v1", new[] { "hook.battle-start" }, new[] { "do.add-hits" }, new[] { "Perfection_AddsHitAtRankAOrS", "Perfection_NoHitBelowRankA", "Perfection_NoHitWhenDefending" }),
            ["tweak.verso.soarrie-handoff"] = new RuleTweakDef("tweak.verso.soarrie-handoff", "verso", "Soarrie hand-off", "If Esquie is seated (needs The Riverfolk Expansion), Soarrie appears on Verso's card at the start of Act II. It passes to Esquie when Esquie ends a turn in Verso's clearing in Act II or later, and Verso scores tune.verso-soarrie-vp VP.", "v1", new[] { "hook.act-change", "hook.evening-end" }, new[] { "do.score-vp", "do.hide-overlay" }, new[] { "SoarrieHandoff_PassesWhenEsquieEndsTurnInVersoClearing", "SoarrieHandoff_VersoScoresOneVp", "SoarrieHandoff_NotWhenVersoInForest" }),
            ["tweak.maelle.stance-chip"] = new RuleTweakDef("tweak.maelle.stance-chip", "maelle", "Stance chip", "Cosmetic: the chip on her card turns Offensive after she battles, Defensive after she Aids or is attacked, and Virtuose after she both battles and Aids in one turn. It changes her portrait and barks only.", "v1", new[] { "hook.battle-resolved", "hook.aid-resolved", "hook.turn-end" }, new[] { "do.show-overlay", "do.show-bubble" }, new[] { "StanceChip_OffensiveAfterBattle", "StanceChip_DefensiveAfterAidOrAttacked", "StanceChip_VirtuoseAfterBattleAndAidSameTurn" }),
            ["tweak.lune.stains"] = new RuleTweakDef("tweak.lune.stains", "lune", "Stains", "Each relic she recovers gives a Stain of its element: Chroma Sample (jewelry) = Fire, Journal (tablet) = Ice, Route Chart (figure) = Lightning. A pre-battle toggle on her board (not a mid-battle prompt) arms one Stain for +tune.lune-stain-hits hit in her next battle; the Stain is spent when that battle resolves.", "v1", new[] { "hook.relic-recovered", "hook.ui-toggle", "hook.battle-start", "hook.battle-resolved" }, new[] { "do.add-hits" }, new[] { "Stains_RecoveredRelicGivesMatchingStain", "Stains_ArmedStainAddsHitAndIsSpent", "Stains_CannotArmWithoutStain" }),
            ["tweak.monoco.sacred-river-rebirth"] = new RuleTweakDef("tweak.monoco.sacred-river-rebirth", "monoco", "Sacred River Rebirth", "Whenever the Warlord is removed, Monoco loses his Almighty foot and his most recently earned other foot; when Root anoints a new Warlord, it is Monoco reborn with some memories gone. Killing the Warlord during the countdown therefore stops him.", "v1", new[] { "hook.warlord-removed" }, new[] { "do.show-overlay" }, new[] { "SacredRiverRebirth_LosesAlmightyAndLatestFoot", "SacredRiverRebirth_NoFeetNoChange" }),
            ["tweak.curator.quiet-helper"] = new RuleTweakDef("tweak.curator.quiet-helper", "curator", "Quiet Helper", "Whenever another player removes the Paintress's roost from the Monolith, that player draws tune.curator-quiet-helper-cards card ('the Curator upgraded your weapon').", "v1", new[] { "hook.piece-removed" }, new[] { "do.draw-cards", "do.show-bubble" }, new[] { "QuietHelper_RoostRemoverDrawsCard", "QuietHelper_NotForRoostsOutsideMonolith", "QuietHelper_NotWhenCuratorRemovesIt" }),
            ["tweak.curator.home-corner"] = new RuleTweakDef("tweak.curator.home-corner", "curator", "Home corner", "Setup: his home corner may be any free corner except Lumière and the Monolith.", "v1", new[] { "hook.setup-home" }, new[] { "do.restrict-home" }, new[] { "CuratorSetup_HomeCornerExcludesLumiereAndMonolith" }),
            ["tweak.clea.home-flying-manor"] = new RuleTweakDef("tweak.clea.home-flying-manor", "clea", "Home in the Flying Manor", "Setup: her home corner is the Flying Manor.", "v1", new[] { "hook.setup-home" }, new[] { "do.restrict-home" }, new[] { "CleaSetup_HomeIsFlyingManor" }),
            ["tweak.clea.nevron-host"] = new RuleTweakDef("tweak.clea.nevron-host", "clea", "Nevron host", "When Clea is seated, Esquie's rock guards always come from her supply, and she follows the guard host rules (count floor, no building, recruiting or placing at a guarded rock) through the human UI too.", "v1", new[] { "hook.setup-complete", "hook.act-change" }, new[] { "do.place-warriors" }, new[] { "GuardHost_CleaHostsWhenSeated", "GuardHost_HumanCleaUiRespectsFloor" }),
            ["tweak.white-haired-man.unbeatable-act1"] = new RuleTweakDef("tweak.white-haired-man.unbeatable-act1", "white-haired-man", "Unbeatable in Act I", "During Act I only, his warriors in Ring clearings ignore the first hit of each battle (tune.white-haired-man-unbeatable-hits). It switches off at Act II. Exposure works as normal.", "v1", new[] { "hook.battle-start" }, new[] { "do.ignore-first-hit" }, new[] { "UnbeatableActOne_RingWarriorsIgnoreFirstHit", "UnbeatableActOne_OffFromActTwo", "UnbeatableActOne_OnlyInRingClearings" }),
            ["tweak.white-haired-man.monolith-barrier"] = new RuleTweakDef("tweak.white-haired-man.monolith-barrier", "white-haired-man", "Monolith Barrier", "Only while opt.monolith-barrier is on (default off): no battle may start in the Monolith until Visages and Sirène have both been ruled, at the end of the same turn, by seats other than the White-Haired Man and the Paintress. Once that happens the Barrier is down for the rest of the game.", "v1.1", new[] { "hook.battle-legal", "hook.turn-end" }, Array.Empty<string>(), new[] { "MonolithBarrier_BlocksMonolithBattleUntilAxonsRuled", "MonolithBarrier_StaysDownOnceBroken", "MonolithBarrier_OffUnlessOptionOn" }),
