        public static readonly IReadOnlyDictionary<string, StateDef> State = new Dictionary<string, StateDef>
        {
            ["state.global.act"] = new StateDef("state.global.act", "global", "int", "1-3 (act1 The Landing, act2 The Monolith, act3 The Canvas); never goes back", "1", new[] { "hook.game-start", "hook.turn-end", "hook.load" }, "Restored from the save. If the save has none, recomputed with the same state-based test as hook.turn-end: act 2 once any seat has reached tune.act1-end-vp or the last completed round is at least tune.act1-end-round, act 3 likewise with tune.act2-end-vp and tune.act2-end-round. Never moved backwards; a live game that is one step behind the recomputed act catches up at its next turn end."),
            ["state.global.round"] = new StateDef("state.global.round", "global", "int", "1 or more", "1", new[] { "hook.game-start", "hook.round-start", "hook.load" }, "Restored from the save; if Root exposes its own counter (read.round > 0), that value wins."),
            ["state.global.countdowns"] = new StateDef("state.global.countdowns", "global", "HashSet<SeatId>", "seats whose countdown banner is up (announced at the end of their turn, waiting for their next Birdsong)", "empty", new[] { "hook.evening-end", "hook.birdsong-start", "hook.load" }, "For each seat in the set, rerun that character's confirm test on the loaded board; keep it (and redraw its banner) only if it passes, otherwise drop it and clear the banner."),
            ["state.global.spoiler-mode"] = new StateDef("state.global.spoiler-mode", "global", "SpoilerMode", "Safe or Finished", "Safe until the first-launch question is answered; copied from opt.spoiler-mode when a game is created", new[] { "hook.title-screen", "hook.game-start", "hook.load" }, "Restored from the save: a game keeps the spoiler mode it started with, and a change to opt.spoiler-mode applies from the next game. Finished-mode 'mother' lines still wait for Act III."),
            ["state.global.difficulty"] = new StateDef("state.global.difficulty", "global", "Difficulty", "Easy, Normal or Hard", "Normal (copied from opt.difficulty when the game is created)", new[] { "hook.game-start", "hook.load" }, "Restored from the save, so a game keeps the difficulty it started with."),
            ["state.global.seat-characters"] = new StateDef("state.global.seat-characters", "global", "Dictionary<SeatId,string>", "every seat maps to one character id from characters.json", "empty; filled as seats are assigned", new[] { "hook.seat-assigned", "hook.load" }, "Restored from the save, then each seat's engine (read.seat-engine) is compared with its character's engine; on a mismatch that seat plays plain Root (no themed win or bot plan) and the player is warned."),
            ["state.global.roles"] = new StateDef("state.global.roles", "global", "Dictionary<RoleId,IReadOnlyList<ClearingId>>", "each map role id to its clearings (one for most roles; none for Sirène or The Reacher when the Monolith lacks that many path neighbours; all river clearings for the Sacred River)", "on Autumn: the fixed roles in map_autumn.json; on other maps: empty, filled at map load, or when Gustave's keep is placed if he is seated", new[] { "hook.map-loaded", "hook.piece-placed", "hook.load" }, "Restored from the save as is, because roles never move during a game (Lumière stays the keep's corner even after the keep is gone). Only a save with no mod state recomputes them by the map_roles rules."),
            ["state.global.e33-mode"] = new StateDef("state.global.e33-mode", "global", "bool", "true for a game created from the mod's character select; false for a plain Root game", "false", new[] { "hook.character-select", "hook.game-start", "hook.load" }, "True only if the save carries mod state for this game's ID; a save without it loads as plain Root."),
            ["state.global.campaign-game"] = new StateDef("state.global.campaign-game", "global", "int", "0 = Free Play, 1-3 = game number in the 3-game campaign (Act I, Act II, Act III)", "0", new[] { "hook.game-start", "hook.game-over" }, "Kept in the player's profile, not the game save; a loaded campaign game keeps the number saved with it."),
            ["state.global.campaign-journal"] = new StateDef("state.global.campaign-journal", "global", "bool", "true when the human lost the previous campaign game and gets the last expedition's journal (+1 card at setup)", "false", new[] { "hook.game-over", "hook.setup-complete" }, "Kept in the player's profile; spent at hook.setup-complete of the next campaign game."),
            ["state.global.pending-vp"] = new StateDef("state.global.pending-vp", "global", "Dictionary<SeatId,int>", "seat -> VP queued by do.score-vp's fallback (0 or more); only used when Root cannot add VP outside that seat's turn", "empty", new[] { "hook.evening-end", "hook.birdsong-start", "hook.load" }, "Restored from the save; each entry is paid at that seat's next Birdsong (hook.birdsong-start) and then removed."),
            ["state.global.pending-draws"] = new StateDef("state.global.pending-draws", "global", "Dictionary<SeatId,int>", "seat -> cards queued by do.draw-cards' fallback (0 or more); only used when Root cannot make a seat draw outside its turn", "empty", new[] { "hook.piece-removed", "hook.setup-complete", "hook.evening-start", "hook.load" }, "Restored from the save; each entry is added to that seat's next Evening draw (hook.evening-start) and then removed."),
            ["state.gustave.flags"] = new StateDef("state.gustave.flags", "gustave", "HashSet<ClearingId>", "clearings ever flagged; Lumière always included; only grows", "{Lumière}", new[] { "hook.setup-complete", "hook.evening-end", "hook.load" }, "Restored from the save; ids not on the current map are dropped and Lumière is added back if missing. Flags never come off, so the board is not used to remove any."),
            ["state.gustave.arm"] = new StateDef("state.gustave.arm", "gustave", "int", "0 to tune.gustave-arm-max (3)", "0", new[] { "hook.game-start", "hook.battle-resolved", "hook.load" }, "Restored and clamped to 0..tune.gustave-arm-max."),
            ["state.gustave.overcharge-armed"] = new StateDef("state.gustave.overcharge-armed", "gustave", "bool", "true while the Overcharge toggle is armed for his next battle", "false", new[] { "hook.ui-toggle", "hook.battle-resolved", "hook.turn-end", "hook.load" }, "Restored from the save (undo and rollback snapshots can fall between arming and the battle); dropped if state.gustave.arm < tune.gustave-arm-max."),
            ["state.gustave.route"] = new StateDef("state.gustave.route", "gustave", "IReadOnlyList<ClearingId>", "the bot's planned Route from Lumière to a Beachhead, in path order; empty for a human Gustave (Hard: rewritten after any action that raises a Route clearing's cost)", "empty", new[] { "hook.birdsong-start", "hook.action-resolved", "hook.load" }, "Not trusted after loading: recomputed at his next Birdsong."),
            ["state.esquie.rocks"] = new StateDef("state.esquie.rocks", "esquie", "RockState[]", "4 entries in order Florrie, Dorrie, Soarrie, Urrie. RockState fields: string Status (notSpawned | hidden | guarded | loose | heldByRuler | withVerso | held); ClearingId? Clearing (null while withVerso, heldByRuler or held); SeatId? HostSeat (the Nevron host for guarded rocks, Verso's seat for withVerso, null otherwise); int GuardsLeft (0-3). Soarrie's holder is HostSeat while withVerso, and the Monolith's current ruler while heldByRuler.", "all notSpawned", new[] { "hook.game-start", "hook.setup-complete", "hook.act-change", "hook.battle-resolved", "hook.piece-removed", "hook.action-resolved", "hook.explore-resolved", "hook.aid-resolved", "hook.evening-end", "hook.load" }, "Restored from the save. Held rocks stay held. For each guarded rock, GuardsLeft = min(saved GuardsLeft, host warriors now in its clearing), and it becomes loose at 0. Guard floors and placement blocks are re-sent to the plugin (do.set-guard-floor, do.block-placement). Rocks whose act has not come yet stay notSpawned."),
            ["state.esquie.decoy"] = new StateDef("state.esquie.decoy", "esquie", "bool", "true while the François decoy badge sits at Esquie's Nest", "false; true at setup when Esquie is seated", new[] { "hook.setup-complete", "hook.piece-moved", "hook.act-change", "hook.load" }, "Restored; forced false if the loaded act is 2 or later."),
            ["state.esquie.target"] = new StateDef("state.esquie.target", "esquie", "int?", "index (0-3) of the rock the bot is chasing this turn, or null", "null", new[] { "hook.birdsong-start", "hook.load" }, "Not trusted after loading: recomputed at his next Birdsong (a new target triggers his target bark)."),
            ["state.paintress.still-life-used"] = new StateDef("state.paintress.still-life-used", "paintress", "bool", "true once Still Life has moved a warrior this turn (v1.1)", "false", new[] { "hook.battle-start", "hook.turn-end", "hook.load" }, "Restored; reset at the next hook.turn-end."),
            ["state.paintress.repaint-avoid"] = new StateDef("state.paintress.repaint-avoid", "paintress", "Dictionary<ClearingId,int>", "clearings where a Portrait was destroyed, mapped to her turns left to avoid rebuilding there (0-2)", "empty", new[] { "hook.piece-removed", "hook.turn-end", "hook.load" }, "Restored; entries for clearings not on the map are dropped."),
            ["state.sciel.sun"] = new StateDef("state.sciel.sun", "sciel", "bool", "true while she holds a Sun charge (v1.1 Twilight)", "false", new[] { "hook.piece-placed", "hook.battle-resolved", "hook.load" }, "Restored from the save (the charge is an event record the board cannot show)."),
            ["state.sciel.moon"] = new StateDef("state.sciel.moon", "sciel", "bool", "true while she holds a Moon charge (v1.1 Twilight)", "false", new[] { "hook.battle-resolved", "hook.load" }, "Restored from the save."),
            ["state.sciel.twilight-armed"] = new StateDef("state.sciel.twilight-armed", "sciel", "bool", "true from the start of her Evening (holding Sun and Moon) until her first battle of that Evening", "false", new[] { "hook.evening-start", "hook.battle-resolved", "hook.turn-end", "hook.load" }, "Restored; cleared at the next hook.turn-end."),
            ["state.verso.rank"] = new StateDef("state.verso.rank", "verso", "int", "0-4 = D, C, B, A, S", "0 (D)", new[] { "hook.game-start", "hook.battle-resolved", "hook.load" }, "Restored and clamped to 0..tune.verso-rank-s."),
            ["state.maelle.stance"] = new StateDef("state.maelle.stance", "maelle", "string", "'none', 'offensive', 'defensive' or 'virtuose' (cosmetic stance chip)", "none", new[] { "hook.battle-resolved", "hook.aid-resolved", "hook.turn-end", "hook.load" }, "Restored from the save; cosmetic only."),
            ["state.maelle.stance-turn"] = new StateDef("state.maelle.stance-turn", "maelle", "HashSet<string>", "what she did during her current turn: 'battled', 'aided'", "empty", new[] { "hook.battle-resolved", "hook.aid-resolved", "hook.turn-end", "hook.load" }, "Restored; cleared at the next hook.turn-end."),
            ["state.maelle.family"] = new StateDef("state.maelle.family", "maelle", "HashSet<SeatId>", "the bot's two chosen family factions (one in a 2-player game); empty for a human Maelle", "empty", new[] { "hook.birdsong-start", "hook.load" }, "Restored; seats that are now Hostile are dropped and re-picked at her next Birdsong."),
            ["state.lune.tagged-relic"] = new StateDef("state.lune.tagged-relic", "lune", "int?", "relic id of the Parents' Journal, or null before Act II", "null", new[] { "hook.act-change", "hook.relic-moved", "hook.load" }, "Restored; if that relic id no longer exists, the relic is re-found by its type, value and last place; if it cannot be found and it is not among her recovered relics, the tagging rule runs again."),
            ["state.lune.stains"] = new StateDef("state.lune.stains", "lune", "Dictionary<string,int>", "Stains held by element: 'fire' (Chroma Sample), 'ice' (Journal), 'lightning' (Route Chart); 0 or more each", "all 0", new[] { "hook.relic-recovered", "hook.battle-resolved", "hook.load" }, "Restored from the save."),
            ["state.lune.stain-armed"] = new StateDef("state.lune.stain-armed", "lune", "string?", "the element armed for her next battle, or null", "null", new[] { "hook.ui-toggle", "hook.battle-resolved", "hook.load" }, "Restored; dropped if she no longer holds a Stain of that element."),
            ["state.monoco.feet"] = new StateDef("state.monoco.feet", "monoco", "FootState[]", "5 entries in order Agile, Caster, Balanced, Heavy, Almighty. FootState fields: bool Earned; SeatId? Faction (the seat it came from); int Order (1 for the first foot earned and rising; 0 while not earned).", "all not earned", new[] { "hook.game-start", "hook.battle-resolved", "hook.warlord-removed", "hook.load" }, "Restored from the save; Almighty is cleared if the loaded act is below tune.monoco-almighty-act; feet whose Faction is no longer a seat are cleared."),
            ["state.curator.cell-crack"] = new StateDef("state.curator.cell-crack", "curator", "string", "'none' (Curator not seated), 'inert' (setup to end of Act II), 'tunnel' (opened at Act III), 'dig-owed' (fallback: his first Act III action is a free Dig into the Monolith), 'gone' (the Monolith tunnel was removed; he may Dig again normally)", "none; inert at setup when the Curator is seated", new[] { "hook.setup-complete", "hook.act-change", "hook.action-resolved", "hook.piece-removed", "hook.load" }, "Restored, then checked against the board: 'tunnel' with no Duchy tunnel in the Monolith becomes 'gone'; 'inert' in Act III becomes 'dig-owed' if the opening never happened."),
            ["state.clea.covered"] = new StateDef("state.clea.covered", "clea", "HashSet<ClearingId>", "clearings holding 1+ of her warriors at the end of her last turn, not counting guard warriors she hosts on Esquie's rocks (the same count as win.clea); empty when Clea is not seated", "empty", new[] { "hook.evening-end", "hook.load" }, "Restored from the save; ids not on the current map are dropped. If the save has none, it is recomputed from the current board, so no clearing counts as just lost until her next turn ends."),
            ["state.white-haired-man.barrier-down"] = new StateDef("state.white-haired-man.barrier-down", "white-haired-man", "bool", "true once Visages and Sirène were both ruled at the end of a turn by seats other than the White-Haired Man and the Paintress (v1.1 Monolith Barrier)", "false", new[] { "hook.turn-end", "hook.load" }, "Restored from the save; it never goes back up."),
        };

        public static readonly IReadOnlyDictionary<string, GameHookDef> GameHooks = new Dictionary<string, GameHookDef>
        {
            ["hook.title-screen"] = new GameHookDef("hook.title-screen", "Root's title screen is shown (every launch and every return to the main menu). The mod draws the ROOT 33 title with the 33 tearing out of a rift, and on first launch asks 'Spoiler-safe' or 'I've finished Clair Obscur: Expedition 33', then offers the skippable prologue.", new[] { "whether a spoiler choice is already saved (first launch or not)" }, "void OnTitleScreenShown(bool firstLaunch)"),
            ["hook.character-select"] = new GameHookDef("hook.character-select", "Root's new-game faction selection screen is shown in E33 mode. The mod relabels factions as characters, hides the Clockwork bots, and locks finished-only characters (Clea) in safe mode.", new[] { "engines the player owns (base game plus DLC)", "maximum seat count" }, "void OnCharacterSelectShown(IReadOnlyList<EngineId> ownedEngines, int maxSeats)"),
            ["hook.seat-assigned"] = new GameHookDef("hook.seat-assigned", "A seat is given a faction or Vagabond when the game is created, either by the human's pick or by a bot filling an empty seat.", new[] { "seat", "engine", "whether the seat is a bot" }, "void OnSeatAssigned(SeatId seat, EngineId engine, bool isBot)"),
            ["hook.game-start"] = new GameHookDef("hook.game-start", "A new game has been created, after every seat is assigned and before the map and setup. The core resets all mod state (act 1, round 1, empty flags, rank D, rocks not spawned) and copies difficulty and spoiler mode into the game.", new[] { "seats in turn order", "difficulty", "spoiler mode" }, "void OnGameStart(IReadOnlyList<SeatId> turnOrder, Difficulty difficulty, SpoilerMode spoilers)"),
            ["hook.map-loaded"] = new GameHookDef("hook.map-loaded", "The map for a new game is built, before any setup piece is placed. When Gustave is not seated, the core assigns every map role by rule here (Lumière, the Monolith, the Axons, Old Lumière, Esquie's Nest, the Flying Manor, Stone Wave Cliffs, the Sacred River); when he is, it waits until his keep is placed (hook.piece-placed).", new[] { "map name", "clearings with suits, paths, rivers, corners, ruins and slots (read through board_reads)" }, "void OnMapLoaded(string mapName)"),
            ["hook.setup-home"] = new GameHookDef("hook.setup-home", "During setup, just before a seat chooses where its starting pieces go: the Marquise keep corner, the Eyrie starting roost, another faction's home corner (Lizards, Duchy and the rest), or a Vagabond's starting forest. The core restricts the choice with do.restrict-home or do.restrict-start-forest.", new[] { "seat about to choose" }, "void OnSetupChoice(SeatId seat)"),
            ["hook.setup-complete"] = new GameHookDef("hook.setup-complete", "Every seat has finished setup, before the first Birdsong. The core places the Act I spawns (Florrie and her guards, the François decoy, the Cell Crack overlay), flags Lumière for Gustave, and starts the prologue.", new[] { "the board after setup" }, "void OnSetupComplete()"),
            ["hook.round-start"] = new GameHookDef("hook.round-start", "The first seat in turn order starts its turn, which begins a new round. If Root keeps no round counter, the core counts rounds here.", new[] { "round number" }, "void OnRoundStart(int round)"),
            ["hook.birdsong-start"] = new GameHookDef("hook.birdsong-start", "The start of a seat's Birdsong, before any Birdsong step. Countdown confirmation tests run here first (dominance timing); bots plan their turn.", new[] { "seat whose Birdsong it is" }, "void OnBirdsongStart(SeatId seat)"),
            ["hook.evening-start"] = new GameHookDef("hook.evening-start", "The start of a seat's Evening, before any Evening step. Sciel's Twilight checks her Sun and Moon charges here.", new[] { "seat whose Evening it is" }, "void OnEveningStart(SeatId seat)"),
            ["hook.evening-end"] = new GameHookDef("hook.evening-end", "A seat's Evening has fully resolved (draw and discard done): the end of its turn. The roster's 'end of his Evening' and 'end of her turn' both mean this moment. Gustave plants his flags first, then Esquie's Soarrie hand-off and the early-Urrie check run, then the seat's themed-win test runs (countdown announce or quest win), so Esquie wins on the turn Soarrie is handed over if it is his fourth rock.", new[] { "seat whose turn is ending" }, "void OnEveningEnd(SeatId seat)"),
            ["hook.turn-end"] = new GameHookDef("hook.turn-end", "The turn passes from one seat to the next, right after hook.evening-end. Per-turn toggles and logs reset (unused Overcharge, stance-turn flags, Still Life), the Monolith Barrier is re-checked, and the act clock runs after the themed-win checks: if act < 3 and (the highest Vp of any seat >= the current act's endsAtVp (tune.act1-end-vp / tune.act2-end-vp), or the last completed round >= its endsAfterRound (tune.act1-end-round / tune.act2-end-round)), the act advances one step. The check is state-based, at most one step per turn; a threshold already met (for example one turn that crosses both 10 and 20 VP, or Act I ending at round 4 with a seat already on 20+) advances the next act at the following turn end.", new[] { "seat whose turn just ended" }, "void OnTurnEnd(SeatId seat)"),
            ["hook.act-change"] = new GameHookDef("hook.act-change", "The core moves the game into the next act (raised from hook.turn-end). Act-start story events run: vignettes, spawns (Dorrie, Soarrie, Urrie and guards), unlocks (themed wins at Act II, the Curator's and Almighty at Act III), the Parents' Journal tag, and the Cell Crack opening.", new[] { "new act number" }, "void OnActChanged(int act)"),
            ["hook.action-resolved"] = new GameHookDef("hook.action-resolved", "Any single action of any seat has resolved (move, battle, explore, aid, strike, quest, craft, build, recruit, dig, special action, and so on). Esquie claims loose rocks in his clearing after each of his actions; the Urrie early spawn is checked.", new[] { "seat that acted" }, "void OnActionResolved(SeatId seat)"),
            ["hook.piece-moved"] = new GameHookDef("hook.piece-moved", "One or more pieces of a seat moved (move, march, slip, advance, dig out of the Burrow, Crusade). Esquie entering the Nest while the François decoy is up triggers the decoy joke.", new[] { "owner seat", "piece kind", "from clearing (null for a forest or the Burrow)", "to clearing (null for a forest or the Burrow)", "count" }, "void OnPieceMoved(SeatId owner, PieceKind kind, ClearingId? from, ClearingId? to, int count)"),
            ["hook.piece-placed"] = new GameHookDef("hook.piece-placed", "A piece is placed on the map by any means (build, recruit, spread sympathy, organize, plot, dig, setup, the mod's own spawns). When Gustave's keep is placed during setup, the core assigns every map role (Lumière is the keep's corner) before any other faction sets up. Sciel gains a Sun charge when she places a Lantern.", new[] { "owner seat", "piece kind", "building or token type", "clearing" }, "void OnPiecePlaced(SeatId owner, PieceKind kind, string type, ClearingId c)"),
            ["hook.piece-removed"] = new GameHookDef("hook.piece-removed", "A piece leaves the map by any means: battle hit, Strike, Bomb, Revolt, mob, Sanctify, Convert. The Curator's Quiet Helper fires when the Paintress's roost leaves the Monolith; guard counters drop for host warriors removed outside a battle.", new[] { "seat that caused the removal (null when no seat did)", "removed piece (owner, kind, type)", "clearing" }, "void OnPieceRemoved(SeatId? remover, RemovedPiece piece, ClearingId c)"),
            ["hook.battle-legal"] = new GameHookDef("hook.battle-legal", "Root (or its AI, or the human UI) asks whether a seat may start a battle or a Strike against another seat in a clearing. Returning false hides the option. Used by Esquie's Never Mad and the v1.1 Monolith Barrier.", new[] { "attacker seat", "defender seat", "clearing", "whether it is a Strike" }, "bool CanStartBattle(SeatId attacker, SeatId defender, ClearingId c, bool strike)"),
            ["hook.battle-start"] = new GameHookDef("hook.battle-start", "A battle has been declared (attacker, defender and clearing fixed) and nothing has been rolled yet, before Ambush cards. Pre-battle toggles (Overcharge, Stains) are read and hit modifiers are registered (Perfection, Twilight, Belly Bounce, Unbeatable in Act I); Still Life may move a warrior in.", new[] { "attacker seat", "defender seat", "clearing" }, "void OnBattleStarting(SeatId attacker, SeatId defender, ClearingId c)"),
            ["hook.battle-resolved"] = new GameHookDef("hook.battle-resolved", "A battle has fully resolved: hits dealt, pieces removed, items damaged. Gustave's Arm, Verso's rank, Monoco's feet, Esquie's guard counters, Sciel's Moon charge and Maelle's stance update here.", new[] { "clearing", "attacker and defender seats", "every removed piece with owner, kind and type", "each Vagabond's damaged-item count before and after", "whether the attacker's pawn or Warlord entered the clearing this turn", "the VP leader when the battle started (null on a tie)" }, "void OnBattleResolved(BattleResult r)"),
            ["hook.explore-resolved"] = new GameHookDef("hook.explore-resolved", "A Vagabond's Explore action has resolved in a ruin clearing. Esquie claims Dorrie by Exploring Old Lumière in Act II or later.", new[] { "Vagabond seat", "clearing explored" }, "void OnExploreResolved(SeatId vagabond, ClearingId c)"),
            ["hook.aid-resolved"] = new GameHookDef("hook.aid-resolved", "A Vagabond's Aid action has resolved. Esquie claims Soarrie by Aiding the Monolith's ruler while in the Monolith; Maelle's stance turns Defensive.", new[] { "Vagabond seat", "faction seat aided", "clearing" }, "void OnAidResolved(SeatId vagabond, SeatId receiver, ClearingId c)"),
            ["hook.hostility-change"] = new GameHookDef("hook.hostility-change", "Root is about to make a faction Hostile to a Vagabond because the Vagabond removed that faction's warriors in a battle. Returning false skips the change (Friends Not Foes in guarded-rock clearings).", new[] { "Vagabond seat", "faction seat", "clearing of the battle" }, "bool AllowHostile(SeatId vagabond, SeatId faction, ClearingId battleClearing)"),
            ["hook.relationship-changed"] = new GameHookDef("hook.relationship-changed", "A Vagabond's relationship with a faction has changed (Aid steps, Hostile). Maelle's family row and barks update.", new[] { "Vagabond seat", "faction seat", "relationship before", "relationship after" }, "void OnRelationshipChanged(SeatId vagabond, SeatId faction, Relationship before, Relationship after)"),
            ["hook.item-changed"] = new GameHookDef("hook.item-changed", "A Vagabond item was gained, lost, damaged, repaired, exhausted or refreshed. Verso's hit chord, Maelle's undamaged-item count on the Goal Tracker, and bot gear checks use it.", new[] { "Vagabond seat", "item before (null when gained)", "item after (null when lost)" }, "void OnItemChanged(SeatId vagabond, ItemState? before, ItemState? after)"),
            ["hook.warlord-removed"] = new GameHookDef("hook.warlord-removed", "The Lord of the Hundreds' Warlord pawn has been removed, before Root anoints a new one. Monoco's Sacred River Rebirth fires.", new[] { "Hundreds seat", "clearing where the Warlord fell" }, "void OnWarlordRemoved(SeatId hundreds, ClearingId c)"),
            ["hook.relic-recovered"] = new GameHookDef("hook.relic-recovered", "The Keepers in Iron recovered a relic at a waystation. Lune gains a Stain; her win is checked at her end of turn.", new[] { "Keepers seat", "relic id", "relic type (tablet, figure or jewelry)" }, "void OnRelicRecovered(SeatId keepers, int relicId, string relicType)"),
            ["hook.relic-moved"] = new GameHookDef("hook.relic-moved", "A relic changed place: delved out of a forest, carried, dropped face up into a forest by Prized Trophies, or moved by the mod. Lune's Parents' Journal tag is re-attached here.", new[] { "relic id" }, "void OnRelicMoved(int relicId)"),
            ["hook.vp-changed"] = new GameHookDef("hook.vp-changed", "A seat's VP changed. The Monolith Number (33 minus the top score) and the Goal Tracker refresh; the act clock notes that an act's VP limit was reached.", new[] { "seat", "VP before", "VP after" }, "void OnVpChanged(SeatId seat, int before, int after)"),
            ["hook.turmoil"] = new GameHookDef("hook.turmoil", "The Eyrie fell into Turmoil (the Paintress's Grief). The smeared-canvas bubble plays; the rules are unchanged.", new[] { "Eyrie seat" }, "void OnTurmoil(SeatId eyrie)"),
            ["hook.convert"] = new GameHookDef("hook.convert", "The Lizard Cult converted an enemy warrior. Clea's 'perfect specimen' bark plays on the first Convert of each other faction.", new[] { "Lizard seat", "seat whose warrior was converted", "clearing" }, "void OnConvert(SeatId lizards, SeatId victim, ClearingId c)"),
            ["hook.ui-toggle"] = new GameHookDef("hook.ui-toggle", "A pre-battle toggle on a mod faction-board overlay is switched on or off, by the human clicking it or by a bot's Goal Director (Gustave's Overcharge, Lune's Stains).", new[] { "seat", "toggle id (e.g. 'overcharge', 'stain.fire')", "on or off" }, "void OnToggle(SeatId seat, string toggleId, bool on)"),
            ["hook.bot-decision"] = new GameHookDef("hook.bot-decision", "Root's AI is about to make a decision for a bot seat. The Goal Director picks one of the legal actions by the character's bot plan, or returns null to let Root's own AI decide (also used for hit allocation, Ambush and discards).", new[] { "bot seat", "legal action keys from the engine's legal-action API" }, "string? OnBotDecision(SeatId seat, IReadOnlyList<string> legalActions)"),
            ["hook.game-over"] = new GameHookDef("hook.game-over", "The game ended (30 VP, dominance, a coalition partner's win, or a themed win declared by the mod). The winner's ending card plays and campaign progress is saved.", new[] { "winning seats (a coalition gives two)" }, "void OnGameOver(IReadOnlyList<SeatId> winners)"),
            ["hook.save"] = new GameHookDef("hook.save", "Root writes a save (autosave, manual save, or an async online turn). The core returns its state as text, stored beside the save under the game's ID.", new[] { "the game's ID (to key the mod's file)" }, "string OnSave()"),
            ["hook.load"] = new GameHookDef("hook.load", "Root has loaded a save (resume, async turn, or an undo/rollback that restores a snapshot). The core restores its state and re-checks every piece of it against the board.", new[] { "the mod's saved text for this game's ID (empty when the save has none)" }, "void OnLoad(string saved)"),
        };

