            ["do.move-warriors"] = new BoardActionDef("do.move-warriors", "Move warriors of a seat between two clearings outside that seat's normal move (the Paintress's Still Life: 1 warrior from an adjacent clearing into a Living Portrait clearing before the roll).", "bool MoveWarriors(SeatId seat, ClearingId from, ClearingId to, int count)", false, "Still Life is left out (it is v1.1 only); nothing replaces it."),
            ["do.place-tunnel"] = new BoardActionDef("do.place-tunnel", "Place a Duchy tunnel token in a clearing from the Duchy's supply, or as a free extra token when all three are on the map (the Cell Crack opening at Act III).", "bool PlaceTunnel(SeatId duchy, ClearingId c, bool extraPiece)", false, "The Curator's first Act III action is a free Dig into the Monolith (do.grant-free-dig); the crack overlay stays until he digs there."),
            ["do.grant-free-dig"] = new BoardActionDef("do.grant-free-dig", "Grant the Duchy one free Dig into a given clearing as its first Act III action, without paying a card (the Cell Crack fallback when a tunnel cannot be placed directly).", "bool GrantFreeDig(SeatId duchy, ClearingId c)", false, "He Digs into the Monolith normally, paying the card, as the roster allows after a lost tunnel; the crack overlay stays until he does."),
            ["do.move-relic"] = new BoardActionDef("do.move-relic", "Move a relic token from one forest to another (the Parents' Journal moved into the forest beside Sirène at Act II).", "bool MoveRelicToForest(int relicId, int forest)", false, "Tag the chosen relic where it lies; only the gold glow marks it."),
            ["do.tag-relic"] = new BoardActionDef("do.tag-relic", "Keep a stable handle on one relic so its id survives being delved, carried, dropped face up by Prized Trophies and recovered (the Parents' Journal tag); the gold glow follows it.", "bool TagRelic(int relicId)", false, "If relic objects have no stable identity, the core re-finds the tagged relic after each hook.relic-moved by its type, value and last place."),
            ["do.declare-winner"] = new BoardActionDef("do.declare-winner", "End the game with a themed win for a seat (and its coalition partner, if any), showing that character's ending card.", "void DeclareWinner(SeatId seat, string winConditionId)", true, "Raise the winner's score to 30 through Root's own scoring so Root's 30 VP win ends the game, then show the ending card."),
            ["do.score-vp"] = new BoardActionDef("do.score-vp", "Add VP to a seat outside the usual scoring (Verso's 1 VP when Soarrie passes to Esquie).", "void ScoreVp(SeatId seat, int vp)", true, "If VP cannot be added outside the seat's own turn, queue it in state.global.pending-vp and add it at the start of that seat's next Birdsong."),
