            ["do.grant-ability"] = new BoardActionDef("do.grant-ability", "Give a seat a movement ability for the rest of the game: 'rivers-as-paths' (Florrie), 'no-hostile-boot' (Dorrie), 'glide' (Soarrie: exhaust a torch once per turn to move to any clearing, the Harrier's Glide logic).", "void GrantAbility(SeatId seat, string abilityKey)", false, "Leave the rock powers out (they are v1.1 only); the rocks still count for the win."),
            ["do.show-banner"] = new BoardActionDef("do.show-banner", "Show the public countdown banner for a seat's themed win (announced at the end of its turn).", "void ShowBanner(SeatId seat, string winConditionId)", true, "Write the warning into Root's game log or notification area."),
            ["do.clear-banner"] = new BoardActionDef("do.clear-banner", "Remove a seat's countdown banner (its confirmation failed, or it won).", "void ClearBanner(SeatId seat)", true, "Write the cancellation into Root's game log."),
            ["do.show-bubble"] = new BoardActionDef("do.show-bubble", "Show a speech bubble with a bark over a seat's portrait or pawn.", "void ShowBubble(SeatId seat, string barkId)", true, "Write the line into Root's game log."),
            ["do.show-overlay"] = new BoardActionDef("do.show-overlay", "Draw a mod overlay (token, badge, gauge, tracker, label or screen) anchored to a seat's board, a clearing, a forest, or the whole screen when all anchors are null.", "void ShowOverlay(string overlayId, SeatId? seat, ClearingId? c, int? forest)", true, "If it cannot be anchored on Root's board, show it in the mod's side panel instead, naming the clearing or seat."),
            ["do.hide-overlay"] = new BoardActionDef("do.hide-overlay", "Remove a mod overlay from its anchor (a claimed rock, the removed François decoy, an opened Cell Crack).", "void HideOverlay(string overlayId, SeatId? seat, ClearingId? c, int? forest)", true, "Remove it from the mod's side panel."),
