            ["do.hide-clockwork"] = new BoardActionDef("do.hide-clockwork", "Hide the Clockwork bots (Mechanical Marquise 2.0, Electric Eyrie, Automated Alliance, Vagabot) from seat selection in E33 mode, so every bot seat uses the standard Dire Wolf AI.", "void HideClockworkBots()", true, "Refuse to start an E33 game while a Clockwork bot is seated and say why."),
