        public static readonly IReadOnlyDictionary<string, BotPlanDef> BotPlans = new Dictionary<string, BotPlanDef>
        {
            ["bot.gustave"] = new BotPlanDef("bot.gustave", "gustave", "Goal mode when Vp(seat) >= tune.gustave-goal-vp (8) or the cost of his planned Route (step 1) is tune.gustave-goal-route-cost (4) or less. Easy: only at Vp(seat) >= tune.gustave-easy-goal-vp (12).", "The ruled Chain and the Arm gauge are public, he barks each new flag and announces the push a turn early, and flipping rule of any one Chain clearing or razing the Beachhead building before his Birdsong stops him.", "Goal mode at tune.gustave-easy-goal-vp (12) VP, with no Route-cost trigger; one Route build per turn; never Overcharges; does not retake lost Chain clearings proactively (step 2 is skipped). Spoiler layer: answers only a banner that is up, and only with actions the plan leaves free.", "Layer 1: the legal Marquise actions from Root's legal-action API (read.legal-actions); Root's own AI keeps hit allocation, Ambush and discards and plays any decision no step claims. Layer 2, the Goal Director, in priority order: plan the cheapest three-suit Route from Lumière to a Beachhead each Birdsong; retake lost flagged Route clearings first; build along the Route, the Beachhead as soon as he rules it; while the Arm is under 3 take at least one winnable battle per turn; Overcharge only to take the Beachhead or retake Lumière; in goal mode (8+ VP or Route cost 4 or less) spend bird cards on Route actions and skip Overwork; on the announce turn thicken the thinnest Chain clearing, then the Beachhead. Layer 3: the spoiler layer.", "Keeps a rule margin of tune.gustave-hard-rule-margin (2) on every Chain clearing and re-routes around blockades (re-plans the Route whenever an action raises a Route clearing's cost, not only at Birdsong). Spoiler layer: also answers a seat one step from a win ahead of the goal steps, except on its own announce turn.", new[] { "bot.gustave.01-route", "bot.gustave.02-hold", "bot.gustave.03-build", "bot.gustave.04-charge", "bot.gustave.05-overcharge", "bot.gustave.06-goal-mode", "bot.gustave.07-announce", "bot.gustave.08-spoiler" }),
            ["bot.esquie"] = new BotPlanDef("bot.esquie", "esquie", "Always target-driven: from his first Birdsong he chases the cheapest claimable rock within tune.esquie-bot-rock-range (3) moves, and plays normal Vagabond VP only when none is in range. Endgame at tune.esquie-endgame-rocks (3) rocks held: straight for the last one, whatever its distance.", "The rock ring is public, he barks every new target, and he never takes a risky fight. When he holds 3 rocks, the Nevron host stacks extra warriors on the last rock (more defenders deal more hits to him) and the other bots attack his pawn to damage items (both through the spoiler layer).", "Never asks friends for help (step 3 is skipped) and walks to the François decoy at the Nest once in Act I while it is up. Spoiler layer: answers only a banner that is up, and only with actions the plan leaves free.", "Layer 1: the legal Vagabond (Tinker) actions from Root's legal-action API (read.legal-actions); Root's own AI keeps hit allocation, Ambush and discards and plays any decision no step claims. Never Mad already hides every battle and Strike except against host guards. Layer 2, in priority order: each Birdsong pick the cheapest claimable rock; keep gear ready (repair at 2+ damaged items, get a sword if he could deal no hits); Aid a Friendly or Allied non-host faction next to a guard stack; hunt guards only with every item undamaged and when his hits can finish or nearly finish them, one guard battle per turn; with 3 rocks go straight for the last; with no rock within 3 moves play normal Vagabond VP. Layer 3: the spoiler layer, which can only move his pawn.", "Crafts a sword early (as soon as one is craftable) and fights two guard battles per turn (tune.esquie-hard-guard-battles). Spoiler layer: also answers a seat one step from a win ahead of the goal steps, except on its own announce turn.", new[] { "bot.esquie.01-target", "bot.esquie.02-gear", "bot.esquie.03-friends", "bot.esquie.04-hunt", "bot.esquie.05-endgame", "bot.esquie.06-vp", "bot.esquie.07-spoiler" }),
            ["bot.paintress"] = new BotPlanDef("bot.paintress", "paintress", "Finish mode at Vp(seat) >= tune.paintress-goal-vp (8) with tune.paintress-finish-portraits (2) Living Portraits, worked out as in win.paintress.", "The Portrait tracker is public; breaking one easel or flipping one Portrait clearing before her Birdsong stops the win; Grief resets her Decree; she ends an announce turn with a 'hold still' bark.", "Announces (barks) her next Portrait a turn early, and in finish mode adds one card too many, which often causes Grief. Spoiler layer: answers only a banner that is up, and only with actions the plan leaves free.", "Layer 1: the legal Eyrie actions from Root's legal-action API (read.legal-actions); Root's own AI keeps hit allocation, Ambush and discards and plays any decision no step claims. The Goal Director only reorders choices that a one-turn lookahead says she can resolve, so it never forces Grief (Turmoil). Layer 2, in priority order: score Portrait sites for each missing suit; add Decree cards for the best missing suit's Build and for Recruit; garrison Portraits to 2 warriors and the Monolith to 3+; finish mode at 8+ VP with 2 Living Portraits; repaint a destroyed Portrait elsewhere; attack the White-Haired Man last. Layer 3: the spoiler layer, which applies to everyone.", "Garrisons tune.paintress-hard-portrait-warriors (3) warriors on every Portrait instead of 2. Spoiler layer: also answers a seat one step from a win ahead of the goal steps, except on its own announce turn.", new[] { "bot.paintress.01-site", "bot.paintress.02-decree", "bot.paintress.03-garrison", "bot.paintress.04-finish", "bot.paintress.05-repaint", "bot.paintress.06-spare-white-haired-man", "bot.paintress.07-spoiler" }),
            ["bot.sciel"] = new BotPlanDef("bot.sciel", "sciel", "Finish mode at tune.sciel-finish-sanctuaries (4) Sanctuaries, worked out as in win.sciel's announce test.", "The Sun and Moon gauges are public and she barks her count. Before the announce, any piece stepping into a Sanctuary breaks it (paying Outrage). After it, battling one Lantern off the board or razing her only Aquafarm stops her.", "Evicts only with a 2:1 edge (tune.sciel-easy-evict-ratio), and half the time takes the first legal Revolt instead of the best-scored one. Spoiler layer: answers only a banner that is up, and only with actions the plan leaves free.", "Layer 1: the legal Alliance (Revolt, Spread, Mobilize, Operations) actions from Root's legal-action API (read.legal-actions); Root's own AI keeps hit allocation, Ambush and discards and plays any decision no step claims. Layer 2 re-weights where, in priority order: spread by score; revolt where it makes a Sanctuary; evict lone enemies from her Lanterns in Evening; organize idle warriors while the Sun gauge is short; recruit at threatened Aquafarms; keep a Teacher-led group by her biggest Lantern cluster; finish mode at 4 Sanctuaries; on the announce turn garrison the most exposed Sanctuaries. Layer 3: the spoiler layer.", "As Normal: the roster sets no Hard change to this plan's own steps. Spoiler layer: also answers a seat one step from a win ahead of the goal steps, except on its own announce turn.", new[] { "bot.sciel.01-spread", "bot.sciel.02-revolt", "bot.sciel.03-evict", "bot.sciel.04-organize", "bot.sciel.05-defend-aquafarms", "bot.sciel.06-teacher-group", "bot.sciel.07-finish", "bot.sciel.08-announce", "bot.sciel.09-spoiler" }),
            ["bot.verso"] = new BotPlanDef("bot.verso", "verso", "Approach mode at rank A or above (state.verso.rank >= tune.verso-perfection-rank) in Act II or later; the Monolith assault at rank A or S once step 4's test passes. Below A he climbs.", "The rank is public and he barks each rank-up. Any battle that lands a hit on him in the Monolith before his Birdsong drops him off S, and Ambush cards are the classic answer.", "Ignores Ambush risk when climbing, and waits for tune.verso-easy-assault-swords (4) undamaged swords before assaulting the Monolith. Spoiler layer: answers only a banner that is up, and only with actions the plan leaves free.", "Layer 1: the legal Vagabond (Ranger) actions from Root's legal-action API (read.legal-actions); Root's own AI keeps hit allocation, Ambush and discards and plays any decision no step claims. Layer 2 filters fights, in priority order: below rank A climb with safe battles only; repair after any damage; at rank A from Act II approach the Monolith; assault it only when it can be cleared this turn with expected damage under 1; bail to a forest if the rank drops below A mid-assault; in Act II or later walk into Esquie's clearing when he can reach it. Layer 3: the spoiler layer. Bots always need rank S: the Easy rank-A assist is for a human Verso only.", "As Normal: the roster sets no Hard change to this plan's own steps. Spoiler layer: also answers a seat one step from a win ahead of the goal steps, except on its own announce turn.", new[] { "bot.verso.01-climb", "bot.verso.02-repair", "bot.verso.03-approach", "bot.verso.04-assault", "bot.verso.05-bail", "bot.verso.06-reunion", "bot.verso.07-spoiler" }),
            ["bot.maelle"] = new BotPlanDef("bot.maelle", "maelle", "Goal mode once the relationship parts of win.maelle hold: Allied with tune.maelle-allied (2) non-Vagabond factions (with only one non-Vagabond faction seated: Allied with it) and Hostile with none.", "The relationship track is public and she says who her family is. Attacking her in Lumière damages items and fails the check, and the goal takes many Aid cards.", "Aids once per turn and does not repair before arriving in Lumière. Spoiler layer: answers only a banner that is up, and only with actions the plan leaves free.", "Layer 1: the legal Vagabond (Thief) actions from Root's legal-action API (read.legal-actions); Root's own AI keeps hit allocation, Ambush and discards and plays any decision no step claims. Layer 2 chooses who she helps, in priority order: pick a family of two non-Hostile factions; Aid them each Daylight; no fights with non-Hostile factions unless one is within 5 VP of winning (Disarm the VP leader, quests and ruins for VP); once the relationships hold, go to Lumière with 3+ undamaged items and stay; with only one non-Vagabond faction seated, one family member and 15 VP. Layer 3: the spoiler layer.", "As Normal: the roster sets no Hard change to this plan's own steps. Spoiler layer: also answers a seat one step from a win ahead of the goal steps, except on its own announce turn.", new[] { "bot.maelle.01-family", "bot.maelle.02-aid", "bot.maelle.03-no-fights", "bot.maelle.04-goal-mode", "bot.maelle.05-two-player", "bot.maelle.06-spoiler" }),
            ["bot.lune"] = new BotPlanDef("bot.lune", "lune", "Act II, once the Parents' Journal is tagged (state.lune.tagged-relic set): her goals become the Journal plus any missing relic type. In Act I she plays normal Keepers, recovering missing types first.", "The gold forest sits in the Monolith hot zone, carriers can be intercepted (the attacker scores Prized Trophies and the Journal drops face up, still tagged), and she announces the journal run a turn early.", "Single-warrior carriers (no convoy of tune.lune-convoy-size). Spoiler layer: answers only a banner that is up, and only with actions the plan leaves free.", "Layer 1: the legal Keepers actions from Root's legal-action API (read.legal-actions), with Root's own Keepers AI if the digital game has one (unconfirmed, a week-1 spike item), otherwise the mod's fallback planner with the same priorities; that AI keeps hit allocation, Ambush and discards and plays any decision no step claims. Layer 2, in priority order: in Act I delve and recover missing relic types first; from Act II chase the Parents' Journal or a missing type, whichever is closer; fill the Retinue with cards matching the route; delve the Journal only with 3+ warriors next to its forest; escort carriers in groups of 2+ to a waystation of their type; ignore duplicate types unless she needs VP. Layer 3: the spoiler layer.", "Runs two convoys at once. Spoiler layer: also answers a seat one step from a win ahead of the goal steps, except on its own announce turn.", new[] { "bot.lune.01-act1", "bot.lune.02-act2-goals", "bot.lune.03-retinue", "bot.lune.04-delve", "bot.lune.05-escort", "bot.lune.06-duplicates", "bot.lune.07-spoiler" }),
            ["bot.monoco"] = new BotPlanDef("bot.monoco", "monoco", "Feet-driven from his first Daylight: every reachable Warlord battle is scored by the feet it fills. Escort mode once he holds tune.monoco-bot-escort-after-feet (3) feet.", "The wheel and its source factions are public, he announces his next 'duel', and the Warlord is one exposed pawn whose removal during the countdown costs a foot and Almighty.", "The Warlord advances alone (step 3 is skipped) and only when he outnumbers the defenders by tune.monoco-easy-outnumber (2). Spoiler layer: answers only a banner that is up, and only with actions the plan leaves free.", "Layer 1: the legal Hundreds (moods, the Gestral Stash, Oppress) actions from Root's legal-action API (read.legal-actions), with Root's own Hundreds AI if the digital game has one (unconfirmed, a week-1 spike item), otherwise the mod's fallback planner with the same priorities; that AI keeps hit allocation, Ambush and discards and plays any decision no step claims. Layer 2, in priority order: score the Warlord battles he can reach each Daylight by the feet they fill; pick targets per foot; Command-move rats in the turn before; pick the mood (mask) that boosts the planned battle; build Arenas along the route; after 3 feet keep 2+ Gestrals with the Warlord; on the announce turn end in his strongest enemy-free clearing. Layer 3: the spoiler layer.", "As Normal: the roster sets no Hard change to this plan's own steps. Spoiler layer: also answers a seat one step from a win ahead of the goal steps, except on its own announce turn.", new[] { "bot.monoco.01-battle-score", "bot.monoco.02-targets", "bot.monoco.03-bring-rats", "bot.monoco.04-mood", "bot.monoco.05-arenas", "bot.monoco.06-escort", "bot.monoco.07-announce", "bot.monoco.08-spoiler" }),
            ["bot.curator"] = new BotPlanDef("bot.curator", "curator", "Act III, once the Cell Crack has opened into a tunnel (state.curator.cell-crack is 'tunnel', or 'dig-owed' under the fallback). In Acts I-II he plays the helper.", "The Act III gate; Price of Failure, since every camp or stall destroyed strips a minister permanently; digging next to Lumière is a visible tell, and he announces the push. Keeping the Paintress's roost alive in the Monolith or Lumière heavily garrisoned blocks him.", "Never re-digs a lost tunnel and attacks Lumière only with defenders + tune.curator-easy-assault-margin (3). Spoiler layer: answers only a banner that is up, and only with actions the plan leaves free.", "Layer 1: the legal Duchy (sway, Parliament, building) actions from Root's legal-action API (read.legal-actions), with Root's own Duchy AI if the digital game has one (unconfirmed, a week-1 spike item), otherwise the mod's fallback planner with the same priorities; that AI keeps hit allocation, Ambush and discards and plays any decision no step claims. Layer 2, in priority order: in Acts I-II play the helper (camps, stalls, ministers, the Burrow stocked to 6+, no big fights, never attack the Paintress unless she is one step from her win); in Act III take her roost out of the Monolith through the Cell Crack with defenders + 2, then dig to Lumière and march in with defenders + 2; on the announce turn pour warriors into Lumière. Layer 3: the spoiler layer.", "As Normal: the roster sets no Hard change to this plan's own steps. Spoiler layer: also answers a seat one step from a win ahead of the goal steps, except on its own announce turn.", new[] { "bot.curator.01-helper", "bot.curator.02-reveal", "bot.curator.03-lumiere", "bot.curator.04-announce", "bot.curator.05-spoiler" }),
            ["bot.clea"] = new BotPlanDef("bot.clea", "clea", "Goal mode at tune.clea-goal-coverage (6) covered clearings (her warriors minus hosted guards, as in win.clea).", "Lone warriors fall to any battle, coverage shows on the public tracker, and conspiracies only work in the Outcast suit, which the other players shape with their discards.", "Half the time places warriors where she already has some, and never Sanctifies. Spoiler layer: answers only a banner that is up, and only with actions the plan leaves free.", "Layer 1: the legal Lizard Cult (rituals, conspiracies) actions from Root's legal-action API (read.legal-actions), with Root's own Lizard AI if the digital game has one (unconfirmed, a week-1 spike item), otherwise the mod's fallback planner with the same priorities; that AI keeps hit allocation, Ambush and discards and plays any decision no step claims. The Lizards have no normal Move, so coverage comes from placing and converting. Layer 2, in priority order: recruit into uncovered clearings; convert in Outcast-suit clearings without her warriors and sanctify the VP leader's buildings; keep a bird card for the Monolith; keep the Flying Manor atelier and a warrior there (rebuilding pre-empts); keep Outcast cards for conspiracies; from 6 covered clearings re-cover losses first (pre-empts); never move or count guard stacks. Layer 3: the spoiler layer.", "As Normal: the roster sets no Hard change to this plan's own steps. Spoiler layer: also answers a seat one step from a win ahead of the goal steps, except on its own announce turn.", new[] { "bot.clea.01-recruit", "bot.clea.02-convert", "bot.clea.03-monolith", "bot.clea.04-home", "bot.clea.05-hand", "bot.clea.06-goal-mode", "bot.clea.07-guards", "bot.clea.08-spoiler" }),
            ["bot.white-haired-man"] = new BotPlanDef("bot.white-haired-man", "white-haired-man", "Goal mode at Vp(seat) >= tune.white-haired-man-goal-vp (8).", "Exposure guesses strip plots, a Vagabond walking into the Monolith stops the check, lone Corvid warriors fall easily, and the check waits for his Birdsong.", "Leaves one Ring clearing to a single face-down plot. Spoiler layer: answers only a banner that is up, and only with actions the plan leaves free.", "Layer 1: the legal Corvid actions from Root's legal-action API (read.legal-actions), with Root's own Corvid AI if the digital game has one (unconfirmed, a week-1 spike item), otherwise the mod's fallback planner with the same priorities; that AI keeps hit allocation, Ambush and discards and plays any decision no step claims. The Goal Director uses only public board state plus his own hidden plots. Layer 2, in priority order: measure each Ring clearing's margin; recruit with Ring-suit cards; Snare the Ring clearing hardest to hold, Bomb gatherings, Raid as a refill; fix the lowest-margin Ring clearing first; never attack the Paintress unless she is one step from her win; from 8 VP never leave the Ring and battle any Vagabond in the Monolith. Layer 3: the spoiler layer.", "Keeps a margin of tune.white-haired-man-hard-margin (2) in every Ring clearing. Spoiler layer: also answers a seat one step from a win ahead of the goal steps, except on its own announce turn.", new[] { "bot.white-haired-man.01-ring-status", "bot.white-haired-man.02-recruit", "bot.white-haired-man.03-plots", "bot.white-haired-man.04-move-battle", "bot.white-haired-man.05-spare-paintress", "bot.white-haired-man.06-goal-mode", "bot.white-haired-man.07-spoiler" }),
        };

        public static readonly IReadOnlyDictionary<string, BotRuleDef> BotRules = new Dictionary<string, BotRuleDef>
        {
            ["bot.gustave.01-route"] = new BotRuleDef("bot.gustave.01-route", "bot.gustave", 1, "Route", "Each Birdsong (hook.birdsong-start), plan the Route: the cheapest path from Lumière to a Beachhead (a clearing next to the Monolith) whose clearings together cover fox, rabbit and mouse. The search runs over states (clearing, suits covered so far) along PathNeighbours (rivers are not paths) and saves the path in state.gustave.route. The later steps follow it and the goal-mode trigger reads its cost. Hard also re-plans whenever an action raises the cost of a Route clearing, routing around the blockade.", "cost(c) = 0 if c is in state.gustave.flags and Ruler(c) == seat (a ruled clearing holding his building counts as flagged, since it is flagged at the end of the turn); tune.gustave-route-cost-ruled (1) if Ruler(c) == seat otherwise; tune.gustave-route-cost-unruled (2) + enemy warriors in c if he does not rule it; plus tune.gustave-route-cost-full (3) when c has no free slot and none of its slots holds his building. Route cost = the sum of cost(c) over its clearings. Lowest-cost search over (clearing, suit set) from Lumière to any Beachhead with all three suits (a Lost City gives all three). Ties: fewer clearings, then lower clearing numbers in path order.", new[] { "read.clearings", "read.path-neighbours", "read.suits-of", "read.ruler", "read.warriors", "read.buildings", "read.free-slots", "read.total-slots", "read.seats" }, new[] { "state.gustave.route", "state.gustave.flags", "state.global.roles", "state.global.difficulty" }, new[] { "GustaveBot_RouteCostFollowsRuleFlagsAndSlots", "GustaveBot_RouteIsCheapestThreeSuitPathToBeachhead", "GustaveBot_HardReplansRouteAroundBlockade" }),
            ["bot.gustave.02-hold"] = new BotRuleDef("bot.gustave.02-hold", "bot.gustave", 2, "Hold first", "If a flagged clearing on the Route has lost rule (in state.gustave.flags and state.gustave.route, Ruler(c) != seat), recruit or march there to retake it before any later step. Hard also tops up every Chain clearing to a rule margin of tune.gustave-hard-rule-margin. Easy skips this step: it does not retake lost Chain clearings proactively.", "Lost Route clearings in Route order from Lumière. Warriors needed = (the ruler's warriors + buildings in c) - (his warriors + buildings in c) + 1. Recruit there if he has a recruiter in c, otherwise march from the neighbouring ruled clearing with the most warriors above its own needs. Hard margin(c) = his warriors + buildings in c - the most warriors + buildings any other seat has in c.", new[] { "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.path-neighbours", "read.seats", "read.legal-actions" }, new[] { "state.gustave.route", "state.gustave.flags", "state.global.difficulty" }, new[] { "GustaveBot_RetakesLostFlaggedRouteClearingFirst", "GustaveBot_EasyDoesNotRetakeLostChainClearings", "GustaveBot_HardKeepsRuleMarginTwoOnChain" }),
            ["bot.gustave.03-build"] = new BotRuleDef("bot.gustave.03-build", "bot.gustave", 3, "Build on the Route", "Build in the next ruled, unflagged Route clearing: a sawmill if that keeps wood connected, otherwise the cheapest track. The Beachhead gets a building as soon as he rules it. If no Route clearing can take a building, make the normal VP build (Root's Marquise AI chooses). Easy makes at most one Route build per turn.", "Order: the Beachhead first whenever he rules it and it holds no Marquise building; then ruled, unflagged Route clearings with a free slot, in Route order from Lumière. Building: a sawmill when no sawmill stands among the ruled clearings connected to it (so wood can reach later builds); otherwise the building whose track has the lowest next cost; ties: Root's Marquise AI picks.", new[] { "read.ruler", "read.free-slots", "read.buildings", "read.buildings-of-type", "read.tokens-of-type", "read.path-neighbours", "read.supply-pieces", "read.legal-actions" }, new[] { "state.gustave.route", "state.gustave.flags", "state.global.roles", "state.global.difficulty" }, new[] { "GustaveBot_BuildsInNextUnflaggedRouteClearing", "GustaveBot_BuildsBeachheadAsSoonAsRuled", "GustaveBot_EasyBuildsOnRouteOncePerTurn" }),
            ["bot.gustave.04-charge"] = new BotRuleDef("bot.gustave.04-charge", "bot.gustave", 4, "Charge the Arm", "While state.gustave.arm is under tune.gustave-arm-max, take at least one winnable battle per turn that removes an enemy piece, preferring enemy pieces on the Route: a battle he starts that removes an enemy piece charges the Arm and clears the road.", "Winnable: he has more warriors in the clearing than the defender, and his expected hits (the higher of two 0-3 dice, capped at his warriors there, +1 when the defender has no warriors) remove at least one piece. Order: Route clearings first, then by expected enemy pieces removed minus expected warriors lost; ties: nearer Lumière along the Route, then lower clearing number.", new[] { "read.warriors", "read.buildings", "read.tokens", "read.ruler", "read.seats", "read.legal-actions" }, new[] { "state.gustave.arm", "state.gustave.route" }, new[] { "GustaveBot_TakesWinnableBattleWhileArmNotFull", "GustaveBot_ChargePrefersEnemyPiecesOnRoute" }),
            ["bot.gustave.05-overcharge"] = new BotRuleDef("bot.gustave.05-overcharge", "bot.gustave", 5, "Overcharge", "Arm Overcharge (hook.ui-toggle) only for a battle that takes the Beachhead or retakes Lumière. In a turn he expects to announce he does not Overcharge, because emptying the Arm cancels the announce, unless that battle is required: he cannot win it without the extra hit and without it the Chain breaks (Lumière or the Beachhead lost). Easy never Overcharges.", "none (a plain condition: the Arm is at tune.gustave-arm-max and the battle is in the Beachhead or in a Lumière ruled by another seat; an expected announce turn is one where win.gustave's announce test would pass after this turn's planned actions)", new[] { "read.ruler", "read.warriors", "read.buildings", "read.legal-actions" }, new[] { "state.gustave.arm", "state.gustave.overcharge-armed", "state.gustave.route", "state.global.roles", "state.global.difficulty" }, new[] { "GustaveBot_OverchargesOnlyForBeachheadOrLumiere", "GustaveBot_NoOverchargeOnExpectedAnnounceTurn", "GustaveBot_EasyNeverOvercharges" }),
            ["bot.gustave.06-goal-mode"] = new BotRuleDef("bot.gustave.06-goal-mode", "bot.gustave", 6, "Goal mode", "In goal mode (Vp(seat) >= tune.gustave-goal-vp or Route cost <= tune.gustave-goal-route-cost; Easy: Vp(seat) >= tune.gustave-easy-goal-vp only), spend bird cards on extra Route actions and skip Overwork.", "none (a plain condition)", new[] { "read.vp", "read.hand-suits", "read.legal-actions" }, new[] { "state.gustave.route", "state.global.difficulty" }, new[] { "GustaveBot_GoalModeAtEightVpOrRouteCostFour", "GustaveBot_GoalModeSpendsBirdsOnRouteAndSkipsOverwork" }),
            ["bot.gustave.07-announce"] = new BotRuleDef("bot.gustave.07-announce", "bot.gustave", 7, "Announce turn", "On the announce turn (win.gustave's announce test will pass at the end of this turn if nothing changes), spend leftover actions thickening the Chain clearing with the thinnest margin of rule, then the Beachhead, and use Field Hospitals for warriors lost there.", "margin(c) = his warriors + buildings in c - the most warriors + buildings any other seat has in c. Chain clearings in ascending margin, then the Beachhead; ties: lower clearing number.", new[] { "read.ruler", "read.warriors", "read.buildings", "read.path-neighbours", "read.suits-of", "read.vp", "read.active-dominance", "read.hand-suits", "read.legal-actions" }, new[] { "state.gustave.flags", "state.gustave.arm", "state.global.roles", "state.global.act" }, new[] { "GustaveBot_AnnounceTurnThickensThinnestChainClearing", "GustaveBot_AnnounceTurnUsesFieldHospitalsInChain" }),
            ["bot.gustave.08-spoiler"] = new BotRuleDef("bot.gustave.08-spoiler", "bot.gustave", 8, "Spoiler layer", "Shared spoiler layer (layer 3 of every bot; this part of the text is the same in all eleven plans). TRIGGER: another seat, the human included, that is not this bot's coalition partner, whose themed win is unlocked in the current act (Act II on; the Curator's from Act III) and not switched off (not switched off by that win's offWithDominance / offInCoalition), and that either has its countdown banner up (state.global.countdowns) or is one step from its win. One step means the public Goal Tracker shows every part of that win's test met except exactly one unit: one Arm pip, Chain suit, rock, Portrait suit, Sanctuary or Sanctuary suit, rank step, Allied faction, undamaged item, relic type, foot or source faction, covered clearing or Ring clearing, or one yes/no part (the Beachhead, the Monolith, Lumière, the Flying Manor atelier, an Aquafarm, the Parents' Journal recovered, the Warlord on the map, the tune.countdown-vp gate). ANSWER: attack or block the key clearing with a real Root action from that win's counterplay. Gustave: flip rule of the Chain clearing with the thinnest margin, or remove the Beachhead's buildings. Esquie (3 rocks held): the Nevron host moves extra warriors onto the last guarded rock (more defenders deal more hits to him) and every other bot attacks his pawn to damage items. The Paintress: break an easel, flip rule of a Portrait clearing or thin it below tune.paintress-portrait-warriors warriors, or take the Monolith. Sciel: before her banner, step a piece into a Sanctuary (paying Outrage); once it is up, battle a Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm. Verso: before his banner, put a warrior, building or pawn in the Monolith (tokens do not block him); once it is up, battle him there and land a hit. Maelle: attack her in Lumière and damage items until fewer than tune.maelle-items are undamaged. Lune: battle the warriors carrying the Parents' Journal or her missing relic type, and hold the clearings around the gold forest. Monoco: battle the Warlord off the map (Sacred River Rebirth strips Almighty and his latest other foot). The Curator: flip rule of Lumière or remove his Monolith tunnel; with no keep in Lumière, raze his building there and cut his warriors below tune.curator-lumiere-warriors; keep the Paintress's roost in the Monolith alive. Clea: remove her warriors from one counted clearing (lone Nevrons first) or from the Monolith, or raze the Flying Manor atelier. The White-Haired Man: out-stack him in one Ring clearing, guess a plot with Exposure, or walk a Vagabond pawn into the Monolith. LIMITS: it obeys every rule tweak and every 'never' and 'only' in the steps above it, uses only public information plus this bot's own hand and hidden pieces, and barks the block. PRIORITY: with no trigger it does nothing. It is listed last, as in the roster, but takes the actions it needs ahead of the steps above (it pre-empts them) in two cases: a banner that is up, because that seat confirms before this bot's next Birdsong, unless this bot can finish a quest win this turn; and, on Hard only, a one-step threat, unless this is this bot's own announce turn (its own confirmation would land first). Otherwise it answers with the actions the steps above leave free. Easy answers banners only, and only with free actions. FOR GUSTAVE: his answers are Marquise marches, recruits and battles; he never Overcharges for a block, because step 5 allows it only for the Beachhead and Lumière.", "Threats: banners before one-step threats; then the seat whose next Birdsong comes first in turn order (read.seats from read.current-seat); then the higher VP. For the chosen threat, answer cost = actions needed this turn + expected hits taken (Root's dice: two 0-3 dice, the attacker deals the higher and the defender the lower, each capped by its warriors; +1 hit to a defender with no warriors). Take the cheapest legal answer, breaking a met part before blocking the missing unit; ties: the answer nearest this bot's pieces, then the lower clearing number.", new[] { "read.seats", "read.current-seat", "read.seat-engine", "read.vp", "read.active-dominance", "read.coalition-partner", "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.tokens", "read.tokens-of-type", "read.pawn-clearing", "read.items", "read.relationship", "read.path-neighbours", "read.suits-of", "read.clearings", "read.recovered-relics", "read.relic-type", "read.relic-clearing", "read.relic-forest", "read.forest-clearings", "read.corvid-face-up-plot", "read.legal-actions", "read.hand-suits", "read.is-bot" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.global.difficulty", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.monoco.feet", "state.lune.tagged-relic", "state.curator.cell-crack", "state.gustave.route", "state.gustave.overcharge-armed" }, new[] { "GustaveBot_SpoilerAnswersBannerBeforeOwnSteps", "GustaveBot_SpoilerNeverOverchargesToBlock" }),
            ["bot.esquie.01-target"] = new BotRuleDef("bot.esquie.01-target", "bot.esquie", 1, "Target", "Each Birdsong, choose the claimable rock to chase and save its index in state.esquie.target. Loose rocks come first, then Dorrie (Old Lumière, Act II on) when a torch is ready, then the rest by cost. For Soarrie he walks into Verso's clearing (withVerso) or, without Verso, first collects a card of the Monolith's suit for the Aid (heldByRuler); with nobody ruling the Monolith he just walks in. Easy walks to the François decoy at the Nest once in Act I while state.esquie.decoy is true.", "cost = path distance from his pawn + tune.esquie-bot-guard-weight (2) x GuardsLeft - his max hits there (undamaged swords, plus tune.esquie-belly-bounce-swords for an undamaged Bag in a guarded-rock clearing). Order: loose rocks by path distance; Dorrie when an undamaged, unexhausted torch is on his card and no Corvid warriors are in Old Lumière; then guarded rocks and Soarrie by cost (Soarrie: path distance to Verso's clearing, or to the Monolith). From a forest, path distance is counted from the nearest clearing touching it, +1. Ties: rock order Florrie, Dorrie, Soarrie, Urrie.", new[] { "read.pawn-clearing", "read.pawn-forest", "read.forest-clearings", "read.path-neighbours", "read.items", "read.hand-suits", "read.suits-of", "read.ruler", "read.warriors", "read.seats", "read.seat-engine" }, new[] { "state.esquie.rocks", "state.esquie.target", "state.esquie.decoy", "state.global.roles", "state.global.act", "state.global.seat-characters", "state.global.difficulty" }, new[] { "EsquieBot_TargetCostIsDistancePlusTwiceGuardsMinusMaxHits", "EsquieBot_LooseRocksBeforeGuardedRocks", "EsquieBot_EasyVisitsFrancoisDecoyOnceInActOne" }),
            ["bot.esquie.02-gear"] = new BotRuleDef("bot.esquie.02-gear", "bot.esquie", 2, "Gear", "With tune.esquie-bot-repair-damaged (2) or more damaged items he repairs in a forest first (he ends his move in a forest so the Evening rest repairs them). If he could deal no hits in his target's clearing (no undamaged sword and no Belly Bounce), he crafts or Aids for a sword instead of attacking. Hard crafts a sword as soon as one is craftable.", "Repair comes before any guard battle. Sword source: craft one if a sword is craftable, otherwise Aid the nearest faction holding a crafted sword (read.crafted-items); ties: lower clearing number.", new[] { "read.items", "read.pawn-forest", "read.forests-around", "read.crafted-items", "read.hand-suits", "read.relationship", "read.seats", "read.legal-actions" }, new[] { "state.esquie.target", "state.esquie.rocks", "state.global.difficulty" }, new[] { "EsquieBot_RepairsInForestAtTwoDamagedItems", "EsquieBot_SeeksSwordWhenHeCanDealNoHits", "EsquieBot_HardCraftsSwordEarly" }),
            ["bot.esquie.03-friends"] = new BotRuleDef("bot.esquie.03-friends", "bot.esquie", 3, "Friends", "If a Friendly or Allied faction that is not the rock's Nevron host has warriors next to a guard stack, he Aids it there. Every bot whose seat is Friendly or Allied with Esquie and has warriors in or next to the clearing of his current (publicly barked) target then gets a small 'help Esquie' bonus for battling the guards, applied only when it costs its own goal nothing. Easy never asks friends for help.", "Friends in order: most warriors next to the stack, then Allied before Friendly, then lower VP. The bonus is a tie-break only: among a friend bot's equally scored choices, a battle against the host's warriors in a guarded-rock clearing wins the tie.", new[] { "read.relationship", "read.warriors", "read.path-neighbours", "read.pawn-clearing", "read.hand-suits", "read.suits-of", "read.vp", "read.seats", "read.legal-actions" }, new[] { "state.esquie.rocks", "state.esquie.target", "state.global.difficulty" }, new[] { "EsquieBot_AidsFriendlyNonHostNextToGuards", "EsquieBot_HelpBonusOnlyBreaksTies", "EsquieBot_EasyNeverAsksFriends", "EsquieBot_HelpBonusOnlyForFriendsNearTarget" }),
            ["bot.esquie.04-hunt"] = new BotRuleDef("bot.esquie.04-hunt", "bot.esquie", 4, "Hunt", "He enters a guarded-rock clearing and battles the host's guards only with every item undamaged, and only when his expected hits this turn can finish or nearly finish the guards. One guard battle per turn (tune.esquie-bot-guard-battles); two on Hard (tune.esquie-hard-guard-battles).", "expected hits this turn = the sum, over the guard battles he may take, of E[min(higher of two 0-3 dice, max hits)], where max hits = undamaged swords + the Bag under Belly Bounce. Enter only if expected hits >= GuardsLeft - 1.", new[] { "read.items", "read.warriors", "read.pawn-clearing", "read.path-neighbours", "read.legal-actions" }, new[] { "state.esquie.rocks", "state.esquie.target", "state.global.difficulty" }, new[] { "EsquieBot_HuntsOnlyWithAllItemsUndamaged", "EsquieBot_HuntsWhenExpectedHitsNearlyFinishGuards", "EsquieBot_HardTakesTwoGuardBattlesPerTurn" }),
            ["bot.esquie.05-endgame"] = new BotRuleDef("bot.esquie.05-endgame", "bot.esquie", 5, "Endgame", "With tune.esquie-endgame-rocks (3) rocks held, he goes straight for the last one: it is the target whatever its distance, and step 6's VP play no longer applies.", "Shortest path to the last rock (to Verso's clearing for a withVerso Soarrie, to the Monolith for a heldByRuler Soarrie).", new[] { "read.pawn-clearing", "read.pawn-forest", "read.path-neighbours", "read.legal-actions" }, new[] { "state.esquie.rocks", "state.esquie.target" }, new[] { "EsquieBot_EndgameGoesStraightForLastRock" }),
            ["bot.esquie.06-vp"] = new BotRuleDef("bot.esquie.06-vp", "bot.esquie", 6, "Vagabond VP", "If no claimable rock is within tune.esquie-bot-rock-range (3) moves, he plays normal Vagabond VP (quests, Aid, ruins): this step claims no decision and Root's Vagabond AI chooses.", "none (a plain condition: no claimable rock within range)", new[] { "read.pawn-clearing", "read.path-neighbours", "read.has-ruin", "read.legal-actions" }, new[] { "state.esquie.rocks" }, new[] { "EsquieBot_PlaysVagabondVpWhenNoRockWithinThreeMoves" }),
            ["bot.esquie.07-spoiler"] = new BotRuleDef("bot.esquie.07-spoiler", "bot.esquie", 7, "Spoiler layer", "Shared spoiler layer (layer 3 of every bot; this part of the text is the same in all eleven plans). TRIGGER: another seat, the human included, that is not this bot's coalition partner, whose themed win is unlocked in the current act (Act II on; the Curator's from Act III) and not switched off (not switched off by that win's offWithDominance / offInCoalition), and that either has its countdown banner up (state.global.countdowns) or is one step from its win. One step means the public Goal Tracker shows every part of that win's test met except exactly one unit: one Arm pip, Chain suit, rock, Portrait suit, Sanctuary or Sanctuary suit, rank step, Allied faction, undamaged item, relic type, foot or source faction, covered clearing or Ring clearing, or one yes/no part (the Beachhead, the Monolith, Lumière, the Flying Manor atelier, an Aquafarm, the Parents' Journal recovered, the Warlord on the map, the tune.countdown-vp gate). ANSWER: attack or block the key clearing with a real Root action from that win's counterplay. Gustave: flip rule of the Chain clearing with the thinnest margin, or remove the Beachhead's buildings. Esquie (3 rocks held): the Nevron host moves extra warriors onto the last guarded rock (more defenders deal more hits to him) and every other bot attacks his pawn to damage items. The Paintress: break an easel, flip rule of a Portrait clearing or thin it below tune.paintress-portrait-warriors warriors, or take the Monolith. Sciel: before her banner, step a piece into a Sanctuary (paying Outrage); once it is up, battle a Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm. Verso: before his banner, put a warrior, building or pawn in the Monolith (tokens do not block him); once it is up, battle him there and land a hit. Maelle: attack her in Lumière and damage items until fewer than tune.maelle-items are undamaged. Lune: battle the warriors carrying the Parents' Journal or her missing relic type, and hold the clearings around the gold forest. Monoco: battle the Warlord off the map (Sacred River Rebirth strips Almighty and his latest other foot). The Curator: flip rule of Lumière or remove his Monolith tunnel; with no keep in Lumière, raze his building there and cut his warriors below tune.curator-lumiere-warriors; keep the Paintress's roost in the Monolith alive. Clea: remove her warriors from one counted clearing (lone Nevrons first) or from the Monolith, or raze the Flying Manor atelier. The White-Haired Man: out-stack him in one Ring clearing, guess a plot with Exposure, or walk a Vagabond pawn into the Monolith. LIMITS: it obeys every rule tweak and every 'never' and 'only' in the steps above it, uses only public information plus this bot's own hand and hidden pieces, and barks the block. PRIORITY: with no trigger it does nothing. It is listed last, as in the roster, but takes the actions it needs ahead of the steps above (it pre-empts them) in two cases: a banner that is up, because that seat confirms before this bot's next Birdsong, unless this bot can finish a quest win this turn; and, on Hard only, a one-step threat, unless this is this bot's own announce turn (its own confirmation would land first). Otherwise it answers with the actions the steps above leave free. Easy answers banners only, and only with free actions. FOR ESQUIE: Never Mad bars every battle and Strike except against host guards, so he never attacks to spoil. He answers only by moving his pawn: into the Monolith against the White-Haired Man (it fails his announce and his confirmation), into the Monolith before Verso's banner, or into a would-be Sanctuary before Sciel's banner. A quest win he can finish this turn always comes first.", "Threats: banners before one-step threats; then the seat whose next Birdsong comes first in turn order (read.seats from read.current-seat); then the higher VP. For the chosen threat, answer cost = actions needed this turn + expected hits taken (Root's dice: two 0-3 dice, the attacker deals the higher and the defender the lower, each capped by its warriors; +1 hit to a defender with no warriors). Take the cheapest legal answer, breaking a met part before blocking the missing unit; ties: the answer nearest this bot's pieces, then the lower clearing number.", new[] { "read.seats", "read.current-seat", "read.seat-engine", "read.vp", "read.active-dominance", "read.coalition-partner", "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.tokens", "read.tokens-of-type", "read.pawn-clearing", "read.items", "read.relationship", "read.path-neighbours", "read.suits-of", "read.clearings", "read.recovered-relics", "read.relic-type", "read.relic-clearing", "read.relic-forest", "read.forest-clearings", "read.corvid-face-up-plot", "read.legal-actions", "read.pawn-forest", "read.is-bot" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.global.difficulty", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.monoco.feet", "state.lune.tagged-relic", "state.curator.cell-crack", "state.esquie.target" }, new[] { "EsquieBot_SpoilerBlocksOnlyByMovingPawn", "EsquieBot_SpoilerYieldsToOwnQuestWinThisTurn" }),
            ["bot.paintress.01-site"] = new BotRuleDef("bot.paintress.01-site", "bot.paintress", 1, "Site score", "For each suit still lacking a Living Portrait, score the clearings of that suit outside the Monolith that have a free slot, and target the best for her next roost (Easel). Bots bark their next goal move; Easy barks the next Portrait a turn early.", "site(c) = tune.paintress-site-adjacent (+3) if c is next to a clearing she rules + tune.paintress-site-near-monolith (+2) if c is within tune.paintress-site-near-monolith-steps (2) path steps of the Monolith + tune.paintress-site-enemy-warrior (-1) per enemy warrior in c + tune.paintress-site-guarded-rock (-3) if c holds a guarded rock. Clearings in state.paintress.repaint-avoid are skipped. Best suit = the missing suit with the highest best site; ties: lower clearing number.", new[] { "read.clearings", "read.suits-of", "read.free-slots", "read.ruler", "read.path-neighbours", "read.warriors", "read.buildings-of-type", "read.seats" }, new[] { "state.esquie.rocks", "state.paintress.repaint-avoid", "state.global.roles", "state.global.difficulty" }, new[] { "PaintressBot_SiteScoreMatchesFormula", "PaintressBot_SiteSkipsSuitsWithLivingPortrait", "PaintressBot_EasyBarksNextPortraitATurnEarly" }),
            ["bot.paintress.02-decree"] = new BotRuleDef("bot.paintress.02-decree", "bot.paintress", 2, "Decree", "When adding cards to the Decree, prefer a Build card of the best missing suit (step 1) and a Recruit card (a bird, or the suit of a Portrait with fewer than tune.paintress-portrait-warriors warriors). The lookahead remembers that Build cards repeat every turn, so once two suits are done she prefers a bird Build card. She never adds a card the lookahead says may fail.", "Candidates in order: Build of the best missing suit, then Recruit (bird first, then the suit of the thinnest Portrait); once two suits have Living Portraits, a bird Build card before a suited one. A candidate is dropped if the one-turn lookahead (the Decree plus the card, against the board after this turn's planned actions) finds a column it cannot resolve.", new[] { "read.eyrie-decree", "read.eyrie-leader", "read.hand-suits", "read.suits-of", "read.ruler", "read.free-slots", "read.buildings-of-type", "read.warriors", "read.supply-pieces", "read.legal-actions" }, new[] { "state.global.roles" }, new[] { "PaintressBot_DecreePrefersBuildOfBestMissingSuit", "PaintressBot_PrefersBirdBuildAfterTwoSuits", "PaintressBot_NeverAddsCardLookaheadSaysMayFail" }),
            ["bot.paintress.03-garrison"] = new BotRuleDef("bot.paintress.03-garrison", "bot.paintress", 3, "Garrison", "Spare moves bring every Portrait up to tune.paintress-portrait-warriors (2) warriors (Hard: tune.paintress-hard-portrait-warriors, 3). She keeps tune.paintress-monolith-garrison (3) or more warriors in the Monolith and recruits there first when enemy warriors stand in a clearing next to it.", "The Monolith first whenever it holds fewer than 3 of her warriors or enemy warriors are next to it; then Portraits in ascending warriors (hosted guards not counted), then by enemy warriors next to them; ties: lower clearing number.", new[] { "read.warriors", "read.buildings-of-type", "read.ruler", "read.path-neighbours", "read.eyrie-decree", "read.seats", "read.legal-actions" }, new[] { "state.esquie.rocks", "state.global.roles", "state.global.difficulty" }, new[] { "PaintressBot_GarrisonsPortraitsToTwoWarriors", "PaintressBot_KeepsThreeInMonolithAndRecruitsThereUnderThreat", "PaintressBot_HardGarrisonsThreePerPortrait" }),
            ["bot.paintress.04-finish"] = new BotRuleDef("bot.paintress.04-finish", "bot.paintress", 4, "Finish mode", "In finish mode (Vp(seat) >= tune.paintress-goal-vp with tune.paintress-finish-portraits Living Portraits), add exactly the cards that build and stock the third Portrait, and battle only to retake rule of the Monolith or a Portrait clearing. Easy adds one card too many, which often causes Grief.", "Cards needed = one Build of the missing suit + the Recruit or Move cards that put tune.paintress-portrait-warriors warriors there, checked by the lookahead; nothing else is added (Easy: one extra card).", new[] { "read.vp", "read.eyrie-decree", "read.hand-suits", "read.buildings-of-type", "read.warriors", "read.ruler", "read.suits-of", "read.legal-actions" }, new[] { "state.esquie.rocks", "state.global.roles", "state.global.difficulty" }, new[] { "PaintressBot_FinishModeAddsExactCardsForThirdPortrait", "PaintressBot_FinishModeBattlesOnlyToRetakeRule", "PaintressBot_EasyAddsOneCardTooManyInFinishMode" }),
            ["bot.paintress.05-repaint"] = new BotRuleDef("bot.paintress.05-repaint", "bot.paintress", 5, "Repaint", "A destroyed Portrait is rebuilt elsewhere: the clearing where it fell goes into state.paintress.repaint-avoid and the site score skips it for tune.paintress-repaint-avoid-turns (2) of her turns.", "Step 1's site score without the avoided clearings.", new[] { "read.buildings-of-type", "read.suits-of", "read.free-slots" }, new[] { "state.paintress.repaint-avoid" }, new[] { "PaintressBot_RepaintAvoidsSameClearingForTwoTurns" }),
            ["bot.paintress.06-spare-white-haired-man"] = new BotRuleDef("bot.paintress.06-spare-white-haired-man", "bot.paintress", 6, "Attack the White-Haired Man last", "She deprioritises attacking the White-Haired Man: among the battles the steps above would take, his pieces are her last choice. The spoiler layer (step 7) still attacks him like anyone else.", "Battle targets keep the order the steps above give them, except that every battle against the White-Haired Man's seat moves to the end of the list.", new[] { "read.seats", "read.legal-actions" }, new[] { "state.global.seat-characters" }, new[] { "PaintressBot_AttacksWhiteHairedManLast" }),
            ["bot.paintress.07-spoiler"] = new BotRuleDef("bot.paintress.07-spoiler", "bot.paintress", 7, "Spoiler layer", "Shared spoiler layer (layer 3 of every bot; this part of the text is the same in all eleven plans). TRIGGER: another seat, the human included, that is not this bot's coalition partner, whose themed win is unlocked in the current act (Act II on; the Curator's from Act III) and not switched off (not switched off by that win's offWithDominance / offInCoalition), and that either has its countdown banner up (state.global.countdowns) or is one step from its win. One step means the public Goal Tracker shows every part of that win's test met except exactly one unit: one Arm pip, Chain suit, rock, Portrait suit, Sanctuary or Sanctuary suit, rank step, Allied faction, undamaged item, relic type, foot or source faction, covered clearing or Ring clearing, or one yes/no part (the Beachhead, the Monolith, Lumière, the Flying Manor atelier, an Aquafarm, the Parents' Journal recovered, the Warlord on the map, the tune.countdown-vp gate). ANSWER: attack or block the key clearing with a real Root action from that win's counterplay. Gustave: flip rule of the Chain clearing with the thinnest margin, or remove the Beachhead's buildings. Esquie (3 rocks held): the Nevron host moves extra warriors onto the last guarded rock (more defenders deal more hits to him) and every other bot attacks his pawn to damage items. The Paintress: break an easel, flip rule of a Portrait clearing or thin it below tune.paintress-portrait-warriors warriors, or take the Monolith. Sciel: before her banner, step a piece into a Sanctuary (paying Outrage); once it is up, battle a Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm. Verso: before his banner, put a warrior, building or pawn in the Monolith (tokens do not block him); once it is up, battle him there and land a hit. Maelle: attack her in Lumière and damage items until fewer than tune.maelle-items are undamaged. Lune: battle the warriors carrying the Parents' Journal or her missing relic type, and hold the clearings around the gold forest. Monoco: battle the Warlord off the map (Sacred River Rebirth strips Almighty and his latest other foot). The Curator: flip rule of Lumière or remove his Monolith tunnel; with no keep in Lumière, raze his building there and cut his warriors below tune.curator-lumiere-warriors; keep the Paintress's roost in the Monolith alive. Clea: remove her warriors from one counted clearing (lone Nevrons first) or from the Monolith, or raze the Flying Manor atelier. The White-Haired Man: out-stack him in one Ring clearing, guess a plot with Exposure, or walk a Vagabond pawn into the Monolith. LIMITS: it obeys every rule tweak and every 'never' and 'only' in the steps above it, uses only public information plus this bot's own hand and hidden pieces, and barks the block. PRIORITY: with no trigger it does nothing. It is listed last, as in the roster, but takes the actions it needs ahead of the steps above (it pre-empts them) in two cases: a banner that is up, because that seat confirms before this bot's next Birdsong, unless this bot can finish a quest win this turn; and, on Hard only, a one-step threat, unless this is this bot's own announce turn (its own confirmation would land first). Otherwise it answers with the actions the steps above leave free. Easy answers banners only, and only with free actions. FOR THE PAINTRESS: step 6 does not apply here, so she attacks the White-Haired Man like anyone else. Her answers must fit the Decree: a card is added for a block only when the lookahead says it cannot cause Grief.", "Threats: banners before one-step threats; then the seat whose next Birdsong comes first in turn order (read.seats from read.current-seat); then the higher VP. For the chosen threat, answer cost = actions needed this turn + expected hits taken (Root's dice: two 0-3 dice, the attacker deals the higher and the defender the lower, each capped by its warriors; +1 hit to a defender with no warriors). Take the cheapest legal answer, breaking a met part before blocking the missing unit; ties: the answer nearest this bot's pieces, then the lower clearing number.", new[] { "read.seats", "read.current-seat", "read.seat-engine", "read.vp", "read.active-dominance", "read.coalition-partner", "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.tokens", "read.tokens-of-type", "read.pawn-clearing", "read.items", "read.relationship", "read.path-neighbours", "read.suits-of", "read.clearings", "read.recovered-relics", "read.relic-type", "read.relic-clearing", "read.relic-forest", "read.forest-clearings", "read.corvid-face-up-plot", "read.legal-actions", "read.eyrie-decree", "read.hand-suits", "read.is-bot" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.global.difficulty", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.monoco.feet", "state.lune.tagged-relic", "state.curator.cell-crack" }, new[] { "PaintressBot_SpoilerStillAttacksWhiteHairedMan", "PaintressBot_SpoilerOwnAnnounceTurnBeforeOneStepThreat" }),
            ["bot.sciel.01-spread"] = new BotRuleDef("bot.sciel.01-spread", "bot.sciel", 1, "Spread", "Spread into the best-scoring legal clearing. Never spread into a clearing with tune.sciel-spread-max-enemy (2) or more enemy pieces, or under Martial Law.", "spread(c) = tune.sciel-spread-base (3) - enemy pieces in c (warriors, buildings, tokens and pawns) - enemy warriors in clearings next to c + tune.sciel-spread-new-suit (+2) if c's suit has no Sanctuary yet; ties: lower clearing number.", new[] { "read.tokens-of-type", "read.warriors", "read.buildings", "read.tokens", "read.pawn-clearing", "read.path-neighbours", "read.suits-of", "read.clearings", "read.seats", "read.alliance-supporters", "read.legal-actions" }, Array.Empty<string>(), new[] { "ScielBot_SpreadScoreMatchesFormula", "ScielBot_NeverSpreadsIntoTwoEnemyPiecesOrMartialLaw" }),
            ["bot.sciel.02-revolt"] = new BotRuleDef("bot.sciel.02-revolt", "bot.sciel", 2, "Revolt", "Revolt in a sympathetic clearing holding enemy buildings or tokens, in a suit with no Aquafarm, ideally one that becomes a Sanctuary at once (Revolt clears every enemy piece there). Keep tune.sciel-revolt-supporters (2) matching supporters ready for the next one. Easy, half the time, takes the first legal Revolt instead.", "Order: clearings that become a Sanctuary at once (no Vagabond pawn left there) first, then by enemy buildings + tokens removed; ties: a suit with no Sanctuary yet, then lower clearing number. She keeps 2 supporters of the next-best target's suit unspent.", new[] { "read.tokens-of-type", "read.buildings", "read.tokens", "read.buildings-of-type", "read.pawn-clearing", "read.suits-of", "read.alliance-supporters", "read.seats", "read.legal-actions" }, new[] { "state.global.difficulty" }, new[] { "ScielBot_RevoltsWhereItMakesASanctuary", "ScielBot_KeepsTwoMatchingSupportersReady", "ScielBot_EasySometimesTakesFirstLegalRevolt" }),
            ["bot.sciel.03-evict"] = new BotRuleDef("bot.sciel.03-evict", "bot.sciel", 3, "Evict", "In Evening (Operations), battle lone enemy warriors or tokens on her Lanterns, preferring an Evening with Twilight armed once v1.1 adds it. Easy evicts only with a 2:1 edge.", "Targets: sympathetic clearings holding exactly one enemy warrior, or enemy tokens and no enemy warriors. Order: clearings that become a Sanctuary after the battle first, then fewest enemy pieces; ties: lower clearing number. Easy needs her warriors there >= tune.sciel-easy-evict-ratio x the enemy pieces there.", new[] { "read.phase", "read.tokens-of-type", "read.warriors", "read.tokens", "read.buildings", "read.pawn-clearing", "read.alliance-officers", "read.seats", "read.legal-actions" }, new[] { "state.sciel.twilight-armed", "state.global.difficulty" }, new[] { "ScielBot_EvictsLoneEnemyFromLantern", "ScielBot_EasyEvictsOnlyWithTwoToOne", "ScielBot_PrefersTwilightEveningToEvict" }),
            ["bot.sciel.04-organize"] = new BotRuleDef("bot.sciel.04-organize", "bot.sciel", 4, "Organize", "Organize (remove one of her warriors to place a Lantern) when the Sun gauge is short of tune.sciel-sanctuaries Sanctuaries and a warrior is idle (no other step needs it this turn).", "Idle warriors in clearings without her Lantern, ordered by step 1's spread score for the clearing they stand in.", new[] { "read.warriors", "read.tokens-of-type", "read.supply-pieces", "read.legal-actions" }, Array.Empty<string>(), new[] { "ScielBot_OrganizesIdleWarriorWhenSunShort" }),
            ["bot.sciel.05-defend-aquafarms"] = new BotRuleDef("bot.sciel.05-defend-aquafarms", "bot.sciel", 5, "Recruit at threatened Aquafarms", "Recruit at an Aquafarm (base) that is threatened: enemy warriors in its clearing or in a clearing next to it.", "Aquafarms by enemy warriors in and next to their clearing, most first; ties: lower clearing number.", new[] { "read.buildings-of-type", "read.warriors", "read.path-neighbours", "read.seats", "read.legal-actions" }, Array.Empty<string>(), new[] { "ScielBot_RecruitsAtThreatenedAquafarm" }),
            ["bot.sciel.06-teacher-group"] = new BotRuleDef("bot.sciel.06-teacher-group", "bot.sciel", 6, "Teacher-led group", "Keep one Teacher-led group (her biggest warrior stack, moved by her officers' Operations) in or beside her biggest Lantern cluster.", "Lantern cluster = sympathetic clearings joined by paths; biggest = most clearings (ties: most Sanctuaries). If the group is elsewhere it moves toward the cluster by the shortest path.", new[] { "read.tokens-of-type", "read.warriors", "read.path-neighbours", "read.alliance-officers", "read.legal-actions" }, Array.Empty<string>(), new[] { "ScielBot_KeepsTeacherGroupBesideBiggestLanternCluster" }),
            ["bot.sciel.07-finish"] = new BotRuleDef("bot.sciel.07-finish", "bot.sciel", 7, "Finish mode", "In finish mode (tune.sciel-finish-sanctuaries Sanctuaries), hoard supporters, spending them only on the Spread or Revolt that makes her next Sanctuary, and never pull warriors out of the cluster.", "none (a plain condition)", new[] { "read.tokens-of-type", "read.warriors", "read.buildings", "read.tokens", "read.pawn-clearing", "read.alliance-supporters", "read.legal-actions" }, Array.Empty<string>(), new[] { "ScielBot_FinishModeHoardsSupporters", "ScielBot_FinishModeNeverPullsWarriorsFromCluster" }),
            ["bot.sciel.08-announce"] = new BotRuleDef("bot.sciel.08-announce", "bot.sciel", 8, "Announce turn", "On the announce turn (win.sciel's announce test will pass at the end of this turn), end with her own warriors on the most exposed Sanctuaries (her warriors don't break a Sanctuary, and Guerrilla War makes attacks costly) and keep supporters for Outrage income.", "exposure(c) = enemy warriors in clearings next to c. Sanctuaries in descending exposure, one warrior each before a second anywhere; ties: lower clearing number.", new[] { "read.tokens-of-type", "read.warriors", "read.path-neighbours", "read.alliance-supporters", "read.seats", "read.legal-actions" }, new[] { "state.global.act" }, new[] { "ScielBot_AnnounceTurnGarrisonsMostExposedSanctuaries", "ScielBot_AnnounceTurnKeepsSupporters" }),
            ["bot.sciel.09-spoiler"] = new BotRuleDef("bot.sciel.09-spoiler", "bot.sciel", 9, "Spoiler layer", "Shared spoiler layer (layer 3 of every bot; this part of the text is the same in all eleven plans). TRIGGER: another seat, the human included, that is not this bot's coalition partner, whose themed win is unlocked in the current act (Act II on; the Curator's from Act III) and not switched off (not switched off by that win's offWithDominance / offInCoalition), and that either has its countdown banner up (state.global.countdowns) or is one step from its win. One step means the public Goal Tracker shows every part of that win's test met except exactly one unit: one Arm pip, Chain suit, rock, Portrait suit, Sanctuary or Sanctuary suit, rank step, Allied faction, undamaged item, relic type, foot or source faction, covered clearing or Ring clearing, or one yes/no part (the Beachhead, the Monolith, Lumière, the Flying Manor atelier, an Aquafarm, the Parents' Journal recovered, the Warlord on the map, the tune.countdown-vp gate). ANSWER: attack or block the key clearing with a real Root action from that win's counterplay. Gustave: flip rule of the Chain clearing with the thinnest margin, or remove the Beachhead's buildings. Esquie (3 rocks held): the Nevron host moves extra warriors onto the last guarded rock (more defenders deal more hits to him) and every other bot attacks his pawn to damage items. The Paintress: break an easel, flip rule of a Portrait clearing or thin it below tune.paintress-portrait-warriors warriors, or take the Monolith. Sciel: before her banner, step a piece into a Sanctuary (paying Outrage); once it is up, battle a Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm. Verso: before his banner, put a warrior, building or pawn in the Monolith (tokens do not block him); once it is up, battle him there and land a hit. Maelle: attack her in Lumière and damage items until fewer than tune.maelle-items are undamaged. Lune: battle the warriors carrying the Parents' Journal or her missing relic type, and hold the clearings around the gold forest. Monoco: battle the Warlord off the map (Sacred River Rebirth strips Almighty and his latest other foot). The Curator: flip rule of Lumière or remove his Monolith tunnel; with no keep in Lumière, raze his building there and cut his warriors below tune.curator-lumiere-warriors; keep the Paintress's roost in the Monolith alive. Clea: remove her warriors from one counted clearing (lone Nevrons first) or from the Monolith, or raze the Flying Manor atelier. The White-Haired Man: out-stack him in one Ring clearing, guess a plot with Exposure, or walk a Vagabond pawn into the Monolith. LIMITS: it obeys every rule tweak and every 'never' and 'only' in the steps above it, uses only public information plus this bot's own hand and hidden pieces, and barks the block. PRIORITY: with no trigger it does nothing. It is listed last, as in the roster, but takes the actions it needs ahead of the steps above (it pre-empts them) in two cases: a banner that is up, because that seat confirms before this bot's next Birdsong, unless this bot can finish a quest win this turn; and, on Hard only, a one-step threat, unless this is this bot's own announce turn (its own confirmation would land first). Otherwise it answers with the actions the steps above leave free. Easy answers banners only, and only with free actions. FOR SCIEL: her answers are a Revolt in a key clearing that holds her Lantern (it removes every enemy piece there) and Evening Operations moves and battles. In finish mode she never pulls warriors out of the cluster for a block (step 7).", "Threats: banners before one-step threats; then the seat whose next Birdsong comes first in turn order (read.seats from read.current-seat); then the higher VP. For the chosen threat, answer cost = actions needed this turn + expected hits taken (Root's dice: two 0-3 dice, the attacker deals the higher and the defender the lower, each capped by its warriors; +1 hit to a defender with no warriors). Take the cheapest legal answer, breaking a met part before blocking the missing unit; ties: the answer nearest this bot's pieces, then the lower clearing number.", new[] { "read.seats", "read.current-seat", "read.seat-engine", "read.vp", "read.active-dominance", "read.coalition-partner", "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.tokens", "read.tokens-of-type", "read.pawn-clearing", "read.items", "read.relationship", "read.path-neighbours", "read.suits-of", "read.clearings", "read.recovered-relics", "read.relic-type", "read.relic-clearing", "read.relic-forest", "read.forest-clearings", "read.corvid-face-up-plot", "read.legal-actions", "read.alliance-supporters", "read.alliance-officers", "read.is-bot" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.global.difficulty", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.monoco.feet", "state.lune.tagged-relic", "state.curator.cell-crack" }, new[] { "ScielBot_SpoilerRevoltsInKeyLanternClearing", "ScielBot_SpoilerEasyAnswersBannersOnlyWithFreeActions" }),
            ["bot.verso.01-climb"] = new BotRuleDef("bot.verso.01-climb", "bot.verso", 1, "Climb", "Below rank A, start a battle only when the hits he expects to take are under tune.verso-bot-max-expected-hits (0.5): a lone defending warrior, or undefended buildings and tokens. A defender holding tune.verso-bot-ambush-hand (3) or more cards is a possible Ambush, and then he needs tune.verso-bot-ambush-swords (2) or more undamaged swords. He prefers Hostile factions (Infamy VP) and the VP leader, and fills the rest of the turn with quests and ruins (Root's Vagabond AI). Easy ignores Ambush risk.", "expected hits taken = E[min(lower of two 0-3 dice, defending warriors)], 0 with no defending warriors; a lone defending warrior is allowed by name. Order: Hostile factions, then the VP leader, then the rest; then fewest expected hits; ties: lower clearing number.", new[] { "read.warriors", "read.buildings", "read.tokens", "read.pawn-clearing", "read.items", "read.hand-size", "read.relationship", "read.vp", "read.seats", "read.legal-actions" }, new[] { "state.verso.rank", "state.global.difficulty" }, new[] { "VersoBot_ClimbsOnlyWithSafeBattlesBelowRankA", "VersoBot_TreatsThreeCardDefenderAsAmbush", "VersoBot_EasyIgnoresAmbushRisk" }),
            ["bot.verso.02-repair"] = new BotRuleDef("bot.verso.02-repair", "bot.verso", 2, "Repair", "After any damage, use Get Back Up (Hideout) or end the turn in a forest (the Evening rest) before the next fight.", "none (a plain condition: while any item is damaged he starts no battle)", new[] { "read.items", "read.pawn-forest", "read.forests-around", "read.legal-actions" }, Array.Empty<string>(), new[] { "VersoBot_RepairsBeforeNextFightAfterDamage" }),
            ["bot.verso.03-approach"] = new BotRuleDef("bot.verso.03-approach", "bot.verso", 3, "Approach", "At rank A or above in Act II or later, move next to the Monolith and keep farming lone warriors nearby (with step 1's filter) until step 4 says the assault is on.", "Path distance to the nearest clearing next to the Monolith; farming targets within one move of the Monolith first.", new[] { "read.pawn-clearing", "read.path-neighbours", "read.warriors", "read.legal-actions" }, new[] { "state.verso.rank", "state.global.act", "state.global.roles" }, new[] { "VersoBot_ApproachesMonolithAtRankAInActTwo" }),
            ["bot.verso.04-assault"] = new BotRuleDef("bot.verso.04-assault", "bot.verso", 4, "Assault", "Enter the Monolith at rank A or S only when its defenders can be cleared this turn (undamaged swords + the Perfection hit + the defenseless extra hit against buildings) with expected damage under tune.verso-bot-assault-max-damage (1). Clear the warriors, then the buildings, and end the turn there only at rank S with no other faction's pieces left. Easy waits for tune.verso-easy-assault-swords (4) undamaged swords.", "Pieces to clear = other seats' warriors + buildings + tokens in the Monolith. Expected removals this turn = over the battles he can start (one per ready sword), E[min(higher of two 0-3 dice, undamaged swords)] + tune.verso-perfection-hits, +1 once no defending warriors remain. Expected damage = the sum of E[min(lower die, defending warriors)] + 2 for a battle against a possible Ambush. Go when expected removals >= pieces to clear and expected damage < tune.verso-bot-assault-max-damage.", new[] { "read.pawn-clearing", "read.items", "read.warriors", "read.buildings", "read.tokens", "read.hand-size", "read.seats", "read.legal-actions" }, new[] { "state.verso.rank", "state.global.roles", "state.global.act", "state.global.difficulty" }, new[] { "VersoBot_AssaultsOnlyWhenMonolithClearableThisTurn", "VersoBot_EndsTurnInMonolithOnlyAtRankSWhenEmpty", "VersoBot_EasyWaitsForFourUndamagedSwords" }),
            ["bot.verso.05-bail"] = new BotRuleDef("bot.verso.05-bail", "bot.verso", 5, "Bail", "If his rank drops below A during an assault, leave the Monolith for a forest and rebuild (step 2, then step 1).", "The forest touching his clearing reachable with the fewest moves; ties: lower forest number.", new[] { "read.pawn-clearing", "read.forests-around", "read.items", "read.legal-actions" }, new[] { "state.verso.rank", "state.global.roles" }, new[] { "VersoBot_BailsToForestWhenRankDropsBelowA" }),
            ["bot.verso.06-reunion"] = new BotRuleDef("bot.verso.06-reunion", "bot.verso", 6, "Reunion", "In Act II or later, while Soarrie is on his card (withVerso), he walks into Esquie's clearing when he can reach it this turn, so Esquie can end his turn there (the reunion is worth tune.verso-soarrie-vp VP to Verso).", "none (a plain condition: Esquie seated, Soarrie withVerso, Esquie's pawn reachable with his ready boots this turn)", new[] { "read.pawn-clearing", "read.path-neighbours", "read.items", "read.seats", "read.legal-actions" }, new[] { "state.esquie.rocks", "state.global.act", "state.global.seat-characters" }, new[] { "VersoBot_WalksToEsquieWhenReachableInActTwo", "VersoBot_NoReunionWalkOnceSoarriePassed" }),
            ["bot.verso.07-spoiler"] = new BotRuleDef("bot.verso.07-spoiler", "bot.verso", 7, "Spoiler layer", "Shared spoiler layer (layer 3 of every bot; this part of the text is the same in all eleven plans). TRIGGER: another seat, the human included, that is not this bot's coalition partner, whose themed win is unlocked in the current act (Act II on; the Curator's from Act III) and not switched off (not switched off by that win's offWithDominance / offInCoalition), and that either has its countdown banner up (state.global.countdowns) or is one step from its win. One step means the public Goal Tracker shows every part of that win's test met except exactly one unit: one Arm pip, Chain suit, rock, Portrait suit, Sanctuary or Sanctuary suit, rank step, Allied faction, undamaged item, relic type, foot or source faction, covered clearing or Ring clearing, or one yes/no part (the Beachhead, the Monolith, Lumière, the Flying Manor atelier, an Aquafarm, the Parents' Journal recovered, the Warlord on the map, the tune.countdown-vp gate). ANSWER: attack or block the key clearing with a real Root action from that win's counterplay. Gustave: flip rule of the Chain clearing with the thinnest margin, or remove the Beachhead's buildings. Esquie (3 rocks held): the Nevron host moves extra warriors onto the last guarded rock (more defenders deal more hits to him) and every other bot attacks his pawn to damage items. The Paintress: break an easel, flip rule of a Portrait clearing or thin it below tune.paintress-portrait-warriors warriors, or take the Monolith. Sciel: before her banner, step a piece into a Sanctuary (paying Outrage); once it is up, battle a Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm. Verso: before his banner, put a warrior, building or pawn in the Monolith (tokens do not block him); once it is up, battle him there and land a hit. Maelle: attack her in Lumière and damage items until fewer than tune.maelle-items are undamaged. Lune: battle the warriors carrying the Parents' Journal or her missing relic type, and hold the clearings around the gold forest. Monoco: battle the Warlord off the map (Sacred River Rebirth strips Almighty and his latest other foot). The Curator: flip rule of Lumière or remove his Monolith tunnel; with no keep in Lumière, raze his building there and cut his warriors below tune.curator-lumiere-warriors; keep the Paintress's roost in the Monolith alive. Clea: remove her warriors from one counted clearing (lone Nevrons first) or from the Monolith, or raze the Flying Manor atelier. The White-Haired Man: out-stack him in one Ring clearing, guess a plot with Exposure, or walk a Vagabond pawn into the Monolith. LIMITS: it obeys every rule tweak and every 'never' and 'only' in the steps above it, uses only public information plus this bot's own hand and hidden pieces, and barks the block. PRIORITY: with no trigger it does nothing. It is listed last, as in the roster, but takes the actions it needs ahead of the steps above (it pre-empts them) in two cases: a banner that is up, because that seat confirms before this bot's next Birdsong, unless this bot can finish a quest win this turn; and, on Hard only, a one-step threat, unless this is this bot's own announce turn (its own confirmation would land first). Otherwise it answers with the actions the steps above leave free. Easy answers banners only, and only with free actions. FOR VERSO: his fights keep step 1's filter below rank A and step 4's test in the Monolith; where no fight passes, he answers by moving his pawn (into the Monolith against the White-Haired Man, or into a would-be Sanctuary before Sciel's banner).", "Threats: banners before one-step threats; then the seat whose next Birdsong comes first in turn order (read.seats from read.current-seat); then the higher VP. For the chosen threat, answer cost = actions needed this turn + expected hits taken (Root's dice: two 0-3 dice, the attacker deals the higher and the defender the lower, each capped by its warriors; +1 hit to a defender with no warriors). Take the cheapest legal answer, breaking a met part before blocking the missing unit; ties: the answer nearest this bot's pieces, then the lower clearing number.", new[] { "read.seats", "read.current-seat", "read.seat-engine", "read.vp", "read.active-dominance", "read.coalition-partner", "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.tokens", "read.tokens-of-type", "read.pawn-clearing", "read.items", "read.relationship", "read.path-neighbours", "read.suits-of", "read.clearings", "read.recovered-relics", "read.relic-type", "read.relic-clearing", "read.relic-forest", "read.forest-clearings", "read.corvid-face-up-plot", "read.legal-actions", "read.hand-size", "read.is-bot" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.global.difficulty", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.monoco.feet", "state.lune.tagged-relic", "state.curator.cell-crack" }, new[] { "VersoBot_SpoilerKeepsClimbFilterBelowRankA", "VersoBot_SpoilerNeverBlocksCoalitionPartner" }),
            ["bot.maelle.01-family"] = new BotRuleDef("bot.maelle.01-family", "bot.maelle", 1, "Family", "Pick her family: the two non-Hostile, non-Vagabond factions closest to Allied, avoiding the VP leader when there is another option, and save them in state.maelle.family. She re-picks only if a family member passes tune.maelle-family-repick-vp (22) VP.", "Relationship steps: Allied 3, Friendly 2, Amiable 1, Indifferent 0; highest first; ties: lower VP; the VP leader goes last whenever another candidate exists.", new[] { "read.relationship", "read.vp", "read.seats", "read.seat-engine" }, new[] { "state.maelle.family" }, new[] { "MaelleBot_PicksTwoNonHostileClosestToAllied", "MaelleBot_AvoidsVpLeaderInFamily", "MaelleBot_RepicksOnlyPastTwentyTwoVp" }),
            ["bot.maelle.02-aid"] = new BotRuleDef("bot.maelle.02-aid", "bot.maelle", 2, "Aid", "Each Daylight, move to a clearing where a family faction has pieces and whose suit matches a card in her hand, Aid that faction, and take its crafted items when offered (swords and boots first). Easy Aids once per turn.", "Family member with fewer relationship steps first (it needs more Aid), then fewest moves; items taken: swords, then boots, then any other.", new[] { "read.pawn-clearing", "read.path-neighbours", "read.warriors", "read.buildings", "read.tokens", "read.suits-of", "read.hand-suits", "read.crafted-items", "read.relationship", "read.items", "read.legal-actions" }, new[] { "state.maelle.family", "state.global.difficulty" }, new[] { "MaelleBot_AidsFamilyInMatchingSuitClearing", "MaelleBot_TakesSwordsAndBootsFirst", "MaelleBot_EasyAidsOncePerTurn" }),
            ["bot.maelle.03-no-fights"] = new BotRuleDef("bot.maelle.03-no-fights", "bot.maelle", 3, "No fights", "No fights with non-Hostile factions unless one is within tune.maelle-threat-vp (5) VP of Root's 30 VP win. She Disarms (Steals from) the VP leader to refill her hand and uses quests and ruins for VP.", "Disarm target: the VP leader in her clearing or one move away; ties: more cards in hand.", new[] { "read.relationship", "read.vp", "read.pawn-clearing", "read.hand-size", "read.has-ruin", "read.seats", "read.legal-actions" }, new[] { "state.maelle.family" }, new[] { "MaelleBot_NoFightsWithNonHostileUnlessNearWin", "MaelleBot_DisarmsVpLeaderToRefillHand" }),
            ["bot.maelle.04-goal-mode"] = new BotRuleDef("bot.maelle.04-goal-mode", "bot.maelle", 4, "Goal mode", "In goal mode, once the relationship conditions hold: path to Lumière, repair in a forest the turn before arriving, arrive with tune.maelle-items (3) or more undamaged items, and stay. Easy does not repair before arriving.", "Shortest path to Lumière; if any item is damaged, the turn before the last move ends in a forest on or beside that path.", new[] { "read.pawn-clearing", "read.pawn-forest", "read.path-neighbours", "read.forests-around", "read.items", "read.relationship", "read.seats", "read.seat-engine", "read.legal-actions" }, new[] { "state.global.roles", "state.global.difficulty" }, new[] { "MaelleBot_GoalModeHeadsToLumiereAndStays", "MaelleBot_RepairsInForestTurnBeforeArriving", "MaelleBot_EasySkipsRepairBeforeArriving" }),
            ["bot.maelle.05-two-player"] = new BotRuleDef("bot.maelle.05-two-player", "bot.maelle", 5, "One-faction table", "With only one non-Vagabond faction seated (a 2-player game, or two Vagabonds at three seats): one family faction, then push to tune.maelle-2p-vp (15) VP.", "none (a plain condition)", new[] { "read.seats", "read.seat-engine", "read.vp" }, new[] { "state.maelle.family" }, new[] { "MaelleBot_OneFactionTablePicksOneFamilyAndPushesToFifteenVp" }),
            ["bot.maelle.06-spoiler"] = new BotRuleDef("bot.maelle.06-spoiler", "bot.maelle", 6, "Spoiler layer", "Shared spoiler layer (layer 3 of every bot; this part of the text is the same in all eleven plans). TRIGGER: another seat, the human included, that is not this bot's coalition partner, whose themed win is unlocked in the current act (Act II on; the Curator's from Act III) and not switched off (not switched off by that win's offWithDominance / offInCoalition), and that either has its countdown banner up (state.global.countdowns) or is one step from its win. One step means the public Goal Tracker shows every part of that win's test met except exactly one unit: one Arm pip, Chain suit, rock, Portrait suit, Sanctuary or Sanctuary suit, rank step, Allied faction, undamaged item, relic type, foot or source faction, covered clearing or Ring clearing, or one yes/no part (the Beachhead, the Monolith, Lumière, the Flying Manor atelier, an Aquafarm, the Parents' Journal recovered, the Warlord on the map, the tune.countdown-vp gate). ANSWER: attack or block the key clearing with a real Root action from that win's counterplay. Gustave: flip rule of the Chain clearing with the thinnest margin, or remove the Beachhead's buildings. Esquie (3 rocks held): the Nevron host moves extra warriors onto the last guarded rock (more defenders deal more hits to him) and every other bot attacks his pawn to damage items. The Paintress: break an easel, flip rule of a Portrait clearing or thin it below tune.paintress-portrait-warriors warriors, or take the Monolith. Sciel: before her banner, step a piece into a Sanctuary (paying Outrage); once it is up, battle a Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm. Verso: before his banner, put a warrior, building or pawn in the Monolith (tokens do not block him); once it is up, battle him there and land a hit. Maelle: attack her in Lumière and damage items until fewer than tune.maelle-items are undamaged. Lune: battle the warriors carrying the Parents' Journal or her missing relic type, and hold the clearings around the gold forest. Monoco: battle the Warlord off the map (Sacred River Rebirth strips Almighty and his latest other foot). The Curator: flip rule of Lumière or remove his Monolith tunnel; with no keep in Lumière, raze his building there and cut his warriors below tune.curator-lumiere-warriors; keep the Paintress's roost in the Monolith alive. Clea: remove her warriors from one counted clearing (lone Nevrons first) or from the Monolith, or raze the Flying Manor atelier. The White-Haired Man: out-stack him in one Ring clearing, guess a plot with Exposure, or walk a Vagabond pawn into the Monolith. LIMITS: it obeys every rule tweak and every 'never' and 'only' in the steps above it, uses only public information plus this bot's own hand and hidden pieces, and barks the block. PRIORITY: with no trigger it does nothing. It is listed last, as in the roster, but takes the actions it needs ahead of the steps above (it pre-empts them) in two cases: a banner that is up, because that seat confirms before this bot's next Birdsong, unless this bot can finish a quest win this turn; and, on Hard only, a one-step threat, unless this is this bot's own announce turn (its own confirmation would land first). Otherwise it answers with the actions the steps above leave free. Easy answers banners only, and only with free actions. FOR MAELLE: step 3 binds the spoiler: she battles a non-Hostile faction only when it is within tune.maelle-threat-vp VP of Root's 30 VP win. Otherwise she answers by moving her pawn (into the Monolith against the White-Haired Man or before Verso's banner, into a would-be Sanctuary before Sciel's banner), by battling Hostile factions, and by Disarming the threat's seat.", "Threats: banners before one-step threats; then the seat whose next Birdsong comes first in turn order (read.seats from read.current-seat); then the higher VP. For the chosen threat, answer cost = actions needed this turn + expected hits taken (Root's dice: two 0-3 dice, the attacker deals the higher and the defender the lower, each capped by its warriors; +1 hit to a defender with no warriors). Take the cheapest legal answer, breaking a met part before blocking the missing unit; ties: the answer nearest this bot's pieces, then the lower clearing number.", new[] { "read.seats", "read.current-seat", "read.seat-engine", "read.vp", "read.active-dominance", "read.coalition-partner", "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.tokens", "read.tokens-of-type", "read.pawn-clearing", "read.items", "read.relationship", "read.path-neighbours", "read.suits-of", "read.clearings", "read.recovered-relics", "read.relic-type", "read.relic-clearing", "read.relic-forest", "read.forest-clearings", "read.corvid-face-up-plot", "read.legal-actions", "read.hand-size", "read.is-bot" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.global.difficulty", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.monoco.feet", "state.lune.tagged-relic", "state.curator.cell-crack", "state.maelle.family" }, new[] { "MaelleBot_SpoilerFightsNonHostileOnlyNearWin", "MaelleBot_SpoilerWalksIntoMonolithAgainstWhiteHairedMan" }),
            ["bot.lune.01-act1"] = new BotRuleDef("bot.lune.01-act1", "bot.lune", 1, "Act I relics", "In Act I, normal Keepers play, but delve and recover relic types missing from her recovered relics first.", "Relics in forests whose type she has not recovered, nearest first (path distance from her nearest warriors to a clearing touching the relic's forest); ties: higher value among face-up relics only (RelicFaceUp(r) == true; face-down relics count as unknown and rank below known values), then lower relic id.", new[] { "read.recovered-relics", "read.relic-type", "read.relic-value", "read.relic-face-up", "read.relics-in-forest", "read.relic-forest", "read.forest-clearings", "read.warriors", "read.path-neighbours", "read.legal-actions" }, new[] { "state.global.act" }, new[] { "LuneBot_ActOneDelvesMissingRelicTypesFirst" }),
            ["bot.lune.02-act2-goals"] = new BotRuleDef("bot.lune.02-act2-goals", "bot.lune", 2, "Act II goals", "From Act II her goals are the Parents' Journal (the tagged relic, in the gold forest beside Sirène) and any missing relic type; she works on whichever is closer.", "distance = path steps from her nearest warrior group to a clearing touching the relic's forest, or to the relic's clearing while it is carried; the closer goal first; ties: the Journal.", new[] { "read.relic-forest", "read.relic-clearing", "read.relic-type", "read.relics-in-forest", "read.forest-clearings", "read.forests-around", "read.recovered-relics", "read.warriors", "read.path-neighbours" }, new[] { "state.lune.tagged-relic", "state.global.act", "state.global.roles" }, new[] { "LuneBot_ActTwoChasesJournalOrMissingTypeWhicheverCloser" }),
            ["bot.lune.03-retinue"] = new BotRuleDef("bot.lune.03-retinue", "bot.lune", 3, "Retinue", "Add Move and Delve cards to the Retinue whose suits match the clearings on the way to the target forest, and never add a card she cannot resolve.", "Cards in hand whose suit matches the next clearings on the shortest path to the target, in path order; a card is dropped if the one-turn lookahead finds it unresolvable.", new[] { "read.keepers-retinue", "read.hand-suits", "read.suits-of", "read.path-neighbours", "read.forest-clearings", "read.legal-actions" }, new[] { "state.lune.tagged-relic" }, new[] { "LuneBot_RetinueAddsCardsMatchingRouteSuits", "LuneBot_NeverAddsUnresolvableRetinueCard" }),
            ["bot.lune.04-delve"] = new BotRuleDef("bot.lune.04-delve", "bot.lune", 4, "Delve the Journal", "Delve the Journal's forest only with tune.lune-delve-escort (3) or more of her warriors in clearings touching that forest.", "none (a plain condition)", new[] { "read.warriors", "read.forest-clearings", "read.relic-forest", "read.legal-actions" }, new[] { "state.lune.tagged-relic" }, new[] { "LuneBot_DelvesJournalOnlyWithThreeWarriorsAdjacent" }),
            ["bot.lune.05-escort"] = new BotRuleDef("bot.lune.05-escort", "bot.lune", 5, "Escort", "Escort carriers in groups of tune.lune-convoy-size (2) or more (Devout Knights ignore the first hit), avoid clearings where enemies outnumber the escort, and route to a waystation of the carried relic's type; for the Journal, a tablet waystation, building or flipping a Research Camp to the tablet side on the shortest way home. Easy sends single-warrior carriers; Hard runs two convoys at once.", "Route = the shortest path to a waystation showing the relic's type that passes no clearing where one enemy seat's warriors outnumber the convoy; if there is none, the shortest such path to a clearing where she can build or flip a waystation to that type.", new[] { "read.relic-clearing", "read.relic-type", "read.warriors", "read.buildings-of-type", "read.path-neighbours", "read.free-slots", "read.seats", "read.legal-actions" }, new[] { "state.lune.tagged-relic", "state.global.difficulty" }, new[] { "LuneBot_EscortsCarriersInGroupsOfTwo", "LuneBot_AvoidsClearingsWhereEnemiesOutnumberEscort", "LuneBot_HardRunsTwoConvoys" }),
            ["bot.lune.06-duplicates"] = new BotRuleDef("bot.lune.06-duplicates", "bot.lune", 6, "Skip duplicates", "Ignore relics of a type she has already recovered unless she needs VP: they are skipped while the Journal or a missing type can still be reached.", "none (a plain condition)", new[] { "read.recovered-relics", "read.relic-type", "read.relics-in-forest" }, new[] { "state.lune.tagged-relic" }, new[] { "LuneBot_SkipsDuplicateTypesWhileGoalRelicsRemain" }),
            ["bot.lune.07-spoiler"] = new BotRuleDef("bot.lune.07-spoiler", "bot.lune", 7, "Spoiler layer", "Shared spoiler layer (layer 3 of every bot; this part of the text is the same in all eleven plans). TRIGGER: another seat, the human included, that is not this bot's coalition partner, whose themed win is unlocked in the current act (Act II on; the Curator's from Act III) and not switched off (not switched off by that win's offWithDominance / offInCoalition), and that either has its countdown banner up (state.global.countdowns) or is one step from its win. One step means the public Goal Tracker shows every part of that win's test met except exactly one unit: one Arm pip, Chain suit, rock, Portrait suit, Sanctuary or Sanctuary suit, rank step, Allied faction, undamaged item, relic type, foot or source faction, covered clearing or Ring clearing, or one yes/no part (the Beachhead, the Monolith, Lumière, the Flying Manor atelier, an Aquafarm, the Parents' Journal recovered, the Warlord on the map, the tune.countdown-vp gate). ANSWER: attack or block the key clearing with a real Root action from that win's counterplay. Gustave: flip rule of the Chain clearing with the thinnest margin, or remove the Beachhead's buildings. Esquie (3 rocks held): the Nevron host moves extra warriors onto the last guarded rock (more defenders deal more hits to him) and every other bot attacks his pawn to damage items. The Paintress: break an easel, flip rule of a Portrait clearing or thin it below tune.paintress-portrait-warriors warriors, or take the Monolith. Sciel: before her banner, step a piece into a Sanctuary (paying Outrage); once it is up, battle a Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm. Verso: before his banner, put a warrior, building or pawn in the Monolith (tokens do not block him); once it is up, battle him there and land a hit. Maelle: attack her in Lumière and damage items until fewer than tune.maelle-items are undamaged. Lune: battle the warriors carrying the Parents' Journal or her missing relic type, and hold the clearings around the gold forest. Monoco: battle the Warlord off the map (Sacred River Rebirth strips Almighty and his latest other foot). The Curator: flip rule of Lumière or remove his Monolith tunnel; with no keep in Lumière, raze his building there and cut his warriors below tune.curator-lumiere-warriors; keep the Paintress's roost in the Monolith alive. Clea: remove her warriors from one counted clearing (lone Nevrons first) or from the Monolith, or raze the Flying Manor atelier. The White-Haired Man: out-stack him in one Ring clearing, guess a plot with Exposure, or walk a Vagabond pawn into the Monolith. LIMITS: it obeys every rule tweak and every 'never' and 'only' in the steps above it, uses only public information plus this bot's own hand and hidden pieces, and barks the block. PRIORITY: with no trigger it does nothing. It is listed last, as in the roster, but takes the actions it needs ahead of the steps above (it pre-empts them) in two cases: a banner that is up, because that seat confirms before this bot's next Birdsong, unless this bot can finish a quest win this turn; and, on Hard only, a one-step threat, unless this is this bot's own announce turn (its own confirmation would land first). Otherwise it answers with the actions the steps above leave free. Easy answers banners only, and only with free actions. FOR LUNE: her answers are Battle and Move cards added to the Retinue for the key clearing, added only when the lookahead says she can resolve them (step 3), and convoys keep their escort size (step 5). A quest win she can finish this turn always comes first.", "Threats: banners before one-step threats; then the seat whose next Birdsong comes first in turn order (read.seats from read.current-seat); then the higher VP. For the chosen threat, answer cost = actions needed this turn + expected hits taken (Root's dice: two 0-3 dice, the attacker deals the higher and the defender the lower, each capped by its warriors; +1 hit to a defender with no warriors). Take the cheapest legal answer, breaking a met part before blocking the missing unit; ties: the answer nearest this bot's pieces, then the lower clearing number.", new[] { "read.seats", "read.current-seat", "read.seat-engine", "read.vp", "read.active-dominance", "read.coalition-partner", "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.tokens", "read.tokens-of-type", "read.pawn-clearing", "read.items", "read.relationship", "read.path-neighbours", "read.suits-of", "read.clearings", "read.recovered-relics", "read.relic-type", "read.relic-clearing", "read.relic-forest", "read.forest-clearings", "read.corvid-face-up-plot", "read.legal-actions", "read.keepers-retinue", "read.hand-suits", "read.is-bot" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.global.difficulty", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.monoco.feet", "state.lune.tagged-relic", "state.curator.cell-crack" }, new[] { "LuneBot_SpoilerNormalAnswersOneStepWithFreeActions", "LuneBot_SpoilerIgnoresWinsLockedInCurrentAct" }),
            ["bot.monoco.01-battle-score"] = new BotRuleDef("bot.monoco.01-battle-score", "bot.monoco", 1, "Score Warlord battles", "Each Daylight, list the Warlord battles he can reach (Advance by Prowess, Command moves to bring rats along) and score each; the best becomes the planned battle.", "score = tune.monoco-bot-missing-foot (+10) if it fills a missing foot + tune.monoco-bot-new-faction (+4) if it adds a new source faction toward the tune.monoco-feet-factions rule (3 factions) + his win chance (the chance his stack's hits remove every defending warrior, 0 to 1). The heavy penalty: a battle whose defenders could deal hits equal to his stack (their warriors there, capped at 3, >= his warriors there including the Warlord) ranks below every battle without that risk. Ties: lower clearing number.", new[] { "read.pawn-clearing", "read.warriors", "read.buildings", "read.tokens", "read.path-neighbours", "read.hundreds-mood", "read.vp", "read.seats", "read.legal-actions", "read.hundreds-hoard" }, new[] { "state.monoco.feet", "state.global.act" }, new[] { "MonocoBot_BattleScoreMatchesFormula", "MonocoBot_HeavyPenaltyForBattleThatCouldWipeHisStack" }),
            ["bot.monoco.02-targets"] = new BotRuleDef("bot.monoco.02-targets", "bot.monoco", 2, "Targets", "Targets by the foot they fill: Heavy or Caster, an enemy building or token guarded by tune.monoco-bot-target-guards (1) or fewer warriors; Agile, a lone enemy warrior one Advance away; Balanced, an even fight he still wins; Almighty (from Act tune.monoco-almighty-act), the VP leader's least-guarded building, or a leader stack of tune.monoco-almighty-pieces (3) or more pieces he can wipe out. Easy advances only when the Warlord outnumbers the defenders by tune.monoco-easy-outnumber (2).", "Missing feet first (step 1's score), then within a foot the fewest defending warriors; Balanced: a fight where the defenders can deal at least one hit (so he loses a piece) and his win chance is the best among such fights; ties: lower clearing number.", new[] { "read.warriors", "read.buildings", "read.tokens", "read.pawn-clearing", "read.path-neighbours", "read.vp", "read.seats", "read.legal-actions" }, new[] { "state.monoco.feet", "state.global.act", "state.global.difficulty" }, new[] { "MonocoBot_TargetsMatchMissingFoot", "MonocoBot_AlmightyTargetsLeaderLeastGuardedBuilding", "MonocoBot_EasyAdvancesOnlyOutnumberingByTwo" }),
            ["bot.monoco.03-bring-rats"] = new BotRuleDef("bot.monoco.03-bring-rats", "bot.monoco", 3, "Bring the rats", "The turn before the planned battle, Command-move rats into or next to the target. Easy skips this step: the Warlord advances alone.", "Rats from the nearest clearings first (fewest moves); ties: lower clearing number.", new[] { "read.warriors", "read.path-neighbours", "read.pawn-clearing", "read.legal-actions", "read.hundreds-hoard" }, new[] { "state.monoco.feet", "state.global.difficulty" }, new[] { "MonocoBot_CommandsRatsToTargetTurnBefore", "MonocoBot_EasyWarlordAdvancesAlone" }),
            ["bot.monoco.04-mood"] = new BotRuleDef("bot.monoco.04-mood", "bot.monoco", 4, "Mood", "Pick the mood (mask) that boosts the planned battle.", "The mood whose effect adds most to the planned battle's step 1 score; ties: keep the current mood. Mood effects are Root's own, unchanged by the reskin, and read from the card id.", new[] { "read.hundreds-mood", "read.legal-actions" }, Array.Empty<string>(), new[] { "MonocoBot_PicksMoodThatBoostsPlannedBattle" }),
            ["bot.monoco.05-arenas"] = new BotRuleDef("bot.monoco.05-arenas", "bot.monoco", 5, "Arenas", "Build Arenas (strongholds) along the route to his targets so Oppress keeps scoring.", "Clearings on the Warlord's planned path that he rules and that have a free slot, nearest first; ties: lower clearing number.", new[] { "read.ruler", "read.free-slots", "read.buildings-of-type", "read.path-neighbours", "read.pawn-clearing", "read.legal-actions" }, Array.Empty<string>(), new[] { "MonocoBot_BuildsArenasAlongRoute" }),
            ["bot.monoco.06-escort"] = new BotRuleDef("bot.monoco.06-escort", "bot.monoco", 6, "Escort the Warlord", "After tune.monoco-bot-escort-after-feet (3) feet, keep tune.monoco-bot-escort (2) or more Gestrals in the Warlord's clearing.", "none (a plain condition)", new[] { "read.pawn-clearing", "read.warriors", "read.legal-actions" }, new[] { "state.monoco.feet" }, new[] { "MonocoBot_EscortsWarlordWithTwoAfterThreeFeet" }),
            ["bot.monoco.07-announce"] = new BotRuleDef("bot.monoco.07-announce", "bot.monoco", 7, "Announce turn", "On the announce turn (win.monoco's announce test will pass at the end of this turn), end with the Warlord in his strongest enemy-free clearing.", "Clearings with no enemy pieces, by his warriors + buildings there, most first; ties: fewest enemy warriors next to it, then lower clearing number.", new[] { "read.warriors", "read.buildings", "read.tokens", "read.pawn-clearing", "read.path-neighbours", "read.seats", "read.legal-actions" }, new[] { "state.monoco.feet", "state.global.act" }, new[] { "MonocoBot_AnnounceTurnEndsInStrongestEnemyFreeClearing" }),
            ["bot.monoco.08-spoiler"] = new BotRuleDef("bot.monoco.08-spoiler", "bot.monoco", 8, "Spoiler layer", "Shared spoiler layer (layer 3 of every bot; this part of the text is the same in all eleven plans). TRIGGER: another seat, the human included, that is not this bot's coalition partner, whose themed win is unlocked in the current act (Act II on; the Curator's from Act III) and not switched off (not switched off by that win's offWithDominance / offInCoalition), and that either has its countdown banner up (state.global.countdowns) or is one step from its win. One step means the public Goal Tracker shows every part of that win's test met except exactly one unit: one Arm pip, Chain suit, rock, Portrait suit, Sanctuary or Sanctuary suit, rank step, Allied faction, undamaged item, relic type, foot or source faction, covered clearing or Ring clearing, or one yes/no part (the Beachhead, the Monolith, Lumière, the Flying Manor atelier, an Aquafarm, the Parents' Journal recovered, the Warlord on the map, the tune.countdown-vp gate). ANSWER: attack or block the key clearing with a real Root action from that win's counterplay. Gustave: flip rule of the Chain clearing with the thinnest margin, or remove the Beachhead's buildings. Esquie (3 rocks held): the Nevron host moves extra warriors onto the last guarded rock (more defenders deal more hits to him) and every other bot attacks his pawn to damage items. The Paintress: break an easel, flip rule of a Portrait clearing or thin it below tune.paintress-portrait-warriors warriors, or take the Monolith. Sciel: before her banner, step a piece into a Sanctuary (paying Outrage); once it is up, battle a Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm. Verso: before his banner, put a warrior, building or pawn in the Monolith (tokens do not block him); once it is up, battle him there and land a hit. Maelle: attack her in Lumière and damage items until fewer than tune.maelle-items are undamaged. Lune: battle the warriors carrying the Parents' Journal or her missing relic type, and hold the clearings around the gold forest. Monoco: battle the Warlord off the map (Sacred River Rebirth strips Almighty and his latest other foot). The Curator: flip rule of Lumière or remove his Monolith tunnel; with no keep in Lumière, raze his building there and cut his warriors below tune.curator-lumiere-warriors; keep the Paintress's roost in the Monolith alive. Clea: remove her warriors from one counted clearing (lone Nevrons first) or from the Monolith, or raze the Flying Manor atelier. The White-Haired Man: out-stack him in one Ring clearing, guess a plot with Exposure, or walk a Vagabond pawn into the Monolith. LIMITS: it obeys every rule tweak and every 'never' and 'only' in the steps above it, uses only public information plus this bot's own hand and hidden pieces, and barks the block. PRIORITY: with no trigger it does nothing. It is listed last, as in the roster, but takes the actions it needs ahead of the steps above (it pre-empts them) in two cases: a banner that is up, because that seat confirms before this bot's next Birdsong, unless this bot can finish a quest win this turn; and, on Hard only, a one-step threat, unless this is this bot's own announce turn (its own confirmation would land first). Otherwise it answers with the actions the steps above leave free. Easy answers banners only, and only with free actions. FOR MONOCO: his answers are Warlord battles and Command moves; among answers of equal cost he takes the one step 1 scores higher, since it may also fill a foot.", "Threats: banners before one-step threats; then the seat whose next Birdsong comes first in turn order (read.seats from read.current-seat); then the higher VP. For the chosen threat, answer cost = actions needed this turn + expected hits taken (Root's dice: two 0-3 dice, the attacker deals the higher and the defender the lower, each capped by its warriors; +1 hit to a defender with no warriors). Take the cheapest legal answer, breaking a met part before blocking the missing unit; ties: the answer nearest this bot's pieces, then the lower clearing number.", new[] { "read.seats", "read.current-seat", "read.seat-engine", "read.vp", "read.active-dominance", "read.coalition-partner", "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.tokens", "read.tokens-of-type", "read.pawn-clearing", "read.items", "read.relationship", "read.path-neighbours", "read.suits-of", "read.clearings", "read.recovered-relics", "read.relic-type", "read.relic-clearing", "read.relic-forest", "read.forest-clearings", "read.corvid-face-up-plot", "read.legal-actions", "read.hundreds-mood", "read.is-bot" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.global.difficulty", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.monoco.feet", "state.lune.tagged-relic", "state.curator.cell-crack" }, new[] { "MonocoBot_SpoilerHardAnswersOneStepAheadOfGoalSteps", "MonocoBot_SpoilerBreaksMetPartBeforeBlockingMissingOne" }),
            ["bot.curator.01-helper"] = new BotRuleDef("bot.curator.01-helper", "bot.curator", 1, "The helper (Acts I-II)", "In Acts I-II the Cell Crack is inert. Build camps and stalls, sway ministers for VP, and stock the Burrow to tune.curator-burrow-stock (6) or more. Avoid big fights, and never attack the Paintress unless she is one step from her own win (as the spoiler layer defines it).", "Order: build a camp or stall in a ruled clearing with a free slot; sway the highest-VP minister he can afford; recruit to the Burrow while it holds fewer than tune.curator-burrow-stock. He starts no battle against 2 or more defending warriors (a big fight).", new[] { "read.duchy-burrow", "read.duchy-ministers", "read.buildings", "read.free-slots", "read.ruler", "read.warriors", "read.hand-suits", "read.seats", "read.legal-actions" }, new[] { "state.curator.cell-crack", "state.global.act", "state.global.seat-characters" }, new[] { "CuratorBot_StocksBurrowToSixInActsOneAndTwo", "CuratorBot_AvoidsBigFightsBeforeActThree", "CuratorBot_NeverAttacksPaintressUnlessOneStepFromWin" }),
            ["bot.curator.02-reveal"] = new BotRuleDef("bot.curator.02-reveal", "bot.curator", 2, "The reveal (Act III)", "In Act III, once the Cell Crack is a tunnel, if the Paintress's roost still stands in the Monolith, emerge there from the Burrow with defenders + tune.curator-assault-margin (2) warriors and take it down. Under the fallback ('dig-owed') his first Act III action is the free Dig into the Monolith.", "Warriors needed = the Paintress's warriors in the Monolith + tune.curator-assault-margin; he waits in the Burrow, recruiting, until it holds that many.", new[] { "read.duchy-burrow", "read.warriors", "read.buildings-of-type", "read.tokens-of-type", "read.seats", "read.legal-actions" }, new[] { "state.curator.cell-crack", "state.global.act", "state.global.roles", "state.global.seat-characters" }, new[] { "CuratorBot_EmergesInMonolithWithDefendersPlusTwo", "CuratorBot_WaitsInBurrowUntilDefendersPlusTwo" }),
            ["bot.curator.03-lumiere"] = new BotRuleDef("bot.curator.03-lumiere", "bot.curator", 3, "Lumière", "In Act III, dig next to Lumière (or into it if no keep stands there) and march or battle in with defenders + tune.curator-assault-margin (2). Sway Battle and Move ministers first. If no keep stands in Lumière, keep a card of Lumière's suit to build there, or hold tune.curator-lumiere-warriors (3) or more warriors there. Easy never re-digs a lost tunnel and attacks Lumière only with defenders + tune.curator-easy-assault-margin (3).", "Dig target: Lumière itself when no keep stands there, otherwise the clearing next to Lumière with the fewest enemy warriors (ties: lower clearing number). Warriors needed = Lumière's ruler's warriors + the margin. Ministers: those that grant Battle or Move first, then by VP.", new[] { "read.tokens-of-type", "read.warriors", "read.buildings", "read.ruler", "read.path-neighbours", "read.suits-of", "read.hand-suits", "read.duchy-ministers", "read.duchy-burrow", "read.supply-pieces", "read.legal-actions" }, new[] { "state.global.roles", "state.global.act", "state.global.difficulty", "state.curator.cell-crack" }, new[] { "CuratorBot_DigsNextToLumiereWhileKeepStands", "CuratorBot_EntersLumiereWithDefendersPlusTwo", "CuratorBot_EasyNeverRedigsAndNeedsDefendersPlusThree" }),
            ["bot.curator.04-announce"] = new BotRuleDef("bot.curator.04-announce", "bot.curator", 4, "Announce turn", "On the announce turn (win.curator's announce test will pass at the end of this turn), recruit into the Burrow and pour warriors into Lumière.", "Every warrior that can reach Lumière this turn (by the tunnel next to it or by march) goes in.", new[] { "read.duchy-burrow", "read.warriors", "read.tokens-of-type", "read.ruler", "read.path-neighbours", "read.legal-actions" }, new[] { "state.global.roles", "state.curator.cell-crack" }, new[] { "CuratorBot_AnnounceTurnPoursWarriorsIntoLumiere" }),
            ["bot.curator.05-spoiler"] = new BotRuleDef("bot.curator.05-spoiler", "bot.curator", 5, "Spoiler layer", "Shared spoiler layer (layer 3 of every bot; this part of the text is the same in all eleven plans). TRIGGER: another seat, the human included, that is not this bot's coalition partner, whose themed win is unlocked in the current act (Act II on; the Curator's from Act III) and not switched off (not switched off by that win's offWithDominance / offInCoalition), and that either has its countdown banner up (state.global.countdowns) or is one step from its win. One step means the public Goal Tracker shows every part of that win's test met except exactly one unit: one Arm pip, Chain suit, rock, Portrait suit, Sanctuary or Sanctuary suit, rank step, Allied faction, undamaged item, relic type, foot or source faction, covered clearing or Ring clearing, or one yes/no part (the Beachhead, the Monolith, Lumière, the Flying Manor atelier, an Aquafarm, the Parents' Journal recovered, the Warlord on the map, the tune.countdown-vp gate). ANSWER: attack or block the key clearing with a real Root action from that win's counterplay. Gustave: flip rule of the Chain clearing with the thinnest margin, or remove the Beachhead's buildings. Esquie (3 rocks held): the Nevron host moves extra warriors onto the last guarded rock (more defenders deal more hits to him) and every other bot attacks his pawn to damage items. The Paintress: break an easel, flip rule of a Portrait clearing or thin it below tune.paintress-portrait-warriors warriors, or take the Monolith. Sciel: before her banner, step a piece into a Sanctuary (paying Outrage); once it is up, battle a Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm. Verso: before his banner, put a warrior, building or pawn in the Monolith (tokens do not block him); once it is up, battle him there and land a hit. Maelle: attack her in Lumière and damage items until fewer than tune.maelle-items are undamaged. Lune: battle the warriors carrying the Parents' Journal or her missing relic type, and hold the clearings around the gold forest. Monoco: battle the Warlord off the map (Sacred River Rebirth strips Almighty and his latest other foot). The Curator: flip rule of Lumière or remove his Monolith tunnel; with no keep in Lumière, raze his building there and cut his warriors below tune.curator-lumiere-warriors; keep the Paintress's roost in the Monolith alive. Clea: remove her warriors from one counted clearing (lone Nevrons first) or from the Monolith, or raze the Flying Manor atelier. The White-Haired Man: out-stack him in one Ring clearing, guess a plot with Exposure, or walk a Vagabond pawn into the Monolith. LIMITS: it obeys every rule tweak and every 'never' and 'only' in the steps above it, uses only public information plus this bot's own hand and hidden pieces, and barks the block. PRIORITY: with no trigger it does nothing. It is listed last, as in the roster, but takes the actions it needs ahead of the steps above (it pre-empts them) in two cases: a banner that is up, because that seat confirms before this bot's next Birdsong, unless this bot can finish a quest win this turn; and, on Hard only, a one-step threat, unless this is this bot's own announce turn (its own confirmation would land first). Otherwise it answers with the actions the steps above leave free. Easy answers banners only, and only with free actions. FOR THE CURATOR: step 1's limits bind in Acts I-II (no big fights, and the Paintress only once she is one step from her win). His answers come through the Burrow (emerging by tunnel next to the key clearing) and his Battle and Move ministers.", "Threats: banners before one-step threats; then the seat whose next Birdsong comes first in turn order (read.seats from read.current-seat); then the higher VP. For the chosen threat, answer cost = actions needed this turn + expected hits taken (Root's dice: two 0-3 dice, the attacker deals the higher and the defender the lower, each capped by its warriors; +1 hit to a defender with no warriors). Take the cheapest legal answer, breaking a met part before blocking the missing unit; ties: the answer nearest this bot's pieces, then the lower clearing number.", new[] { "read.seats", "read.current-seat", "read.seat-engine", "read.vp", "read.active-dominance", "read.coalition-partner", "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.tokens", "read.tokens-of-type", "read.pawn-clearing", "read.items", "read.relationship", "read.path-neighbours", "read.suits-of", "read.clearings", "read.recovered-relics", "read.relic-type", "read.relic-clearing", "read.relic-forest", "read.forest-clearings", "read.corvid-face-up-plot", "read.legal-actions", "read.duchy-burrow", "read.duchy-ministers", "read.is-bot" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.global.difficulty", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.monoco.feet", "state.lune.tagged-relic", "state.curator.cell-crack" }, new[] { "CuratorBot_SpoilerKeepsHelperLimitsBeforeActThree", "CuratorBot_SpoilerOrdersBannersByNextBirdsong" }),
            ["bot.clea.01-recruit"] = new BotRuleDef("bot.clea.01-recruit", "bot.clea", 1, "Recruit", "Recruit ritual: reveal cards whose suits match uncovered clearings and place each new warrior in an uncovered clearing, where the ritual lets her choose (the exact Recruit wording is a week-1 spike item). Easy, half the time, places a warrior where she already has some.", "Suits by the number of uncovered clearings of that suit, most first; within a suit, the uncovered clearing with the fewest enemy warriors in and next to it; ties: lower clearing number. Easy's half-the-time choice comes from the bot's seeded random source.", new[] { "read.hand-suits", "read.suits-of", "read.warriors", "read.clearings", "read.path-neighbours", "read.seats", "read.legal-actions" }, new[] { "state.esquie.rocks", "state.global.difficulty" }, new[] { "CleaBot_RecruitPlacesInUncoveredClearings", "CleaBot_EasyHalfTheTimeStacksACoveredClearing" }),
            ["bot.clea.02-convert"] = new BotRuleDef("bot.clea.02-convert", "bot.clea", 2, "Convert and Sanctify", "Convert in Outcast-suit clearings where she has no warrior yet, since each converted warrior is new coverage. Sanctify the VP leader's buildings when affordable. Easy never Sanctifies.", "Convert targets: Outcast-suit clearings holding an enemy warrior and none of hers; ties: lower clearing number. Sanctify: the VP leader's buildings, with the acolytes left after Converts.", new[] { "read.lizard-outcast", "read.lizard-hated", "read.lizard-acolytes", "read.warriors", "read.buildings", "read.suits-of", "read.vp", "read.seats", "read.legal-actions" }, new[] { "state.esquie.rocks", "state.global.difficulty" }, new[] { "CleaBot_ConvertsInOutcastClearingsWithoutHerWarrior", "CleaBot_SanctifiesVpLeaderBuildings", "CleaBot_EasyNeverSanctifies" }),
            ["bot.clea.03-monolith"] = new BotRuleDef("bot.clea.03-monolith", "bot.clea", 3, "Monolith", "Keep a bird card to recruit into the Monolith whatever its suit. Use Crusade (2 acolytes) only when the Monolith or a clearing next to it is the Outcast suit.", "none (a plain condition)", new[] { "read.hand-suits", "read.lizard-outcast", "read.lizard-acolytes", "read.suits-of", "read.path-neighbours", "read.warriors", "read.legal-actions" }, new[] { "state.global.roles" }, new[] { "CleaBot_KeepsBirdCardForMonolith", "CleaBot_CrusadesOnlyWhenMonolithAreaIsOutcastSuit" }),
            ["bot.clea.04-home"] = new BotRuleDef("bot.clea.04-home", "bot.clea", 4, "Home", "Always keep 1 or more warriors and the atelier (garden) in the Flying Manor. Rebuilding the atelier comes first: while it is gone this step pre-empts the steps above.", "none (a plain condition)", new[] { "read.buildings-of-type", "read.warriors", "read.legal-actions" }, new[] { "state.global.roles", "state.esquie.rocks" }, new[] { "CleaBot_RebuildsFlyingManorAtelierFirst", "CleaBot_KeepsAWarriorInFlyingManor" }),
            ["bot.clea.05-hand"] = new BotRuleDef("bot.clea.05-hand", "bot.clea", 5, "Hand", "Keep Outcast-suit cards for conspiracies, and Sacrifice bird cards for acolytes only when she holds tune.clea-bot-sacrifice-birds (2) or more birds.", "Cards spent on rituals: non-Outcast suits first; birds above the one step 3 keeps are the only ones sacrificed.", new[] { "read.hand-suits", "read.lizard-outcast", "read.lizard-acolytes", "read.legal-actions" }, Array.Empty<string>(), new[] { "CleaBot_KeepsOutcastCardsForConspiracies", "CleaBot_SacrificesBirdsOnlyWithTwoOrMore" }),
            ["bot.clea.06-goal-mode"] = new BotRuleDef("bot.clea.06-goal-mode", "bot.clea", 6, "Goal mode", "In goal mode (tune.clea-goal-coverage or more covered clearings), re-cover any clearing that just lost its warrior (covered at the end of her last turn, uncovered now) before anything else: while such a clearing exists this step pre-empts the steps above.", "Lost clearings: the Monolith first (it is part of her win), then fewest enemy warriors; ties: lower clearing number.", new[] { "read.warriors", "read.clearings", "read.suits-of", "read.hand-suits", "read.legal-actions" }, new[] { "state.esquie.rocks", "state.global.roles", "state.clea.covered" }, new[] { "CleaBot_GoalModeRecoversLostClearingFirst" }),
            ["bot.clea.07-guards"] = new BotRuleDef("bot.clea.07-guards", "bot.clea", 7, "Guard stacks", "Guard stacks she hosts are never moved and never counted: her coverage and every step above subtract GuardsLeft of the guarded rocks she hosts in a clearing, and no action of hers takes those warriors below the guard floor.", "none (a plain condition)", new[] { "read.warriors" }, new[] { "state.esquie.rocks" }, new[] { "CleaBot_NeverCountsHostedGuardsAsCoverage", "CleaBot_NeverMovesGuardStacks" }),
            ["bot.clea.08-spoiler"] = new BotRuleDef("bot.clea.08-spoiler", "bot.clea", 8, "Spoiler layer", "Shared spoiler layer (layer 3 of every bot; this part of the text is the same in all eleven plans). TRIGGER: another seat, the human included, that is not this bot's coalition partner, whose themed win is unlocked in the current act (Act II on; the Curator's from Act III) and not switched off (not switched off by that win's offWithDominance / offInCoalition), and that either has its countdown banner up (state.global.countdowns) or is one step from its win. One step means the public Goal Tracker shows every part of that win's test met except exactly one unit: one Arm pip, Chain suit, rock, Portrait suit, Sanctuary or Sanctuary suit, rank step, Allied faction, undamaged item, relic type, foot or source faction, covered clearing or Ring clearing, or one yes/no part (the Beachhead, the Monolith, Lumière, the Flying Manor atelier, an Aquafarm, the Parents' Journal recovered, the Warlord on the map, the tune.countdown-vp gate). ANSWER: attack or block the key clearing with a real Root action from that win's counterplay. Gustave: flip rule of the Chain clearing with the thinnest margin, or remove the Beachhead's buildings. Esquie (3 rocks held): the Nevron host moves extra warriors onto the last guarded rock (more defenders deal more hits to him) and every other bot attacks his pawn to damage items. The Paintress: break an easel, flip rule of a Portrait clearing or thin it below tune.paintress-portrait-warriors warriors, or take the Monolith. Sciel: before her banner, step a piece into a Sanctuary (paying Outrage); once it is up, battle a Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm. Verso: before his banner, put a warrior, building or pawn in the Monolith (tokens do not block him); once it is up, battle him there and land a hit. Maelle: attack her in Lumière and damage items until fewer than tune.maelle-items are undamaged. Lune: battle the warriors carrying the Parents' Journal or her missing relic type, and hold the clearings around the gold forest. Monoco: battle the Warlord off the map (Sacred River Rebirth strips Almighty and his latest other foot). The Curator: flip rule of Lumière or remove his Monolith tunnel; with no keep in Lumière, raze his building there and cut his warriors below tune.curator-lumiere-warriors; keep the Paintress's roost in the Monolith alive. Clea: remove her warriors from one counted clearing (lone Nevrons first) or from the Monolith, or raze the Flying Manor atelier. The White-Haired Man: out-stack him in one Ring clearing, guess a plot with Exposure, or walk a Vagabond pawn into the Monolith. LIMITS: it obeys every rule tweak and every 'never' and 'only' in the steps above it, uses only public information plus this bot's own hand and hidden pieces, and barks the block. PRIORITY: with no trigger it does nothing. It is listed last, as in the roster, but takes the actions it needs ahead of the steps above (it pre-empts them) in two cases: a banner that is up, because that seat confirms before this bot's next Birdsong, unless this bot can finish a quest win this turn; and, on Hard only, a one-step threat, unless this is this bot's own announce turn (its own confirmation would land first). Otherwise it answers with the actions the steps above leave free. Easy answers banners only, and only with free actions. FOR CLEA: with no normal Move, her answers are Recruit placements into the key clearing (a warrior there breaks a Sanctuary before Sciel's banner, or out-stacks a Ring clearing), Convert and Sanctify in Outcast-suit key clearings, and Crusade within step 3's limit. Guard stacks are never moved for it (step 7), and she keeps a warrior and the atelier in the Flying Manor (step 4).", "Threats: banners before one-step threats; then the seat whose next Birdsong comes first in turn order (read.seats from read.current-seat); then the higher VP. For the chosen threat, answer cost = actions needed this turn + expected hits taken (Root's dice: two 0-3 dice, the attacker deals the higher and the defender the lower, each capped by its warriors; +1 hit to a defender with no warriors). Take the cheapest legal answer, breaking a met part before blocking the missing unit; ties: the answer nearest this bot's pieces, then the lower clearing number.", new[] { "read.seats", "read.current-seat", "read.seat-engine", "read.vp", "read.active-dominance", "read.coalition-partner", "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.tokens", "read.tokens-of-type", "read.pawn-clearing", "read.items", "read.relationship", "read.path-neighbours", "read.suits-of", "read.clearings", "read.recovered-relics", "read.relic-type", "read.relic-clearing", "read.relic-forest", "read.forest-clearings", "read.corvid-face-up-plot", "read.legal-actions", "read.lizard-outcast", "read.lizard-acolytes", "read.hand-suits", "read.is-bot" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.global.difficulty", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.monoco.feet", "state.lune.tagged-relic", "state.curator.cell-crack" }, new[] { "CleaBot_SpoilerNeverMovesGuardStacks", "CleaBot_SpoilerUsesOnlyPublicInformation" }),
            ["bot.white-haired-man.01-ring-status"] = new BotRuleDef("bot.white-haired-man.01-ring-status", "bot.white-haired-man", 1, "Ring status", "Each turn, work out his margin in each Ring clearing (the Monolith's path neighbours).", "margin(r) = his warriors in r (minus GuardsLeft of rocks he hosts there) - the rule count (warriors + buildings) of the strongest faction in r that is not the Paintress; a face-up Snare holds r whatever the margin.", new[] { "read.path-neighbours", "read.warriors", "read.buildings", "read.corvid-face-up-plot", "read.seats" }, new[] { "state.global.roles", "state.global.seat-characters", "state.esquie.rocks" }, new[] { "WhiteHairedManBot_RingMarginMatchesFormula", "WhiteHairedManBot_RingMarginIgnoresPaintress" }),
            ["bot.white-haired-man.02-recruit"] = new BotRuleDef("bot.white-haired-man.02-recruit", "bot.white-haired-man", 2, "Recruit", "Recruit with cards of Ring suits (Corvid Recruit places a warrior in every clearing of that suit).", "The suit whose Ring clearings have the lowest total margin first; ties: more Ring clearings of that suit, then fox, rabbit, mouse.", new[] { "read.hand-suits", "read.suits-of", "read.path-neighbours", "read.supply-warriors", "read.legal-actions" }, new[] { "state.global.roles" }, new[] { "WhiteHairedManBot_RecruitsWithRingSuitCards" }),
            ["bot.white-haired-man.03-plots"] = new BotRuleDef("bot.white-haired-man.03-plots", "bot.white-haired-man", 3, "Plots", "A Snare in the Ring clearing hardest to out-stack, flipped face up as the check nears so it holds that clearing regardless of numbers; a Bomb where tune.white-haired-man-bomb-warriors (3) or more enemy warriors gather in or beside the Ring; a Raid as a refill. Easy leaves one Ring clearing to a single face-down plot.", "Snare: the Ring clearing with the lowest margin (step 1), flipped face up from goal mode (step 6). Bomb: the clearing in or next to the Ring with the most enemy warriors, at least tune.white-haired-man-bomb-warriors. Raid: in a Ring clearing with no plot when no Snare or Bomb is due. Ties: lower clearing number.", new[] { "read.corvid-hidden-plot", "read.corvid-face-up-plot", "read.warriors", "read.path-neighbours", "read.tokens-of-type", "read.hand-suits", "read.seats", "read.legal-actions" }, new[] { "state.global.roles", "state.global.difficulty" }, new[] { "WhiteHairedManBot_SnaresLowestMarginRingClearing", "WhiteHairedManBot_BombsWhereThreeEnemiesGather", "WhiteHairedManBot_EasyLeavesOneRingClearingToFaceDownPlot" }),
            ["bot.white-haired-man.04-move-battle"] = new BotRuleDef("bot.white-haired-man.04-move-battle", "bot.white-haired-man", 4, "Move and battle", "Move and battle to fix the lowest-margin Ring clearing first, battling intruders there. Hard keeps a margin of tune.white-haired-man-hard-margin (2) in every Ring clearing.", "Ring clearings by margin, lowest first; a clearing is fixed when its margin is 1 or more (Hard: 2) or it holds a face-up Snare; ties: lower clearing number.", new[] { "read.warriors", "read.buildings", "read.path-neighbours", "read.ruler", "read.corvid-face-up-plot", "read.seats", "read.legal-actions" }, new[] { "state.global.roles", "state.global.difficulty", "state.esquie.rocks" }, new[] { "WhiteHairedManBot_FixesLowestMarginRingClearingFirst", "WhiteHairedManBot_HardKeepsMarginTwoInRing" }),
            ["bot.white-haired-man.05-spare-paintress"] = new BotRuleDef("bot.white-haired-man.05-spare-paintress", "bot.white-haired-man", 5, "Spare the Paintress", "He never attacks the Paintress unless she is one step from her own win (as the spoiler layer defines it): no battle against her seat and no Bomb where she has pieces.", "none (a plain condition)", new[] { "read.seats", "read.warriors", "read.buildings", "read.legal-actions" }, new[] { "state.global.seat-characters", "state.global.countdowns" }, new[] { "WhiteHairedManBot_NeverAttacksPaintressUnlessOneStepFromWin" }),
            ["bot.white-haired-man.06-goal-mode"] = new BotRuleDef("bot.white-haired-man.06-goal-mode", "bot.white-haired-man", 6, "Goal mode", "In goal mode (Vp(seat) >= tune.white-haired-man-goal-vp), no warrior in a Ring clearing or the Monolith moves out of them, and he battles any Vagabond pawn in the Monolith when he has warriors there.", "none (a plain condition)", new[] { "read.vp", "read.pawn-clearing", "read.seat-engine", "read.warriors", "read.path-neighbours", "read.seats", "read.legal-actions" }, new[] { "state.global.roles" }, new[] { "WhiteHairedManBot_GoalModeNeverLeavesRing", "WhiteHairedManBot_GoalModeBattlesVagabondInMonolith" }),
            ["bot.white-haired-man.07-spoiler"] = new BotRuleDef("bot.white-haired-man.07-spoiler", "bot.white-haired-man", 7, "Spoiler layer", "Shared spoiler layer (layer 3 of every bot; this part of the text is the same in all eleven plans). TRIGGER: another seat, the human included, that is not this bot's coalition partner, whose themed win is unlocked in the current act (Act II on; the Curator's from Act III) and not switched off (not switched off by that win's offWithDominance / offInCoalition), and that either has its countdown banner up (state.global.countdowns) or is one step from its win. One step means the public Goal Tracker shows every part of that win's test met except exactly one unit: one Arm pip, Chain suit, rock, Portrait suit, Sanctuary or Sanctuary suit, rank step, Allied faction, undamaged item, relic type, foot or source faction, covered clearing or Ring clearing, or one yes/no part (the Beachhead, the Monolith, Lumière, the Flying Manor atelier, an Aquafarm, the Parents' Journal recovered, the Warlord on the map, the tune.countdown-vp gate). ANSWER: attack or block the key clearing with a real Root action from that win's counterplay. Gustave: flip rule of the Chain clearing with the thinnest margin, or remove the Beachhead's buildings. Esquie (3 rocks held): the Nevron host moves extra warriors onto the last guarded rock (more defenders deal more hits to him) and every other bot attacks his pawn to damage items. The Paintress: break an easel, flip rule of a Portrait clearing or thin it below tune.paintress-portrait-warriors warriors, or take the Monolith. Sciel: before her banner, step a piece into a Sanctuary (paying Outrage); once it is up, battle a Lantern off the board, place a building or token in a Lantern clearing, or raze her only Aquafarm. Verso: before his banner, put a warrior, building or pawn in the Monolith (tokens do not block him); once it is up, battle him there and land a hit. Maelle: attack her in Lumière and damage items until fewer than tune.maelle-items are undamaged. Lune: battle the warriors carrying the Parents' Journal or her missing relic type, and hold the clearings around the gold forest. Monoco: battle the Warlord off the map (Sacred River Rebirth strips Almighty and his latest other foot). The Curator: flip rule of Lumière or remove his Monolith tunnel; with no keep in Lumière, raze his building there and cut his warriors below tune.curator-lumiere-warriors; keep the Paintress's roost in the Monolith alive. Clea: remove her warriors from one counted clearing (lone Nevrons first) or from the Monolith, or raze the Flying Manor atelier. The White-Haired Man: out-stack him in one Ring clearing, guess a plot with Exposure, or walk a Vagabond pawn into the Monolith. LIMITS: it obeys every rule tweak and every 'never' and 'only' in the steps above it, uses only public information plus this bot's own hand and hidden pieces, and barks the block. PRIORITY: with no trigger it does nothing. It is listed last, as in the roster, but takes the actions it needs ahead of the steps above (it pre-empts them) in two cases: a banner that is up, because that seat confirms before this bot's next Birdsong, unless this bot can finish a quest win this turn; and, on Hard only, a one-step threat, unless this is this bot's own announce turn (its own confirmation would land first). Otherwise it answers with the actions the steps above leave free. Easy answers banners only, and only with free actions. FOR THE WHITE-HAIRED MAN: step 5 binds (the Paintress only once she is one step from her win), and in goal mode his warriors stay in the Ring and the Monolith (step 6), so he answers there or with Recruit placements and plots (a Bomb where the key clearing gathers enemy warriors).", "Threats: banners before one-step threats; then the seat whose next Birdsong comes first in turn order (read.seats from read.current-seat); then the higher VP. For the chosen threat, answer cost = actions needed this turn + expected hits taken (Root's dice: two 0-3 dice, the attacker deals the higher and the defender the lower, each capped by its warriors; +1 hit to a defender with no warriors). Take the cheapest legal answer, breaking a met part before blocking the missing unit; ties: the answer nearest this bot's pieces, then the lower clearing number.", new[] { "read.seats", "read.current-seat", "read.seat-engine", "read.vp", "read.active-dominance", "read.coalition-partner", "read.ruler", "read.warriors", "read.buildings", "read.buildings-of-type", "read.tokens", "read.tokens-of-type", "read.pawn-clearing", "read.items", "read.relationship", "read.path-neighbours", "read.suits-of", "read.clearings", "read.recovered-relics", "read.relic-type", "read.relic-clearing", "read.relic-forest", "read.forest-clearings", "read.corvid-face-up-plot", "read.legal-actions", "read.corvid-hidden-plot", "read.hand-suits", "read.is-bot" }, new[] { "state.global.countdowns", "state.global.act", "state.global.roles", "state.global.seat-characters", "state.global.difficulty", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.monoco.feet", "state.lune.tagged-relic", "state.curator.cell-crack" }, new[] { "WhiteHairedManBot_SpoilerStaysInRingInGoalMode", "WhiteHairedManBot_SpoilerSparesPaintressUnlessOneStep" }),
        };

