        public static readonly IReadOnlyDictionary<string, StoryEventDef> StoryEvents = new Dictionary<string, StoryEventDef>
        {
            ["story.act1.landing"] = new StoryEventDef("story.act1.landing", "act1", "vignette", "Act I, 'The Landing', opens after the prologue with a short, skippable speech-bubble scene: Expedition 33 comes ashore on the Continent, the landing goes badly, and the survivors regroup. The Monolith Number appears on the Monolith (33 minus the top score). No themed win can happen in Act I. Nothing on the board changes.", null, "safe", false),
            ["story.act1.florrie"] = new StoryEventDef("story.act1.florrie", "act1", "spawn", "At setup, if Esquie is seated: Florrie is placed at Stone Wave Cliffs with 2 guard warriors from the Nevron host's supply under a Lampmaster badge (fewer if the host's supply runs short; the guard counter equals the number placed). No-spawn fallback, the v1 default if the week-1 spike shows the mod cannot place another seat's warriors: Florrie sits at the Cliffs unguarded and can be claimed only when no faction other than Esquie has warriors there.", "spawn.florrie", "safe", true),
            ["story.act1.francois-decoy"] = new StoryEventDef("story.act1.francois-decoy", "act1", "spawn", "At setup, if Esquie is seated: a cosmetic François decoy badge sits at Esquie's Nest. It has no guard warrior and holds no rock. When Esquie enters the Nest while it is up, he barks that this is not Florrie, the badge points him to Stone Wave Cliffs, and it is removed. It also goes when Act I ends.", "spawn.francois-decoy", "safe", false),
            ["story.act2.beach"] = new StoryEventDef("story.act2.beach", "act2", "vignette", "Opens Act II in finished mode only, and only when Gustave is seated: 'The Beach' plays as a what-if ('This time, the arm held.'). With Faithful Gustave on, it instead retitles Gustave's seat 'Expedition 33', the survivors carrying his flag, with the same engine, flags, gauge and win. Safe mode skips it. Cosmetic: no charge, VP or board change.", null, "finished", false),
            ["story.act2.unlock-wins"] = new StoryEventDef("story.act2.unlock-wins", "act2", "unlock", "Themed wins unlock: from now on the announce and quest checks run for every character whose win starts in Act II, so banners can go up. The Curator's win stays locked until Act III. The White-Haired Man's Act I-only rule, Unbeatable in Act I, switches off at the same moment.", null, "safe", false),
            ["story.act2.dorrie"] = new StoryEventDef("story.act2.dorrie", "act2", "spawn", "If Esquie is seated: Dorrie is hidden in the Old Lumière ruin. He claims it by Exploring that ruin, or just by entering if the ruin is already empty. While the White-Haired Man is seated, Dorrie cannot be claimed while his warriors are in Old Lumière. It has no guards, so nothing is placed on Root's board.", "spawn.dorrie", "act2", false),
            ["story.act2.soarrie"] = new StoryEventDef("story.act2.soarrie", "act2", "spawn", "If Esquie is seated: Soarrie appears on Verso's card when Verso is seated; otherwise whichever faction rules the Monolith holds it. Esquie takes it from Verso by ending his turn in Verso's clearing (Verso then scores 1 VP for the reunion, a player action rather than part of this event), from the Monolith's ruler by Aiding that faction once while in the Monolith, or by entering the Monolith while no faction rules it.", "spawn.soarrie", "act2", false),
            ["story.act2.parents-journal"] = new StoryEventDef("story.act2.parents-journal", "act2", "tag", "If Lune is seated: the mod tags one relic as the Parents' Journal, the highest-value tablet still lying in a forest (if no tablet is left in the forests, the highest-value relic of any type in a forest). It is moved into the forest beside Sirène if the engine allows, otherwise tagged where it lies, and its forest glows gold. If an enemy knocks the tagged relic loose (Prized Trophies), it goes face up into a forest and keeps its tag.", "spawn.parents-journal", "act2", true),
            ["story.act3.fall"] = new StoryEventDef("story.act3.fall", "act3", "vignette", "Act III, 'The Canvas', opens with 'The Fall at the Monolith': a short, skippable vignette, after which Lumière is marked as the final battlefield (a highlight on its clearing). Safe mode plays a neutral version. Nothing on the board changes.", null, "act2", false),
            ["story.act3.alicia"] = new StoryEventDef("story.act3.alicia", "act3", "portrait", "If Maelle is seated, her portrait changes. Finished mode shows Alicia, with scars and a brush, and unlocks her Act III barks; safe mode shows 'a memory returns'. Cosmetic only: no relationship or VP change.", null, "act2", false),
            ["story.act3.cell-crack"] = new StoryEventDef("story.act3.cell-crack", "act3", "spawn", "If the Curator is seated: the Cell Crack overlay, inert in the Monolith since setup, becomes a real Duchy tunnel from his supply (a free extra one if all three are on the map). Fallback if the mod cannot place it: his first Act III action is a free Dig into the Monolith. His win unlocks now. Finished mode also reveals his face; safe mode keeps the faceless Curator.", "spawn.cell-crack", "act2", true),
            ["story.act3.urrie"] = new StoryEventDef("story.act3.urrie", "act3", "spawn", "If Esquie is seated and Urrie has not spawned yet: Urrie is placed at Esquie's Nest with 3 guard warriors from the Nevron host's supply under a François badge (fewer if the host's supply runs short). Outside this event, Urrie spawns early as soon as Esquie holds the other three rocks. The no-spawn fallback works as for Florrie.", "spawn.urrie", "act2", true),
            ["story.act3.almighty"] = new StoryEventDef("story.act3.almighty", "act3", "unlock", "If Monoco is seated, his Almighty foot opens: from now on he earns it by removing a building of the current VP leader (when the leader is not Monoco), or in one battle where the Hundreds remove 3 or more of the leader's pieces.", null, "safe", false),
        };

        public static readonly IReadOnlyDictionary<string, SpawnDef> Spawns = new Dictionary<string, SpawnDef>
        {
            ["spawn.florrie"] = new SpawnDef("spawn.florrie", "esquie", "act1", "role.stone-wave-cliffs", 2, "Guarded rock (spawned at setup when Esquie is seated). tune.esquie-guards-florrie warriors are placed from the Nevron host's supply with a Lampmaster badge; GuardsLeft = the number actually placed (0 placed makes it loose at once). Host: Clea if seated; otherwise the non-Marquise, non-Vagabond faction with the most warriors in supply (ties: lowest VP, then lowest seat); otherwise the Marquise. GuardsLeft drops by one for every host warrior removed in that clearing in any battle, whoever fought it; at 0 the rock is loose. After each of Esquie's actions he claims every loose rock in his pawn's clearing. A claimed rock is never lost.", "state.esquie.rocks", "ui.esquie.rocks", new[] { "do.place-warriors", "do.set-guard-floor", "do.block-placement", "do.show-overlay", "do.hide-overlay" }, "No-spawn fallback (the v1 default if the week-1 spike shows the mod cannot place another seat's warriors): no guards and no host; Florrie can be claimed only when no faction other than Esquie has warriors at Stone Wave Cliffs.", new[] { "FlorrieSpawn_PlacedAtCliffsWithTwoGuards", "FlorrieSpawn_HostPriorityCleaThenSupplyThenMarquise", "FlorrieSpawn_ShortSupplySetsGuardsLeftToPlaced", "FlorrieSpawn_NoSpawnFallbackClaimsWhenClearingFree" }),
            ["spawn.dorrie"] = new SpawnDef("spawn.dorrie", "esquie", "act2", "role.old-lumiere", 0, "Hidden in the Old Lumière ruin from the start of Act II (loose at once if that ruin was already emptied, or if Old Lumière has no ruin on this map). Esquie claims it by Exploring that ruin, or by ending any action there while Dorrie is loose. If the White-Haired Man (Corvids) is seated, it cannot be claimed while Corvid warriors are in Old Lumière; an Explore made then empties the ruin and leaves Dorrie loose. Never lost once claimed. Any other Vagabond's Explore of Old Lumière from Act II leaves Dorrie loose there (the ruin is now empty).", "state.esquie.rocks", "ui.esquie.rocks", new[] { "do.show-overlay", "do.hide-overlay" }, "If Root's Explore cannot be hooked, Dorrie is claimed by ending an action in Old Lumière once its ruin is empty (the core polls read.has-ruin after each action).", new[] { "DorrieSpawn_ClaimedByExploringOldLumiere", "DorrieSpawn_LooseWhenRuinAlreadyEmpty", "DorrieSpawn_BlockedWhileCorvidWarriorsPresent", "DorrieSpawn_LooseAfterAnotherVagabondExplores" }),
            ["spawn.soarrie"] = new SpawnDef("spawn.soarrie", "esquie", "act2", "rule: on Verso's card if Verso is seated; otherwise held by whichever faction rules role.monolith", 0, "With Verso seated (needs The Riverfolk Expansion): Soarrie passes to Esquie when Esquie ends his turn in Verso's clearing, and Verso scores tune.verso-soarrie-vp VP. Without Verso: the Monolith's current ruler holds it; Esquie claims it by Aiding that faction once while in the Monolith, or by ending any action in the Monolith while no faction rules it. Never lost once claimed.", "state.esquie.rocks", "ui.esquie.rocks", new[] { "do.score-vp", "do.show-overlay", "do.hide-overlay" }, "If VP cannot be added at the end of Esquie's turn, Verso's 1 VP is added at the start of his next Birdsong; the hand-off itself is pure mod state and always works.", new[] { "SoarrieSpawn_StartsOnVersoWhenSeated", "SoarrieSpawn_HeldByMonolithRulerWithoutVerso", "SoarrieSpawn_ClaimedByAidingRulerInMonolith", "SoarrieSpawn_ClaimedFreeWhenMonolithUnruled" }),
            ["spawn.urrie"] = new SpawnDef("spawn.urrie", "esquie", "act3", "role.esquies-nest", 3, "Guarded rock: spawns at the start of Act III, or as soon as Esquie holds the other three rocks if that comes first. tune.esquie-guards-urrie warriors are placed from the Nevron host's supply with a François badge (host chosen again at spawn time by the same priority as Florrie); GuardsLeft = the number actually placed. GuardsLeft drops by one for every host warrior removed in that clearing in any battle; at 0 it is loose and Esquie claims it after any of his actions in the Nest. Never lost once claimed.", "state.esquie.rocks", "ui.esquie.rocks", new[] { "do.place-warriors", "do.set-guard-floor", "do.block-placement", "do.show-overlay", "do.hide-overlay" }, "No-spawn fallback: no guards; Urrie can be claimed only when no faction other than Esquie has warriors at Esquie's Nest.", new[] { "UrrieSpawn_AppearsAtActThreeWithThreeGuards", "UrrieSpawn_AppearsEarlyWhenOtherThreeHeld", "UrrieSpawn_NoSpawnFallbackClaimsWhenNestFree" }),
            ["spawn.francois-decoy"] = new SpawnDef("spawn.francois-decoy", "esquie", "act1", "role.esquies-nest", 0, "Cosmetic only, no guard warrior and no rock. When Esquie's pawn enters the Nest during Act I while the decoy is up, his 'that's not Florrie' bark plays, the bubble points to Stone Wave Cliffs, and the decoy is removed. It is also removed at the start of Act II.", "state.esquie.decoy", "ui.esquie.francois-decoy", new[] { "do.show-bubble", "do.show-overlay", "do.hide-overlay" }, "If the badge cannot be drawn on the board, only the bark plays when Esquie first enters the Nest in Act I.", new[] { "FrancoisDecoy_EnteringNestGivesNoRockAndRemovesDecoy", "FrancoisDecoy_GoneAtActTwo" }),
            ["spawn.parents-journal"] = new SpawnDef("spawn.parents-journal", "lune", "act2", "rule: the forest touching both role.sirene and role.monolith (lowest forest number if several); wherever the chosen relic lies if relics cannot be moved or the map has no Sirène", 0, "At the start of Act II (when Lune is seated) the highest-value tablet still lying in a forest is tagged as the Parents' Journal (if no tablet is left in the forests, the highest-value relic of any type in a forest) and moved into the forest beside Sirène if the engine allows; its forest glows gold. Lune recovers it like any relic (Delve, carry, Recover at a matching waystation). If an enemy knocks it loose (Prized Trophies) it goes face up into a forest and keeps its tag.", "state.lune.tagged-relic", "ui.lune.journal-glow", new[] { "do.tag-relic", "do.move-relic", "do.show-overlay", "do.hide-overlay" }, "If relics cannot be moved, tag the chosen relic where it lies. If relic values are hidden while face down, choose the forest tablet nearest to Sirène by path distance from the clearings around its forest (ties: lowest forest number). If types are hidden too, tag the forest relic nearest Sirène (same distance rule and ties).", new[] { "ParentsJournal_TagsHighestValueForestTablet", "ParentsJournal_FallsBackToHighestValueAnyType", "ParentsJournal_TagSurvivesPrizedTrophies" }),
            ["spawn.cell-crack"] = new SpawnDef("spawn.cell-crack", "curator", "act1", "role.monolith", 0, "Not claimable. At setup (when the Curator is seated) a crack overlay is drawn in the Monolith. Until Act III it does nothing: it is not a tunnel, does not connect to the Burrow and does not use one of his three tunnels. At the start of Act III it becomes a real Duchy tunnel from his supply, or a free extra tunnel if all three are on the map. If that tunnel is later removed, he may Dig it again normally.", "state.curator.cell-crack", "ui.curator.cell-crack", new[] { "do.place-tunnel", "do.grant-free-dig", "do.show-overlay", "do.hide-overlay" }, "If the mod cannot place a tunnel, his first Act III action is a free Dig into the Monolith (state 'dig-owed', do.grant-free-dig). If a free Dig cannot be granted either, he Digs into the Monolith normally, paying the card.", new[] { "CellCrack_InertBeforeActThree", "CellCrack_BecomesTunnelAtActThree", "CellCrack_FreeExtraTunnelWhenAllPlaced" }),
        };

        public static readonly IReadOnlyDictionary<string, MapRoleDef> MapRoles = new Dictionary<string, MapRoleDef>
        {
            ["role.lumiere"] = new MapRoleDef("role.lumiere", "Lumière", "Autumn: fixed to autumn.01 (bottom-left corner, by the lake), from the real board in map_autumn.json. Other maps: The corner clearing that holds Gustave's keep. The Marquise sets up first, so the role is fixed as soon as the keep is placed, before any other faction sets up. When Gustave is not seated, the corner is chosen by rule at map load: the corner with the lowest Root clearing number.", "1", new[] { "gustave", "maelle", "curator" }, new[] { "MapRoles_LumiereIsTheKeepCorner", "MapRoles_LumiereIsLowestNumberedCornerWithoutGustave", "MapRoles_SingleClearingRolesNeverShareAClearing", "MapRoles_AssignsEveryRoleOnAnyTwelveClearingMap" }),
            ["role.monolith"] = new MapRoleDef("role.monolith", "The Monolith", "Autumn: fixed to autumn.03 (top-right corner), from the real board in map_autumn.json. Other maps: The corner Root itself treats as diagonally opposite Lumière (the one normal Marquise setup leaves without a warrior, and the one Bird dominance pairs with it). On a map where Root has no such pairing, the corner farthest from Lumière by path distance; ties go to the lowest Root clearing number. The Paintress's first roost is forced here.", "1", new[] { "paintress", "gustave", "verso", "white-haired-man", "clea", "curator", "esquie" }, new[] { "MapRoles_MonolithIsDiagonallyOppositeLumiere", "MapRoles_MonolithFallsBackToFarthestCorner" }),
            ["role.esquies-nest"] = new MapRoleDef("role.esquies-nest", "Esquie's Nest", "Autumn: fixed to autumn.02 (bottom-right corner, by a pond), from the real board in map_autumn.json. Other maps: One of the two corners left after Lumière and the Monolith. The Nest is the one that has a Stone Wave Cliffs candidate (a clearing 1-2 steps away by path that is not a corner, not a Monolith path neighbour and not Old Lumière); if both or neither have one, the one with the lower Root clearing number. The other corner is the Flying Manor.", "1", new[] { "esquie" }, new[] { "MapRoles_NestIsTheFreeCornerWithACliffsCandidate", "MapRoles_NestTieGoesToLowerClearingNumber" }),
            ["role.flying-manor"] = new MapRoleDef("role.flying-manor", "Flying Manor", "Autumn: fixed to autumn.04 (top-left corner), from the real board in map_autumn.json. Other maps: The last corner, once Lumière, the Monolith and Esquie's Nest are assigned. Clea's home corner is forced here.", "1", new[] { "clea" }, new[] { "MapRoles_FlyingManorIsTheLastCorner" }),
            ["role.stone-wave-cliffs"] = new MapRoleDef("role.stone-wave-cliffs", "Stone Wave Cliffs", "Autumn: fixed to autumn.06 (bottom center, on the river), from the real board in map_autumn.json. Other maps: A clearing 1-2 steps by path from Esquie's Nest that is not a corner, not a path neighbour of the Monolith and not Old Lumière. Nearest first (1 step before 2), then the lowest Root clearing number. If none qualifies, the nearest clearing to the Nest that is not a corner, not a Monolith neighbour and not Old Lumière.", "1", new[] { "esquie" }, new[] { "MapRoles_CliffsIsOneOrTwoStepsFromNestAndNotAMonolithNeighbour", "MapRoles_CliffsPrefersNearestThenLowestNumber", "MapRoles_CliffsFallsBackToNearestFreeClearing" }),
            ["role.old-lumiere"] = new MapRoleDef("role.old-lumiere", "Old Lumière", "Autumn: fixed to autumn.08 (center-left (the central fox clearing)), from the real board in map_autumn.json. Other maps: The most central ruin clearing: among ruin clearings that are not corners and not Monolith path neighbours, the one with the smallest total path distance to every other clearing; ties go to the lowest Root clearing number. If no ruin qualifies, the most central clearing by the same measure that is not a corner or a Monolith neighbour.", "1", new[] { "esquie" }, new[] { "MapRoles_OldLumiereIsTheMostCentralRuin", "MapRoles_OldLumiereFallsBackToMostCentralClearing" }),
            ["role.visages"] = new MapRoleDef("role.visages", "Visages", "Autumn: fixed to autumn.09 (right middle), from the real board in map_autumn.json. Other maps: The Axons are the Monolith's path neighbours at map load, taken in order of Root clearing number: the first is Visages, the second Sirène, the third The Reacher. Rivers are not paths, and closed Mountain paths do not count. A fourth or later neighbour gets no Axon name but is still a Monolith neighbour for every rule that reads adjacency.", "1", new[] { "white-haired-man", "gustave" }, new[] { "MapRoles_AxonsFollowMonolithNeighboursInClearingOrder", "MapRoles_ClosedMountainPathsDoNotMakeAxons" }),
            ["role.sirene"] = new MapRoleDef("role.sirene", "Sirène", "Autumn: fixed to autumn.10 (upper center-left, on the river), from the real board in map_autumn.json. Other maps: The second Monolith path neighbour by Root clearing number (see Visages). Lune's Parents' Journal goes in the forest beside it. There is none on a map where the Monolith has only one open path neighbour; the Journal is then tagged where it lies.", "0-1", new[] { "lune", "white-haired-man", "gustave" }, new[] { "MapRoles_SireneIsTheSecondMonolithNeighbour" }),
            ["role.the-reacher"] = new MapRoleDef("role.the-reacher", "The Reacher", "Autumn: fixed to autumn.11 (top center), from the real board in map_autumn.json. Other maps: The third Monolith path neighbour by Root clearing number, when there is one (see Visages).", "0-1", new[] { "white-haired-man", "gustave" }, new[] { "MapRoles_ReacherOnlyWithAThirdMonolithNeighbour" }),
            ["role.sacred-river"] = new MapRoleDef("role.sacred-river", "Sacred River", "Autumn: autumn.01, autumn.06, autumn.07, autumn.10, autumn.11 (the river clearings in map_autumn.json). Other maps: Every clearing a river touches; on Lake, every clearing on the lake shore. It is a tag drawn as a river of chroma, not a place name: these clearings keep their own names and may also hold another role.", "all river clearings (0 on a map with no river)", new[] { "monoco", "esquie" }, new[] { "MapRoles_SacredRiverTagsEveryRiverClearing", "MapRoles_LakeShoreCountsAsSacredRiver" }),
        };

        public static readonly IReadOnlyDictionary<string, MapAutumnDef> MapAutumn = new Dictionary<string, MapAutumnDef>
        {
            ["autumn.01"] = new MapAutumnDef("autumn.01", "Lumière", "role.lumiere", "A broken island city of crooked towers, where every expedition is waved off under the number painted across the sea.", "bottom-left corner, by the lake", 1, new[] { "autumn.05", "autumn.08", "autumn.12" }, true, "rabbit", true, false),
            ["autumn.02"] = new MapAutumnDef("autumn.02", "Esquie's Nest", "role.esquies-nest", "A cosy hollow of round stones and enormous footprints, with a grumpy turtle living next door.", "bottom-right corner, by a pond", 1, new[] { "autumn.06", "autumn.07", "autumn.09" }, false, "rabbit", true, false),
            ["autumn.03"] = new MapAutumnDef("autumn.03", "The Monolith", "role.monolith", "A stone spire at the edge of the world where the number is painted, one stroke shorter every year.", "top-right corner", 2, new[] { "autumn.09", "autumn.10", "autumn.11" }, false, "mouse", true, false),
            ["autumn.04"] = new MapAutumnDef("autumn.04", "Flying Manor", "role.flying-manor", "A manor adrift in a ring of floating rocks; its windows are always lit and nobody answers the door.", "top-left corner", 1, new[] { "autumn.10", "autumn.11", "autumn.12" }, false, "fox", true, false),
            ["autumn.05"] = new MapAutumnDef("autumn.05", "Spring Meadows", null, "Soft green hills just past the landing beach, where the expedition first learned the Continent bites back.", "bottom center-left", 2, new[] { "autumn.01", "autumn.06" }, false, "fox", false, false),
            ["autumn.06"] = new MapAutumnDef("autumn.06", "Stone Wave Cliffs", "role.stone-wave-cliffs", "Waves of rock frozen mid-crash, patrolled by a lamp that should not be able to walk.", "bottom center, on the river", 2, new[] { "autumn.02", "autumn.05", "autumn.08" }, true, "mouse", false, false),
            ["autumn.07"] = new MapAutumnDef("autumn.07", "Gestral Village", null, "Wooden arenas and cheerful brawlers who settle every argument with a friendly duel.", "center, on the river", 3, new[] { "autumn.02", "autumn.08", "autumn.09" }, true, "mouse", false, false),
            ["autumn.08"] = new MapAutumnDef("autumn.08", "Old Lumière", "role.old-lumiere", "The drowned old city, its rooftops poking out of still green water like gravestones.", "center-left (the central fox clearing)", 2, new[] { "autumn.01", "autumn.06", "autumn.07", "autumn.10", "autumn.12" }, false, "fox", false, true),
            ["autumn.09"] = new MapAutumnDef("autumn.09", "Visages", "role.visages", "A valley of carved stone faces, each one wearing a different mood.", "right middle", 2, new[] { "autumn.02", "autumn.03", "autumn.07" }, false, "fox", false, true),
            ["autumn.10"] = new MapAutumnDef("autumn.10", "Sirène", "role.sirene", "Silk-draped dunes and a slow, lovely song that pulls travellers off the path.", "upper center-left, on the river", 2, new[] { "autumn.03", "autumn.04", "autumn.08" }, true, "rabbit", false, true),
            ["autumn.11"] = new MapAutumnDef("autumn.11", "The Reacher", "role.the-reacher", "A long cold shoreline where something enormous keeps stretching toward the sky.", "top center", 2, new[] { "autumn.03", "autumn.04" }, true, "rabbit", false, false),
            ["autumn.12"] = new MapAutumnDef("autumn.12", "Forgotten Battlefield", null, "Rusted blades and torn banners from an expedition nobody remembers sailing.", "left middle", 2, new[] { "autumn.01", "autumn.04", "autumn.08" }, false, "mouse", false, true),
        };

        public static readonly IReadOnlyDictionary<string, OverlayDef> Overlays = new Dictionary<string, OverlayDef>
        {
            ["ui.global.title"] = new OverlayDef("ui.global.title", "global", "screen", "The ROOT 33 title over Root's main menu: Root's own logo with the 33 tearing out of a glowing rift beside it, petals drifting off. Shown at every launch and on every return to the main menu (hook.title-screen). Any roster shown on the title screen uses safe names only.", true, new[] { "asset.title-rift", "asset.root-logo", "asset.root-font" }, Array.Empty<string>(), true),
            ["ui.global.spoiler-prompt"] = new OverlayDef("ui.global.spoiler-prompt", "global", "screen", "First launch only: two buttons, 'Spoiler-safe' and 'I've finished Clair Obscur: Expedition 33', with a line saying the choice can be changed later in settings. Then an offer to play or skip the speech-bubble prologue (the Gommage and the send-off).", true, new[] { "asset.prompt-frame", "asset.root-font" }, Array.Empty<string>(), true),
            ["ui.global.settings"] = new OverlayDef("ui.global.settings", "global", "screen", "The mod's settings panel: spoiler mode, bot difficulty, Faithful Gustave (shown only in finished mode) and the campaign. A spoiler-mode change applies from the next game.", true, new[] { "asset.prompt-frame", "asset.root-font" }, Array.Empty<string>(), true),
            ["ui.global.character-select"] = new OverlayDef("ui.global.character-select", "global", "screen", "One card per character on Root's faction-select screen in E33 mode: portrait, safe or finished name, the Root engine and any DLC it needs, the spoiler-safe summary, the win's title, and the lore rival the mod will try to seat. In safe mode Clea's card shows '???' and a lock. A character whose DLC is not owned is hidden, and the Clockwork bots are not offered.", true, new[] { "asset.card-frame", "asset.portrait-fallback", "asset.root-font" }, Array.Empty<string>(), true),
            ["ui.global.vignette"] = new OverlayDef("ui.global.vignette", "global", "screen", "Short, skippable speech-bubble scenes: the prologue (the Gommage and the send-off), each act's opening vignette (The Landing; The Beach in finished mode; The Fall at the Monolith) and story-event captions such as 'a memory returns'. Each scene plays the version its spoiler tier allows.", true, new[] { "asset.vignette-frame", "asset.bubble-frame", "asset.petals" }, new[] { "state.global.act" }, true),
            ["ui.global.ending-card"] = new OverlayDef("ui.global.ending-card", "global", "screen", "The frame for the winner's ending card when a themed win is declared: portrait, the win's title and an original-text ending over a short camera tour of the board. Each character's vignette, with its safe and finished versions, is its own row: ui.gustave.ending, ui.esquie.ending, ui.paintress.ending, ui.sciel.ending, ui.verso.ending, ui.maelle.ending, ui.lune.ending, ui.monoco.ending, ui.curator.ending, ui.clea.ending and ui.white-haired-man.ending. Ending-flavoured vignettes (Verso's, Maelle's and the Curator's) appear only in finished mode, and safe mode shows their plain version; Clea's card is finished-only because she is never seated in safe mode.", true, new[] { "asset.vignette-frame", "asset.petals", "asset.portrait-fallback" }, new[] { "state.global.spoiler-mode" }, true),
            ["ui.global.countdown-banner"] = new OverlayDef("ui.global.countdown-banner", "global", "banner", "A public banner put up at the end of a seat's turn when its countdown win is announced: the character, the win's title, that it takes effect at the start of their next Birdsong, and how to stop it (the win's counterplay line). It comes down when the confirmation fails or the game ends.", true, new[] { "asset.banner-frame", "asset.root-font" }, new[] { "state.global.countdowns" }, true),
            ["ui.global.goal-tracker"] = new OverlayDef("ui.global.goal-tracker", "global", "tracker", "A public panel with one row per seat: the character, the win's title, each step of its test marked done or not (read live from the board or from saved state), and a highlight when a seat is one step away. A win that is still locked shows the act that unlocks it. Bots' spoiler layer reads exactly what this panel shows.", true, new[] { "asset.tracker-frame", "asset.root-suit-icons", "asset.root-font" }, new[] { "state.global.act", "state.global.countdowns", "state.gustave.flags", "state.gustave.arm", "state.esquie.rocks", "state.verso.rank", "state.lune.tagged-relic", "state.monoco.feet", "state.curator.cell-crack" }, true),
            ["ui.global.monolith-number"] = new OverlayDef("ui.global.monolith-number", "global", "label", "The Monolith Number painted on the Monolith clearing: 33 (tune.monolith-number-start) minus the top score, ticking down as anyone scores. Refreshed at hook.vp-changed.", true, new[] { "asset.monolith-plate", "asset.root-font" }, Array.Empty<string>(), true),
            ["ui.global.act-banner"] = new OverlayDef("ui.global.act-banner", "global", "banner", "A banner when an act begins: 'Act I: The Landing' after setup, 'Act II: The Monolith' and 'Act III: The Canvas' later, each with one line on what unlocks (themed wins at Act II; the Curator's win and Almighty at Act III).", true, new[] { "asset.banner-frame", "asset.root-font" }, new[] { "state.global.act" }, true),
            ["ui.global.speech-bubble"] = new OverlayDef("ui.global.speech-bubble", "global", "bubble", "A speech bubble over a seat's portrait or pawn showing one bark's text (do.show-bubble). Text only, no voice. One bubble at a time; it fades after a few seconds or on a click.", true, new[] { "asset.bubble-frame", "asset.root-font" }, Array.Empty<string>(), true),
            ["ui.global.clearing-names"] = new OverlayDef("ui.global.clearing-names", "global", "label", "Continent names on the clearings (the map_autumn names on Autumn, role names on any map), each with its flavour line as a tooltip, and the Sacred River drawn as a ribbon of chroma along the river clearings.", true, new[] { "asset.label-plate", "asset.sacred-river", "asset.root-font" }, new[] { "state.global.roles" }, true),
            ["ui.global.final-battlefield"] = new OverlayDef("ui.global.final-battlefield", "global", "badge", "From Act III, a highlight on Lumière marking it as the final battlefield (story.act3.fall).", true, new[] { "asset.final-battlefield" }, new[] { "state.global.act", "state.global.roles" }, true),
            ["ui.gustave.flags"] = new OverlayDef("ui.gustave.flags", "gustave", "token", "An Expedition Flag painted with 33 on every flagged clearing, joined by a dotted route back to Lumière. A flag in a clearing he no longer rules is drawn faded: it stays, but does not count toward his Chain.", true, new[] { "asset.flag-token", "asset.route-dots" }, new[] { "state.gustave.flags" }, true),
            ["ui.gustave.arm"] = new OverlayDef("ui.gustave.arm", "gustave", "gauge", "Gustave's Arm on his faction board: three pips that glow from blue to white as it charges, and the pre-battle Overcharge toggle, which can be switched on only at 3/3 when he attacks. Firing Overcharge plays a lightning crack.", true, new[] { "asset.arm-gauge", "asset.sfx.overcharge" }, new[] { "state.gustave.arm", "state.gustave.overcharge-armed" }, true),
            ["ui.gustave.road"] = new OverlayDef("ui.gustave.road", "gustave", "tracker", "The public Road tracker: the clearings of his current ruled Chain, the suits it covers out of fox, rabbit and mouse, whether it reaches a Beachhead holding one of his buildings, and the Arm's charge.", true, new[] { "asset.tracker-frame", "asset.root-suit-icons" }, new[] { "state.gustave.flags", "state.gustave.arm" }, true),
            ["ui.gustave.ending"] = new OverlayDef("ui.gustave.ending", "gustave", "screen", "Gustave's ending card when The Road to the Monolith is declared: the flag trail lit end to end along his ruled Chain, the camp pitched at the Monolith's doorstep, and the painted Monolith Number cracking, under an original-text ending. The motto about those who come after is alluded to, never quoted. Safe and finished modes show the same card, since it holds no ending spoiler.", true, new[] { "asset.vignette-frame", "asset.portrait.gustave", "asset.flag-token", "asset.route-dots", "asset.monolith-plate" }, new[] { "state.gustave.flags", "state.global.spoiler-mode" }, true),
            ["ui.esquie.rocks"] = new OverlayDef("ui.esquie.rocks", "esquie", "token", "Esquie's four rocks on the map: Florrie sparkling at Stone Wave Cliffs, Dorrie hidden in the Old Lumière ruin, Soarrie on Verso's card or beside whoever rules the Monolith, and Urrie at Esquie's Nest. A guarded rock shows how many guards are left, a loose rock bounces, and a claimed rock leaves the map for his ring.", true, new[] { "asset.rock-tokens" }, new[] { "state.esquie.rocks" }, true),
            ["ui.esquie.rock-ring"] = new OverlayDef("ui.esquie.rock-ring", "esquie", "tracker", "The public four-slot rock ring on his board; each slot lights up as its rock comes home.", true, new[] { "asset.rock-ring", "asset.rock-tokens" }, new[] { "state.esquie.rocks" }, true),
            ["ui.esquie.lampmaster-badge"] = new OverlayDef("ui.esquie.lampmaster-badge", "esquie", "badge", "A lamp-headed guard badge over Florrie's guard stack at Stone Wave Cliffs, until Florrie is loose.", true, new[] { "asset.badge-lampmaster" }, new[] { "state.esquie.rocks" }, true),
            ["ui.esquie.francois-badge"] = new OverlayDef("ui.esquie.francois-badge", "esquie", "badge", "A grumpy turtle badge over Urrie's guard stack at Esquie's Nest, until Urrie is loose.", true, new[] { "asset.badge-francois" }, new[] { "state.esquie.rocks" }, true),
            ["ui.esquie.francois-decoy"] = new OverlayDef("ui.esquie.francois-decoy", "esquie", "badge", "During Act I only, the same turtle badge sits at Esquie's Nest pretending to have Florrie. It has no guard and no rock: when Esquie enters, it points him to Stone Wave Cliffs and goes.", true, new[] { "asset.badge-francois" }, new[] { "state.esquie.decoy" }, true),
            ["ui.esquie.ending"] = new OverlayDef("ui.esquie.ending", "esquie", "screen", "Esquie's ending card when his Rocks Come Home: the whole table rides home on his back, ending in a dive, under an original-text ending. His rhyme and known lines are never printed. Safe and finished modes show the same card, since it holds no ending spoiler.", true, new[] { "asset.vignette-frame", "asset.portrait.esquie", "asset.rock-ring", "asset.rock-tokens" }, new[] { "state.esquie.rocks", "state.global.spoiler-mode" }, true),
            ["ui.esquie.fx"] = new OverlayDef("ui.esquie.fx", "esquie", "token", "Esquie's battles drawn as him sitting on the guards (asset.fx.esquie-sit). Same in safe and finished mode.", true, new[] { "asset.fx.esquie-sit" }, Array.Empty<string>(), true),
            ["ui.paintress.portraits"] = new OverlayDef("ui.paintress.portraits", "paintress", "token", "A framed portrait over every easel that is a Living Portrait right now, with the Paintress drawn at work beside it and red petals drifting as it goes up. Finished mode labels the three (one per suit) Verso, Clea and Renoir, 'as she remembers them' when that character is seated; safe mode shows veiled portraits.", true, new[] { "asset.portrait-frame", "asset.portrait-veiled", "asset.paintress-at-work", "asset.petals", "asset.portrait.verso", "asset.portrait.clea", "asset.portrait.white-haired-man" }, Array.Empty<string>(), true),
            ["ui.paintress.portrait-tracker"] = new OverlayDef("ui.paintress.portrait-tracker", "paintress", "tracker", "The public 'Portraits 0/3' tracker: one slot per suit (fox, rabbit, mouse), filled by a Living Portrait, plus whether she rules the Monolith with an easel there.", true, new[] { "asset.tracker-frame", "asset.root-suit-icons" }, Array.Empty<string>(), true),
            ["ui.paintress.grief"] = new OverlayDef("ui.paintress.grief", "paintress", "bubble", "When she falls into Grief (Turmoil, hook.turmoil): a smeared-canvas bubble over her board. Finished mode shows a short original real-world flashback caption inside it.", true, new[] { "asset.smeared-canvas", "asset.bubble-frame" }, Array.Empty<string>(), true),
            ["ui.paintress.ending"] = new OverlayDef("ui.paintress.ending", "paintress", "screen", "The Paintress's ending card when The Family Portrait is declared: the camera tours her three Living Portraits, the Monolith Number freezes, and the titanic Paintress silhouette rises, under an original-text ending in which she paints the number and never erases anyone. Finished mode labels the portraits Verso, Clea and Renoir; safe mode shows them veiled, as on the board.", true, new[] { "asset.vignette-frame", "asset.portrait.paintress", "asset.portrait-frame", "asset.portrait-veiled", "asset.paintress-at-work", "asset.monolith-plate", "asset.petals" }, new[] { "state.global.spoiler-mode" }, true),
            ["ui.sciel.gauges"] = new OverlayDef("ui.sciel.gauges", "sciel", "gauge", "Public Sun and Moon gauges on her board: Sun counts her Sanctuaries (out of 5, with the suits they cover), Moon counts Aquafarms on the map. A dusk tint spreads over the board as both fill. From v1.1 the gauges also show her Twilight Sun and Moon charges.", true, new[] { "asset.sun-moon-gauge", "asset.dusk-tint" }, new[] { "state.sciel.sun", "state.sciel.moon", "state.sciel.twilight-armed" }, true),
            ["ui.sciel.ending"] = new OverlayDef("ui.sciel.ending", "sciel", "screen", "Sciel's ending card when the Twilight Harvest is declared: the Aquafarm at twilight, in full harvest, with Lumière's children watching from the shore, under an original-text ending. Safe and finished modes show the same card, since it holds no ending spoiler.", true, new[] { "asset.vignette-frame", "asset.portrait.sciel", "asset.dusk-tint" }, new[] { "state.global.spoiler-mode" }, true),
            ["ui.sciel.fx"] = new OverlayDef("ui.sciel.fx", "sciel", "token", "Her Reaping (Revolt) plays a scythe sweeping in a harvest across the revolting clearing (asset.fx.sciel-reaping). Same in safe and finished mode.", true, new[] { "asset.fx.sciel-reaping" }, Array.Empty<string>(), true),
            ["ui.verso.rank"] = new OverlayDef("ui.verso.rank", "verso", "label", "A large public Perfection letter (D, C, B, A or S) on his character card. A rank-up plays a rising piano phrase; a hit that knocks it down plays a discordant chord.", true, new[] { "asset.rank-letters", "asset.stinger.verso-rank-up", "asset.stinger.verso-hit" }, new[] { "state.verso.rank" }, true),
            ["ui.verso.ending"] = new OverlayDef("ui.verso.ending", "verso", "screen", "Verso's ending card when The Last Note is declared. Finished mode: Verso alone in the Monolith while the brushstrokes of the board fade, nodding to his ending without quoting it. Safe mode: a plain card on which the rank letter flares S and the Monolith goes quiet, because the finished vignette hints at one of the two endings.", true, new[] { "asset.vignette-frame", "asset.portrait.verso", "asset.rank-letters" }, new[] { "state.verso.rank", "state.global.spoiler-mode" }, true),
            ["ui.verso.fx"] = new OverlayDef("ui.verso.fx", "verso", "token", "Get Back Up (Hideout) on his pawn: safe mode shows light knitting him back together; finished mode shows his painted body reassembling (asset.fx.verso-get-back-up).", true, new[] { "asset.fx.verso-get-back-up" }, new[] { "state.global.spoiler-mode" }, true),
            ["ui.maelle.family"] = new OverlayDef("ui.maelle.family", "maelle", "tracker", "Her public 'family' row: one portrait frame per non-Vagabond faction showing her relationship with it (Indifferent up to Allied, or Hostile), with a sketch of that character added at each step. A bot Maelle's chosen family factions are marked, since she says who her family is.", true, new[] { "asset.family-frames", "asset.portrait-fallback" }, new[] { "state.maelle.family" }, true),
            ["ui.maelle.stance"] = new OverlayDef("ui.maelle.stance", "maelle", "badge", "The stance chip on her card: Offensive, Defensive or Virtuose. Cosmetic; it changes her portrait pose and barks.", true, new[] { "asset.stance-chips" }, new[] { "state.maelle.stance" }, true),
            ["ui.maelle.ending"] = new OverlayDef("ui.maelle.ending", "maelle", "screen", "Maelle's ending card when A Home in the Canvas is declared. Finished mode: Lumière lit up with every character she is Allied or Friendly with. Safe mode: a plainer card, her portrait in Lumière beside her family row of relationship frames, with no other characters drawn in, because the finished vignette hints at one of the two endings.", true, new[] { "asset.vignette-frame", "asset.portrait.maelle", "asset.family-frames" }, new[] { "state.maelle.family", "state.global.spoiler-mode" }, true),
            ["ui.maelle.fx"] = new OverlayDef("ui.maelle.fx", "maelle", "token", "Aid drawn as Maelle sharing a keepsake (asset.fx.maelle-keepsake) and Disarm (Steal) as a rapier feint (asset.fx.maelle-disarm). Same in safe and finished mode.", true, new[] { "asset.fx.maelle-keepsake", "asset.fx.maelle-disarm" }, Array.Empty<string>(), true),
            ["ui.lune.journal-glow"] = new OverlayDef("ui.lune.journal-glow", "lune", "token", "From Act II, a gold glow on the forest holding the Parents' Journal and a tag on the relic itself, which follows it if it is carried or knocked loose.", true, new[] { "asset.journal-glow" }, new[] { "state.lune.tagged-relic" }, false),
            ["ui.lune.thesis"] = new OverlayDef("ui.lune.thesis", "lune", "tracker", "The public thesis tracker: Journal, Route Chart and Chroma Sample slots filled by the relics she has recovered, and a gold slot for the Parents' Journal.", true, new[] { "asset.thesis-tracker" }, new[] { "state.lune.tagged-relic" }, false),
            ["ui.lune.stains"] = new OverlayDef("ui.lune.stains", "lune", "gauge", "Her Stains (Fire, Ice, Lightning) glowing on her focus, with the pre-battle toggle that arms one for her next battle.", true, new[] { "asset.stain-icons" }, new[] { "state.lune.stains", "state.lune.stain-armed" }, false),
            ["ui.lune.ending"] = new OverlayDef("ui.lune.ending", "lune", "screen", "Lune's ending card when Her Parents' Work is complete: her finished chart of the Continent, with the Monolith circled and annotated, under an original-text ending. Safe and finished modes show the same card, since it holds no ending spoiler.", true, new[] { "asset.vignette-frame", "asset.portrait.lune", "asset.thesis-tracker", "asset.journal-glow" }, new[] { "state.lune.tagged-relic", "state.global.spoiler-mode" }, false),
            ["ui.lune.journal-page"] = new OverlayDef("ui.lune.journal-page", "lune", "bubble", "When Lune recovers the tagged Parents' Journal (trigger.parents-journal), one page of her parents' notes opens in an original-text bubble before her reaction, bark.lune.06. Example safe text: 'Expedition 46. The route is charted as far as this forest, and the Monolith is closer than it looks. Whoever finds this: keep going, and keep better notes than we did.'", true, new[] { "asset.bubble-frame", "asset.journal-glow" }, new[] { "state.lune.tagged-relic" }, false),
            ["ui.monoco.wheel"] = new OverlayDef("ui.monoco.wheel", "monoco", "tracker", "The public five-slot Bestial Wheel: each foot (Agile, Caster, Balanced, Heavy, Almighty) with the faction it came from, the count of different factions, and Almighty locked until Act III. Each foot snaps on with a Gestral cheer, a rebirth plays a quick Sacred River fade, and his portrait wears the current mood's mask.", true, new[] { "asset.wheel-frame", "asset.monoco-masks", "asset.sfx.gestral-cheer" }, new[] { "state.monoco.feet" }, false),
            ["ui.monoco.ending"] = new OverlayDef("ui.monoco.ending", "monoco", "screen", "Monoco's ending card when The Bestial Wheel is declared: the wheel spinning on Almighty, then a quiet moment with his friend Noco by the Sacred River, under an original-text ending. Safe and finished modes show the same card, since it holds no ending spoiler.", true, new[] { "asset.vignette-frame", "asset.portrait.monoco", "asset.wheel-frame", "asset.monoco-masks", "asset.sacred-river" }, new[] { "state.monoco.feet", "state.global.spoiler-mode" }, false),
            ["ui.curator.cell-crack"] = new OverlayDef("ui.curator.cell-crack", "curator", "token", "A hairline crack on the Monolith from setup, doing nothing until Act III. At Act III it splits open into a real Duchy tunnel; in finished mode his music swells as his face is revealed.", true, new[] { "asset.cell-crack", "asset.stinger.curator-reveal" }, new[] { "state.curator.cell-crack" }, false),
            ["ui.curator.ending"] = new OverlayDef("ui.curator.ending", "curator", "screen", "The Curator's ending card when Curtain Call is declared. Finished mode: red petals drifting over Lumière. Safe mode: a plain card with his faceless portrait, the title and an original-text ending, and no petals, because red petals over Lumière would tell a safe player that the Curator is behind the Gommage.", true, new[] { "asset.vignette-frame", "asset.portrait.curator", "asset.portrait.curator-revealed", "asset.petals" }, new[] { "state.global.spoiler-mode" }, false),
            ["ui.clea.coverage"] = new OverlayDef("ui.clea.coverage", "clea", "tracker", "The public coverage tracker: the clearings holding her Nevrons (out of 8, each marked on the map; guard warriors she hosts on Esquie's rocks do not count), whether the Monolith is one of them, and whether the Flying Manor has her atelier.", true, new[] { "asset.tracker-frame", "asset.nevron-mark" }, new[] { "state.esquie.rocks" }, false),
            ["ui.clea.ending"] = new OverlayDef("ui.clea.ending", "clea", "screen", "Clea's ending card when the Nevron Tide is declared: a map thick with Nevrons and a thin crack of chroma draining out of the Monolith, under an original-text ending. Finished mode only: Clea is never seated in safe mode, so there is no safe card.", true, new[] { "asset.vignette-frame", "asset.portrait.clea", "asset.nevron-mark" }, new[] { "state.global.spoiler-mode" }, false),
            ["ui.clea.fx"] = new OverlayDef("ui.clea.fx", "clea", "token", "Converted pieces melt into Nevron shapes (asset.fx.clea-melt), her Nevron sprites change with each region (asset.nevron-region-sprites), and the Flying Manor corner floats on its ring of rocks (asset.fx.flying-manor-float). Finished mode only, since Clea is never seated in safe mode.", true, new[] { "asset.fx.clea-melt", "asset.nevron-region-sprites", "asset.fx.flying-manor-float" }, new[] { "state.global.roles" }, false),
            ["ui.white-haired-man.ring"] = new OverlayDef("ui.white-haired-man.ring", "white-haired-man", "tracker", "A ring around the Monolith with one segment per Ring clearing, lit where he holds it (his face-up Barrier, or one of his pieces with no ruler but him or the Paintress), plus the Monolith's own status. Face-up Barriers shimmer. With the optional v1.1 Monolith Barrier it also shows whether the Barrier is down.", true, new[] { "asset.ring-barrier" }, new[] { "state.global.roles", "state.white-haired-man.barrier-down" }, false),
            ["ui.white-haired-man.ending"] = new OverlayDef("ui.white-haired-man.ending", "white-haired-man", "screen", "The White-Haired Man's ending card when Nobody Reaches Her is declared: the Monolith wrapped in his barrier, with every expedition stalled on the shore, under an original-text ending. Safe and finished modes show the same card, since it holds no ending spoiler.", true, new[] { "asset.vignette-frame", "asset.portrait.white-haired-man", "asset.ring-barrier" }, new[] { "state.global.spoiler-mode" }, false),
            ["ui.white-haired-man.fx"] = new OverlayDef("ui.white-haired-man.fx", "white-haired-man", "token", "His Massacre (Bomb) plots play an ink-wipe massacre on the shore (asset.fx.whm-ink-wipe). Same in safe and finished mode.", true, new[] { "asset.fx.whm-ink-wipe" }, Array.Empty<string>(), false),
        };

        public static readonly IReadOnlyDictionary<string, BarkDef> Barks = new Dictionary<string, BarkDef>
        {
            ["bark.gustave.01"] = new BarkDef("bark.gustave.01", "gustave", "trigger.game-start", "safe", "Thirty-two, one year left, and now the whole world takes turns. Fine. I'll make mine count.", null, true),
            ["bark.gustave.02"] = new BarkDef("bark.gustave.02", "gustave", "trigger.idle", "safe", "I've measured this forest twice and it moved in between. Who paints a continent and then shuffles it?", null, true),
            ["bark.gustave.03"] = new BarkDef("bark.gustave.03", "gustave", "trigger.flag-planted", "safe", "Every flag's a note to the next crew: road's open, keep walking.", null, true),
            ["bark.gustave.04"] = new BarkDef("bark.gustave.04", "gustave", "trigger.flag-planted", "safe", "Another flag. If the next crew finds a straight road, they can thank me. If it's crooked, blame the dice.", null, true),
            ["bark.gustave.05"] = new BarkDef("bark.gustave.05", "gustave", "trigger.turn-start", "safe", "Whoever painted this world gave it rules, a turn order and a scoring track. Very tidy. I'd still like a word with them.", null, true),
            ["bark.gustave.06"] = new BarkDef("bark.gustave.06", "gustave", "trigger.arm-full", "safe", "Three pips. The arm's humming like the workshop the night before a deadline.", null, true),
            ["bark.gustave.07"] = new BarkDef("bark.gustave.07", "gustave", "trigger.overcharge", "safe", "Overcharging. Everybody stand clear of the engineer.", null, true),
            ["bark.gustave.08"] = new BarkDef("bark.gustave.08", "gustave", "trigger.goal-move", "safe", "Next stop on the road is right there. I want a workshop standing in it by nightfall.", null, true),
            ["bark.gustave.09"] = new BarkDef("bark.gustave.09", "gustave", "trigger.countdown-announced", "safe", "The road reaches the Monolith's doorstep. Break it before morning, or I'm knocking.", null, true),
            ["bark.gustave.10"] = new BarkDef("bark.gustave.10", "gustave", "trigger.countdown-stopped", "safe", "Somebody pulled up my flag. Fine. Engineers rebuild.", null, true),
            ["bark.gustave.11"] = new BarkDef("bark.gustave.11", "gustave", "trigger.attacked", "safe", "You picked a fight with an engineer. I'll be taking notes on your weak points.", null, true),
            ["bark.gustave.12"] = new BarkDef("bark.gustave.12", "gustave", "trigger.act2-start", "safe", "Halfway across the year. The number's lower, the road's longer, and I packed spare bolts.", null, true),
            ["bark.gustave.13"] = new BarkDef("bark.gustave.13", "gustave", "trigger.win", "safe", "Camp pitched at the Monolith's doorstep, flags all the way home. Tell Lumière to come and see.", null, true),
            ["bark.gustave.14"] = new BarkDef("bark.gustave.14", "gustave", "trigger.loss", "safe", "Next expedition, then. Somebody write down where the road went.", null, true),
            ["bark.gustave.15"] = new BarkDef("bark.gustave.15", "gustave", "trigger.canvas-truth", "safe", "Whoever painted this world has been at it for a very long game night. Somebody should check the clock.", null, true),
            ["bark.gustave.16"] = new BarkDef("bark.gustave.16", "gustave", "trigger.canvas-truth", "finished", "Somebody's mother has been playing too many board games, and we're the pieces. I'd still like to see her rulebook.", "bark.gustave.15", true),
            ["bark.esquie.01"] = new BarkDef("bark.esquie.01", "esquie", "trigger.game-start", "safe", "Wheee! Somebody painted squares on the whole world! I'm much too round for squares.", null, true),
            ["bark.esquie.02"] = new BarkDef("bark.esquie.02", "esquie", "trigger.decoy-found", "safe", "Hmm! This rock is much too grumpy to be Florrie. Florrie is never grumpy.", null, true),
            ["bark.esquie.03"] = new BarkDef("bark.esquie.03", "esquie", "trigger.idle", "safe", "Everyone takes turns now! I like turns. Turns are like waiting, but with a schedule.", null, true),
            ["bark.esquie.04"] = new BarkDef("bark.esquie.04", "esquie", "trigger.goal-move", "safe", "Ooh, I think a rock is waiting over there. Hello, rock! I'm coming! Slowly!", null, true),
            ["bark.esquie.05"] = new BarkDef("bark.esquie.05", "esquie", "trigger.rock-claimed", "safe", "Found you! In you go, safe and snug in the Big Belly.", null, true),
            ["bark.esquie.06"] = new BarkDef("bark.esquie.06", "esquie", "trigger.rock-claimed", "safe", "One more friend home! My ring is getting all sparkly.", null, true),
            ["bark.esquie.07"] = new BarkDef("bark.esquie.07", "esquie", "trigger.guards-attacked", "safe", "My friends are here! Thank you, thank you! Please be gentle with the guards.", null, true),
            ["bark.esquie.08"] = new BarkDef("bark.esquie.08", "esquie", "trigger.attacked", "safe", "Oof! That tickles. Not the fun kind of tickle.", null, true),
            ["bark.esquie.09"] = new BarkDef("bark.esquie.09", "esquie", "trigger.rival-countdown", "safe", "Uh-oh, somebody's about to win! I'll go stand somewhere big and round and in the way.", null, true),
            ["bark.esquie.10"] = new BarkDef("bark.esquie.10", "esquie", "trigger.act2-start", "act2", "Shh! Somewhere in the old city, a rock is snoring. I can hear it!", null, true),
            ["bark.esquie.11"] = new BarkDef("bark.esquie.11", "esquie", "trigger.soarrie-handoff", "act2", "Soarrie! You were with Mister Verso all along? You sneaky, floaty rock!", null, true),
            ["bark.esquie.12"] = new BarkDef("bark.esquie.12", "esquie", "trigger.win", "safe", "All four rocks, all home! Everybody climb on and hold tight. We're going for a dive!", null, true),
            ["bark.esquie.13"] = new BarkDef("bark.esquie.13", "esquie", "trigger.canvas-truth", "safe", "Whoever painted this world sure loves a long game! That's okay. I'm the MOST patient.", null, true),
            ["bark.esquie.14"] = new BarkDef("bark.esquie.14", "esquie", "trigger.canvas-truth", "finished", "Mister Verso says his mama has been playing too many board games. That's okay! I'm a VERY good piece.", "bark.esquie.13", true),
            ["bark.paintress.01"] = new BarkDef("bark.paintress.01", "paintress", "trigger.countdown-announced", "safe", "Hold still, darling. You're in the foreground.", null, true),
            ["bark.paintress.02"] = new BarkDef("bark.paintress.02", "paintress", "trigger.easel-raised", "safe", "Three easels, three faces I miss. Touch them and I'll paint you smaller.", null, true),
            ["bark.paintress.03"] = new BarkDef("bark.paintress.03", "paintress", "trigger.game-start", "safe", "Squares, turns, little wooden figures. If this is how the world must be painted now, I will paint it carefully.", null, true),
            ["bark.paintress.04"] = new BarkDef("bark.paintress.04", "paintress", "trigger.idle", "safe", "The number on the Monolith follows your scores now. Play well, and watch it fall.", null, true),
            ["bark.paintress.05"] = new BarkDef("bark.paintress.05", "paintress", "trigger.goal-move", "safe", "That clearing needs a little more of me in it. An easel, I think.", null, true),
            ["bark.paintress.06"] = new BarkDef("bark.paintress.06", "paintress", "trigger.portrait-broken", "safe", "You've smudged a portrait. I'll start another. I always do.", null, true),
            ["bark.paintress.07"] = new BarkDef("bark.paintress.07", "paintress", "trigger.grief", "safe", "The colours won't hold. Give me a moment.", null, true),
            ["bark.paintress.08"] = new BarkDef("bark.paintress.08", "paintress", "trigger.attacked", "safe", "Mind the canvas. The paint is still wet.", null, true),
            ["bark.paintress.09"] = new BarkDef("bark.paintress.09", "paintress", "trigger.countdown-stopped", "safe", "A ruined easel. I'll set up another and begin again.", null, true),
            ["bark.paintress.10"] = new BarkDef("bark.paintress.10", "paintress", "trigger.win", "safe", "Finished. Hold still, everyone, and let it dry.", null, true),
            ["bark.paintress.11"] = new BarkDef("bark.paintress.11", "paintress", "trigger.canvas-truth", "safe", "One more round. The light is good, and the canvas isn't finished.", null, true),
            ["bark.paintress.12"] = new BarkDef("bark.paintress.12", "paintress", "trigger.canvas-truth", "finished", "Your father says I've played too many rounds. One more. Just one more.", "bark.paintress.11", true),
            ["bark.sciel.01"] = new BarkDef("bark.sciel.01", "sciel", "trigger.idle", "safe", "I foretold rain today. I did not foretell rabbits with opinions.", null, true),
            ["bark.sciel.02"] = new BarkDef("bark.sciel.02", "sciel", "trigger.aquafarm-raised", "safe", "The Aquafarm fed half of Lumière. This field can feed the other half.", null, true),
            ["bark.sciel.03"] = new BarkDef("bark.sciel.03", "sciel", "trigger.turn-start", "safe", "Whoever's painting this world has let game night run a little long.", null, true),
            ["bark.sciel.04"] = new BarkDef("bark.sciel.04", "sciel", "trigger.game-start", "safe", "New board, same job: keep the young ones out of harm's way.", null, true),
            ["bark.sciel.05"] = new BarkDef("bark.sciel.05", "sciel", "trigger.sanctuary-count", "safe", "Another Lantern lit and nobody trampling the crops. Don't worry, I'm counting.", null, true),
            ["bark.sciel.06"] = new BarkDef("bark.sciel.06", "sciel", "trigger.goal-move", "safe", "That clearing has been noisy. I think it needs a Lantern and a little peace.", null, true),
            ["bark.sciel.07"] = new BarkDef("bark.sciel.07", "sciel", "trigger.countdown-announced", "safe", "Every Lantern's lit. If you want them out, you'll have to come and put them out yourselves.", null, true),
            ["bark.sciel.08"] = new BarkDef("bark.sciel.08", "sciel", "trigger.attacked", "safe", "Those were seedlings. You can pay the farmer on your way out.", null, true),
            ["bark.sciel.09"] = new BarkDef("bark.sciel.09", "sciel", "trigger.countdown-stopped", "safe", "One Lantern down. I'll light it again. That's what Lanterns are for.", null, true),
            ["bark.sciel.10"] = new BarkDef("bark.sciel.10", "sciel", "trigger.act2-start", "safe", "Half the year gone. I'll plant what I can while there's still light.", null, true),
            ["bark.sciel.11"] = new BarkDef("bark.sciel.11", "sciel", "trigger.win", "safe", "Twilight on the Aquafarm, a full harvest, and the children of Lumière watching from the shore. That's a good year.", null, true),
            ["bark.verso.01"] = new BarkDef("bark.verso.01", "verso", "trigger.idle", "safe", "I can't die, I can't leave, and now I have to wait for my turn.", null, true),
            ["bark.verso.02"] = new BarkDef("bark.verso.02", "verso", "trigger.rank-s", "safe", "Rank S. Please don't cheer. The moment I get proud, something hits me.", null, true),
            ["bark.verso.03"] = new BarkDef("bark.verso.03", "verso", "trigger.game-start", "safe", "A whole world laid out on a board. I've seen stranger things. Not many.", null, true),
            ["bark.verso.04"] = new BarkDef("bark.verso.04", "verso", "trigger.rank-up", "safe", "Up a letter. Keep it quiet; luck hears everything.", null, true),
            ["bark.verso.05"] = new BarkDef("bark.verso.05", "verso", "trigger.rank-down", "safe", "And there goes the letter. Nobody saw that.", null, true),
            ["bark.verso.06"] = new BarkDef("bark.verso.06", "verso", "trigger.goal-move", "safe", "That one's alone and slow. A clean fight. I'll take it.", null, true),
            ["bark.verso.07"] = new BarkDef("bark.verso.07", "verso", "trigger.countdown-announced", "safe", "Standing in the Monolith at S. Anyone who wants a different ending has one turn to land a hit.", null, true),
            ["bark.verso.08"] = new BarkDef("bark.verso.08", "verso", "trigger.attacked", "safe", "Go ahead. I always get back up. It's the getting up that stings.", null, true),
            ["bark.verso.09"] = new BarkDef("bark.verso.09", "verso", "trigger.soarrie-handoff", "act2", "Here, old friend. It's been floating in my pocket all year. Fly safe.", null, true),
            ["bark.verso.10"] = new BarkDef("bark.verso.10", "verso", "trigger.act3-start", "act2", "The last act. I know how stories like this end. Mostly.", null, true),
            ["bark.verso.11"] = new BarkDef("bark.verso.11", "verso", "trigger.win", "safe", "Quiet in here. I could get used to quiet.", null, true),
            ["bark.verso.12"] = new BarkDef("bark.verso.12", "verso", "trigger.loss", "safe", "Well played. I'll be here next time. I'm always here.", null, true),
            ["bark.verso.13"] = new BarkDef("bark.verso.13", "verso", "trigger.canvas-truth", "safe", "Whoever painted this world has been at the table a long time. At some point the pieces get to go home.", null, true),
            ["bark.verso.14"] = new BarkDef("bark.verso.14", "verso", "trigger.canvas-truth", "finished", "Mother's been at this table for decades. At some point you let the pieces go home.", "bark.verso.13", true),
            ["bark.maelle.01"] = new BarkDef("bark.maelle.01", "maelle", "trigger.game-start", "safe", "Sixteen, and it turns out the whole world is somebody's board game. That explains a lot.", null, true),
            ["bark.maelle.02"] = new BarkDef("bark.maelle.02", "maelle", "trigger.idle", "safe", "Everyone keeps asking what suit I am. I'm sixteen! I don't know what suit I am!", null, true),
            ["bark.maelle.03"] = new BarkDef("bark.maelle.03", "maelle", "trigger.relationship-step", "safe", "That's one more person who'd save me a seat at dinner. I'm keeping a list.", null, true),
            ["bark.maelle.04"] = new BarkDef("bark.maelle.04", "maelle", "trigger.stance-change", "safe", "Feet planted, blade up. Your move.", null, true),
            ["bark.maelle.05"] = new BarkDef("bark.maelle.05", "maelle", "trigger.goal-move", "safe", "Back to Lumière. For once, I'd like to be home.", null, true),
            ["bark.maelle.06"] = new BarkDef("bark.maelle.06", "maelle", "trigger.countdown-announced", "safe", "I'm home, my friends are on my side, and my blade is sharp. Come and move me if you dare.", null, true),
            ["bark.maelle.07"] = new BarkDef("bark.maelle.07", "maelle", "trigger.attacked", "safe", "You'll have to get past the rapier first.", null, true),
            ["bark.maelle.08"] = new BarkDef("bark.maelle.08", "maelle", "trigger.act3-start", "safe", "A memory just knocked. I'm not answering yet.", null, true),
            ["bark.maelle.09"] = new BarkDef("bark.maelle.09", "maelle", "trigger.act3-start", "finished", "The name was always under the paint. Alicia. Hello again.", "bark.maelle.08", true),
            ["bark.maelle.10"] = new BarkDef("bark.maelle.10", "maelle", "trigger.win", "safe", "Home, with my family around me. It took a whole board game, but here we are.", null, true),
            ["bark.maelle.11"] = new BarkDef("bark.maelle.11", "maelle", "trigger.canvas-truth", "safe", "Whoever painted this world plays like they've never lost a game. I'd like a word. Or a rematch.", null, true),
            ["bark.maelle.12"] = new BarkDef("bark.maelle.12", "maelle", "trigger.canvas-truth", "finished", "Wait. If she's my mother, who taught her to play like THIS?", "bark.maelle.11", true),
            ["bark.lune.01"] = new BarkDef("bark.lune.01", "lune", "trigger.idle", "safe", "My parents charted this ridge. It was not a ridge then. It was a lake. With otters.", null, true),
            ["bark.lune.02"] = new BarkDef("bark.lune.02", "lune", "trigger.game-start", "safe", "Twelve clearings, three suits, perfectly balanced. Nature doesn't do that. Someone with a rulebook does.", null, true),
            ["bark.lune.03"] = new BarkDef("bark.lune.03", "lune", "trigger.turn-start", "act2", "Filed under 'Paintress, motives of': grief, regret, and apparently a strategy game.", null, true),
            ["bark.lune.04"] = new BarkDef("bark.lune.04", "lune", "trigger.turn-start", "safe", "Whoever painted this world wrote the rules down first. I would love to read the margins.", null, true),
            ["bark.lune.05"] = new BarkDef("bark.lune.05", "lune", "trigger.relic-recovered", "safe", "Recovered and catalogued. My parents would have argued with me about the date.", null, true),
            ["bark.lune.06"] = new BarkDef("bark.lune.06", "lune", "trigger.parents-journal", "safe", "Their handwriting. Give me a moment. ...Right. Back to work.", null, true),
            ["bark.lune.07"] = new BarkDef("bark.lune.07", "lune", "trigger.goal-move", "safe", "The gold forest by Sirène. Escort of two, minimum. I am not losing these notes to a raid.", null, true),
            ["bark.lune.08"] = new BarkDef("bark.lune.08", "lune", "trigger.attacked", "safe", "Mind the convoy. Those are primary sources.", null, true),
            ["bark.lune.09"] = new BarkDef("bark.lune.09", "lune", "trigger.win", "safe", "Chart complete. The Monolith is circled, annotated and, frankly, overdue.", null, true),
            ["bark.lune.10"] = new BarkDef("bark.lune.10", "lune", "trigger.canvas-truth", "safe", "Revised thesis: whoever painted this world is very, very fond of board games. Peer review pending.", null, true),
            ["bark.lune.11"] = new BarkDef("bark.lune.11", "lune", "trigger.canvas-truth", "finished", "Revised thesis: a grieving mother, a family quarrel, and far too many board games. Peer review pending.", "bark.lune.10", true),
            ["bark.monoco.01"] = new BarkDef("bark.monoco.01", "monoco", "trigger.goal-move", "safe", "I would like your feet. Respectfully.", null, true),
            ["bark.monoco.02"] = new BarkDef("bark.monoco.02", "monoco", "trigger.mask-change", "safe", "Mask changed! Today I am Heavy. Please mind the stairs.", null, true),
            ["bark.monoco.03"] = new BarkDef("bark.monoco.03", "monoco", "trigger.game-start", "safe", "Somebody painted us all into a board game? Wonderful. Which piece may I bite first?", null, true),
            ["bark.monoco.04"] = new BarkDef("bark.monoco.04", "monoco", "trigger.foot-earned", "safe", "A new foot for the wheel! Thank you, thank you. I will take very good care of it.", null, true),
            ["bark.monoco.05"] = new BarkDef("bark.monoco.05", "monoco", "trigger.rebirth", "safe", "The river again. I remember... most of it. Splendid, let us begin again!", null, true),
            ["bark.monoco.06"] = new BarkDef("bark.monoco.06", "monoco", "trigger.countdown-announced", "safe", "Five feet, five masks, the whole wheel spinning! Come and duel me before I finish dancing.", null, true),
            ["bark.monoco.07"] = new BarkDef("bark.monoco.07", "monoco", "trigger.attacked", "safe", "Oh! A challenger! Splendid, splendid.", null, true),
            ["bark.monoco.08"] = new BarkDef("bark.monoco.08", "monoco", "trigger.rival-countdown", "safe", "Someone is about to win? Then someone owes me a duel first.", null, true),
            ["bark.monoco.09"] = new BarkDef("bark.monoco.09", "monoco", "trigger.win", "safe", "The wheel is full. Now, a quiet walk by the river with a friend.", null, true),
            ["bark.monoco.10"] = new BarkDef("bark.monoco.10", "monoco", "trigger.canvas-truth", "safe", "Whoever painted this world loves games as much as I love duels. Good taste!", null, true),
            ["bark.monoco.11"] = new BarkDef("bark.monoco.11", "monoco", "trigger.canvas-truth", "finished", "Esquie says somebody's mother has been playing too many board games. Too many? There is no such thing!", "bark.monoco.10", true),
            ["bark.curator.01"] = new BarkDef("bark.curator.01", "curator", "trigger.act3-start", "safe", "Every game ends eventually. I'm simply ending this one on purpose.", null, true),
            ["bark.curator.02"] = new BarkDef("bark.curator.02", "curator", "trigger.idle", "safe", "I'm not the villain of this game. I'm the one who wants it to end.", null, true),
            ["bark.curator.03"] = new BarkDef("bark.curator.03", "curator", "trigger.game-start", "safe", "I'll be at the camp, sharpening things. Bring me your blades.", null, true),
            ["bark.curator.04"] = new BarkDef("bark.curator.04", "curator", "trigger.quiet-helper", "safe", "A small adjustment to your weapon. Don't thank me. Keep swinging.", null, true),
            ["bark.curator.05"] = new BarkDef("bark.curator.05", "curator", "trigger.goal-move", "safe", "Patience. The pieces are nearly where they need to be.", null, true),
            ["bark.curator.06"] = new BarkDef("bark.curator.06", "curator", "trigger.countdown-announced", "safe", "Lumière is mine to close. One more turn, and the curtain falls.", null, true),
            ["bark.curator.07"] = new BarkDef("bark.curator.07", "curator", "trigger.attacked", "safe", "Break my camp and I lose a contact. Is that really worth your turn?", null, true),
            ["bark.curator.08"] = new BarkDef("bark.curator.08", "curator", "trigger.win", "safe", "The curtain is down. Thank you all for playing.", null, true),
            ["bark.curator.09"] = new BarkDef("bark.curator.09", "curator", "trigger.canvas-truth", "safe", "Whoever painted this world should put the brush down. Some games should not last this long.", null, true),
            ["bark.curator.10"] = new BarkDef("bark.curator.10", "curator", "trigger.canvas-truth", "finished", "Aline. Put the brush down. The children are watching you play.", "bark.curator.09", true),
            ["bark.clea.01"] = new BarkDef("bark.clea.01", "clea", "trigger.coverage-count", "safe", "Another Nevron. Perfect? No. Next.", null, true),
            ["bark.clea.02"] = new BarkDef("bark.clea.02", "clea", "trigger.idle", "safe", "Some paint families. I paint teeth.", null, true),
            ["bark.clea.03"] = new BarkDef("bark.clea.03", "clea", "trigger.convert", "safe", "Now that is a perfect specimen. Hold still while the paint sets.", null, true),
            ["bark.clea.04"] = new BarkDef("bark.clea.04", "clea", "trigger.game-start", "safe", "A board, a manor, and plenty of empty clearings. I can work with that.", null, true),
            ["bark.clea.05"] = new BarkDef("bark.clea.05", "clea", "trigger.coverage-count", "safe", "Another clearing with teeth in it. The tide is coming in.", null, true),
            ["bark.clea.06"] = new BarkDef("bark.clea.06", "clea", "trigger.goal-move", "safe", "That clearing has no Nevrons in it. Let's fix that.", null, true),
            ["bark.clea.07"] = new BarkDef("bark.clea.07", "clea", "trigger.countdown-announced", "safe", "Nevrons on every road and one at the Monolith's foot. By morning there won't be a colour left to save.", null, true),
