            ["bark.clea.10"] = new BarkDef("bark.clea.10", "clea", "trigger.canvas-truth", "finished", "She's been playing pretend in Verso's room for years. Somebody has to flip the board.", "bark.clea.09", true),
            ["bark.white-haired-man.01"] = new BarkDef("bark.white-haired-man.01", "white-haired-man", "trigger.monolith-approach", "safe", "Turn back. She is resting.", null, true),
            ["bark.white-haired-man.02"] = new BarkDef("bark.white-haired-man.02", "white-haired-man", "trigger.game-start", "safe", "Expedition Thirty-Three. Next year, Thirty-Two. That's arithmetic, not cruelty.", null, true),
            ["bark.white-haired-man.03"] = new BarkDef("bark.white-haired-man.03", "white-haired-man", "trigger.battle-won", "safe", "She keeps painting new players into the game. I keep taking them off the board.", null, true),
            ["bark.white-haired-man.04"] = new BarkDef("bark.white-haired-man.04", "white-haired-man", "trigger.idle", "safe", "Whoever painted this world made it a game of turns. Fine. I have always been patient at doors.", null, true),
            ["bark.white-haired-man.05"] = new BarkDef("bark.white-haired-man.05", "white-haired-man", "trigger.goal-move", "safe", "The shore road needs a closer watch. I'll be there before you are.", null, true),
            ["bark.white-haired-man.06"] = new BarkDef("bark.white-haired-man.06", "white-haired-man", "trigger.countdown-announced", "safe", "Every road to the Monolith is closed. You have one turn to find a way through. You won't.", null, true),
            ["bark.white-haired-man.07"] = new BarkDef("bark.white-haired-man.07", "white-haired-man", "trigger.attacked", "safe", "Bold. Most expeditions turn back long before this.", null, true),
            ["bark.white-haired-man.08"] = new BarkDef("bark.white-haired-man.08", "white-haired-man", "trigger.act2-start", "safe", "The second act. My blade feels heavier. Not slower.", null, true),
            ["bark.white-haired-man.09"] = new BarkDef("bark.white-haired-man.09", "white-haired-man", "trigger.win", "safe", "Nobody reached her. Nobody ever does.", null, true),
            ["bark.white-haired-man.10"] = new BarkDef("bark.white-haired-man.10", "white-haired-man", "trigger.canvas-truth", "safe", "Whoever painted this world never leaves a game unfinished. Neither do I.", null, true),
            ["bark.white-haired-man.11"] = new BarkDef("bark.white-haired-man.11", "white-haired-man", "trigger.canvas-truth", "finished", "Your mother never could leave a game unfinished. I should know. I'm one of her pieces.", "bark.white-haired-man.10", true),
