        public static readonly IReadOnlyDictionary<string, OptionDef> Options = new Dictionary<string, OptionDef>
        {
            ["opt.spoiler-mode"] = new OptionDef("opt.spoiler-mode", "Spoiler mode", new[] { "safe", "finished" }, "safe", "Asked on first launch: 'Spoiler-safe' (safe) or 'I've finished Clair Obscur: Expedition 33' (finished). Safe uses neutral names (The Paintress, The Curator, The White-Haired Man, Maelle, Verso, and '???' for Clea), locks Clea, never fires a 'mother' line and skips the Beach vignette and the ending-flavoured win vignettes. Finished unlocks true names and lines, but the true 'mother' lines still fire only in the mod's Act III. It can be changed later in the mod's settings and applies from the next game."),
            ["opt.difficulty"] = new OptionDef("opt.difficulty", "Bot difficulty", new[] { "easy", "normal", "hard" }, "normal", "Applies to every bot seat and is chosen when a game is set up. It sets when bots switch from VP play to goal mode, how well they guard their key pieces and how hard they block other players' themed wins. It never changes win thresholds, with one human-only exception: on Easy, a human Verso qualifies at rank A with 2 undamaged swords. Bots never get easy assists, so an Easy bot is never better at winning than a Normal one."),
            ["opt.faithful-gustave"] = new OptionDef("opt.faithful-gustave", "Faithful Gustave", new[] { "off", "on" }, "off", "Finished mode only; hidden and treated as off in safe mode. On: from Act II, Gustave's seat is retitled 'Expedition 33', the survivors carrying his flag, with the same engine, flags, gauge and win, and the Beach vignette plays as that retitle. Off: the Beach plays as a what-if ('This time, the arm held.'). The seat never changes faction, because Root cannot swap a seat's faction mid-game."),
            ["opt.campaign"] = new OptionDef("opt.campaign", "Campaign", new[] { "off", "on" }, "off", "Off is Free Play, with no restrictions. On: a campaign of three linked games, Act I (suggested lead Gustave), Act II (Verso) and Act III (Maelle or the Curator). Losing never ends the campaign, because the next expedition carries on: the player gets the last expedition's journal, worth +1 card in the next game."),
            ["opt.monolith-barrier"] = new OptionDef("opt.monolith-barrier", "Monolith Barrier (v1.1)", new[] { "off", "on" }, "off", "Optional v1.1 table rule. On: no battle may start in the Monolith until Visages and Sirène have both been ruled at the end of the same turn by seats other than the White-Haired Man and the Paintress; once that happens the Barrier is down for the rest of the game. Off: Monolith battles follow normal Root rules."),
        };

